TEST(PlayableServicePartition, IndependentOwnersKeepOneStableLeaseEach) {
    harken::EnginePlayablePartitionPool pool(2);
    const harken::EnginePlayableServiceToken first{9, 3};
    const harken::EnginePlayableServiceToken second{2, 7};
    const auto a = pool.Reserve(first);
    const auto b = pool.Reserve(second);
    ASSERT_TRUE(a.Valid());
    ASSERT_TRUE(b.Valid());
    EXPECT_NE(a.slot, b.slot);
    EXPECT_NE(first.slot, a.slot);
    EXPECT_TRUE(pool.Owns(a, first));
    EXPECT_FALSE(pool.Owns(a, second));
    EXPECT_FALSE(pool.Reserve(first).Valid());
    EXPECT_FALSE(pool.Reserve({4, 8}).Valid());
    EXPECT_EQ(2u, pool.OccupiedCount());
    ASSERT_TRUE(pool.Cancel(a, first));
    const harken::EnginePlayableServiceToken reused{9, 4};
    const auto c = pool.Reserve(reused);
    ASSERT_TRUE(c.Valid());
    EXPECT_EQ(a.slot, c.slot);
    EXPECT_NE(a.generation, c.generation);
    EXPECT_FALSE(pool.Owns(a, first));
    EXPECT_FALSE(pool.Owns(c, first));
    EXPECT_TRUE(pool.Owns(b, second));
    EXPECT_TRUE(pool.Cancel(b, second));
    EXPECT_TRUE(pool.Cancel(c, reused));
    EXPECT_EQ(0u, pool.OccupiedCount());
}

TEST(PlayableServicePartition, CommittedLeaseWaitsForStrictlyLaterCompletion) {
    harken::EnginePlayablePartitionPool pool(1);
    const harken::EnginePlayableServiceToken owner{0, 1};
    const auto token = pool.Reserve(owner);
    ASSERT_TRUE(pool.Commit(token, owner));
    EXPECT_FALSE(pool.Cancel(token, owner));
    EXPECT_FALSE(pool.Release(token, owner, 90));
    ASSERT_TRUE(pool.BeginRetirement(token, owner, 90));
    EXPECT_FALSE(pool.Release(token, owner, 89));
    EXPECT_FALSE(pool.Release(token, owner, 90));
    EXPECT_FALSE(pool.Reserve({0, 2}).Valid());
    ASSERT_TRUE(pool.Release(token, owner, 91));
    EXPECT_EQ(0u, pool.OccupiedCount());
    EXPECT_TRUE(pool.Reserve({0, 2}).Valid());
}

constexpr VnObjectId kSound = harkentest::ObjectId(1001);
constexpr VnObjectId kSecondSound = harkentest::ObjectId(1002);
constexpr VnObjectId kThirdSound = harkentest::ObjectId(1003);
constexpr VnObjectId kContainer = harkentest::ObjectId(2001);
constexpr std::uint64_t kContainerRevision = 3001;

void ExpectTreePlaybackRequest(harken::Engine& engine,
                               harken::PlayableInstanceHandle root,
                               const harken::MonitorRequestContext& expected) {
    harken::MonitorEmitterOrigin rootOrigin{};
    ASSERT_TRUE(engine.playableInstances.CaptureEmitterOrigin(root, &rootOrigin));
    ASSERT_NE(harken::MonitorEmitterKind::Unknown, rootOrigin.kind);
    std::vector<harken::PlayableInstanceHandle> members{root};
    for (std::size_t i = 0; i < members.size(); ++i) {
        harken::MonitorEmitterOrigin origin{};
        ASSERT_TRUE(engine.playableInstances.CaptureEmitterOrigin(members[i], &origin));
        EXPECT_EQ(origin.emitter, rootOrigin.emitter);
        EXPECT_EQ(origin.host, rootOrigin.host);
        EXPECT_EQ(origin.kind, rootOrigin.kind);
        EXPECT_EQ(origin.registrationRevision, rootOrigin.registrationRevision);
        harken::MonitorRequestContext actual{};
        ASSERT_TRUE(engine.playableInstances.CapturePlaybackRequest(members[i], &actual));
        EXPECT_EQ(actual.key, expected.key);
        EXPECT_EQ(actual.origin, expected.origin);
        EXPECT_EQ(actual.operation, expected.operation);
        for (auto child = engine.playableInstances.FirstChild(members[i]); child != 0;
             child = engine.playableInstances.NextSibling(child)) members.push_back(child);
    }
    std::uint32_t voices = 0;
    for (std::uint32_t slot = 0; slot < engine.ledger.Capacity(); ++slot) {
        harken::VoiceLedger::MonitorIdentity identity{};
        if (!engine.ledger.CaptureMonitorIdentity(slot, &identity) ||
            std::find(members.begin(), members.end(), identity.parent.internalToken) == members.end()) continue;
        ++voices;
        EXPECT_EQ(identity.playbackRequest.key, expected.key);
        EXPECT_EQ(identity.playbackRequest.origin, expected.origin);
        EXPECT_EQ(identity.emitterOrigin.emitter, rootOrigin.emitter);
        EXPECT_EQ(identity.emitterOrigin.host, rootOrigin.host);
        EXPECT_EQ(identity.emitterOrigin.kind, rootOrigin.kind);
        EXPECT_EQ(identity.emitterOrigin.registrationRevision, rootOrigin.registrationRevision);
    }
    EXPECT_GT(voices, 0u);
}

void ExpectVariableControlNaturallyCompleted(
    harken::Engine& engine, harken::PlayableInstanceHandle instance) {
    for (std::uint32_t block = 0; block < 96; ++block) {
        engine.nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        if (!engine.playableInstances.Classify(instance).live) break;
    }
    EXPECT_FALSE(engine.playableInstances.Classify(instance).live);
    ASSERT_EQ(VN_OK, Vn_Update());
}

struct NotificationCapture {
    std::uint32_t count = 0;
};

struct StopAfterVariableControlSliceClaimContext {
    enum class Intent : std::uint8_t {
        Stop,
        WorldReplacement,
        TransportReset,
    };

    harken::Engine* engine = nullptr;
    harken::PlayableInstanceHandle instance = 0;
    harken::DecisionToken decision{};
    harken::TimelineArmToken arm{};
    harken::ContainerWorldInstallViewV1 replacementWorld{};
    Intent intent = Intent::Stop;
    bool operationAccepted = false;
    std::atomic<bool> invoked{false};
    std::atomic<bool> releaseClaim{false};
    std::atomic<bool> pumpComplete{false};
};

void WaitForConcurrentStopAfterVariableControlSliceClaim(void* opaque) {
    auto& context =
        *static_cast<StopAfterVariableControlSliceClaimContext*>(opaque);
    context.invoked.store(true, std::memory_order_release);
    while (!context.releaseClaim.load(std::memory_order_acquire)) {
        std::this_thread::yield();
    }
}

