        transitionCurves = {
            TransitionFadeCurve(1), TransitionFadeCurve(2)};
        transitionCurves[0].curve.handles[0] = {
            1.0f / 3.0f, 0.0f, 2.0f / 3.0f, 0.0f};
        transitionCurves[1].curve.handles[0] = {
            1.0f / 3.0f, 1.0f, 2.0f / 3.0f, 1.0f};

        harken::PlayableRefV1 secondSound{};
        secondSound.kind = harken::PlayableKindV1::Sound;
        secondSound.stableId = harkentest::ObjectId(kSecondSound);
        secondSound.expectedProgramSemanticFingerprint =
            properties[1].programSemanticFingerprint;
