TEST(PlayableStart, NestedSequenceCreatesIndependentParentedInstances) {
    VnConfig config = harkentest::MakeNullConfig(4, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(session.InitResult(), VN_OK);
    harken::Engine* engine = session.Engine();
    ASSERT_NE(engine, nullptr);

    std::vector<float> samples(4096, 0.25f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(Vn_RegisterPCM(kSound, &pcm), VN_OK);
    const harken::PCMView media = engine->registry.Lookup(kSound);
    ASSERT_TRUE(media.Valid());

    NestedSequenceWorldImage image(media.contentRevision);
    ASSERT_EQ(harken::InstallContainerWorldV1(*engine, image.world).status,
              harken::WorldInstallStatus::Ok);
    harken::PlayableStartRequest request{};
    request.playbackRequest = engine->monitorRequests.Begin(
        harken::MonitorRequestOrigin::StudioPreview, 3);
    request.root = image.Root();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, request);
    ASSERT_EQ(started.status, harken::PlayableStartStatus::Accepted);

    const harken::PlayableInstanceView root =
        engine->playableInstances.Classify(started.instance);
    ASSERT_TRUE(root.live);
    ASSERT_EQ(root.kind, harken::PlayableKind::Container);
    const harken::PlayableInstanceHandle nested = root.firstChild;
    ASSERT_NE(nested, 0u);
    const harken::PlayableInstanceView nestedView =
        engine->playableInstances.Classify(nested);
    ASSERT_TRUE(nestedView.live);
    EXPECT_EQ(nestedView.parent, started.instance);
    EXPECT_EQ(nestedView.kind, harken::PlayableKind::Container);
    const harken::PlayableInstanceHandle sound = nestedView.firstChild;
    ASSERT_NE(sound, 0u);
    const harken::PlayableInstanceView soundView =
        engine->playableInstances.Classify(sound);
    EXPECT_TRUE(soundView.live);
    EXPECT_EQ(soundView.parent, nested);
    EXPECT_EQ(soundView.kind, harken::PlayableKind::Sound);

    harken::MonitorContentIdentity rootContent{}, nestedContent{}, soundContent{};
    ASSERT_TRUE(engine->playableInstances.CaptureContentIdentity(started.instance, &rootContent));
    ASSERT_TRUE(engine->playableInstances.CaptureContentIdentity(nested, &nestedContent));
    ASSERT_TRUE(engine->playableInstances.CaptureContentIdentity(sound, &soundContent));
    EXPECT_EQ(image.Root().stableId, rootContent.stableId);
    EXPECT_EQ(harkentest::ObjectId(2101), nestedContent.stableId);
    EXPECT_EQ(kSound, soundContent.stableId);
    EXPECT_EQ(media.contentRevision, soundContent.contentRevision);
    EXPECT_EQ(engine->variables.CurrentWorldGeneration(), soundContent.worldGeneration);

    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(row, engine->playableServices.end());
    const auto* resource = FrontierServiceForOwner(*engine, nested);
    ASSERT_NE(nullptr, resource);
    EXPECT_EQ(&*row, engine->ResolvePlayableService(resource->parentService));
    EXPECT_EQ(resource->activeLeafInstance, sound);
    EXPECT_EQ(resource->schedule.ownerInstance, sound);
    EXPECT_EQ(resource->schedule.runtimeProgram.programGeneration, sound);
    ExpectTreePlaybackRequest(*engine, started.instance, request.playbackRequest);

    ASSERT_TRUE(PumpUntilAudible(*engine));
    const harken::MonitorControlCause stop{engine->monitorRequests.Begin(
        harken::MonitorRequestOrigin::StudioPreview, 4)};
    ASSERT_EQ(harken::StopPlayable(*engine, started.instance, 10, stop), harken::PlayableControlStatus::Ok);
    const harken::MonitorControlCause repeat{engine->monitorRequests.Begin(
        harken::MonitorRequestOrigin::StudioPreview, 4)};
    ASSERT_EQ(harken::StopPlayable(*engine, started.instance, 10, repeat), harken::PlayableControlStatus::Ok);
    for (const auto handle : {started.instance, nested, sound}) {
        harken::MonitorControlCause captured{};
        ASSERT_TRUE(engine->playableInstances.CaptureControlCause(handle, &captured));
        EXPECT_EQ(captured.request.key, stop.request.key);
    }
    ASSERT_TRUE(StopUntilStale(*engine, started.instance));
    EXPECT_FALSE(engine->playableInstances.Classify(nested).live);
    EXPECT_FALSE(engine->playableInstances.Classify(sound).live);
}

TEST(PlayableStart, NestedSequenceContinuationCreatesAnotherLeafInstance) {
    VnConfig config = harkentest::MakeNullConfig(4, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(session.InitResult(), VN_OK);
    harken::Engine* engine = session.Engine();
    ASSERT_NE(engine, nullptr);
    std::vector<float> samples(4096, 0.25f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(Vn_RegisterPCM(kSound, &pcm), VN_OK);
    const harken::PCMView media = engine->registry.Lookup(kSound);
    ASSERT_TRUE(media.Valid());

    NestedSequenceWorldImage image(media.contentRevision);
    image.SetContainerLoopCount(1, 2);
    ASSERT_EQ(harken::InstallContainerWorldV1(*engine, image.world).status,
              harken::WorldInstallStatus::Ok);
    harken::PlayableStartRequest request{};
    request.playbackRequest = engine->monitorRequests.Begin(
        harken::MonitorRequestOrigin::StudioPreview, 3);
    request.root = image.Root();
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&request.emitter));
    auto& hosts = engine->monitorEmitters;
    const auto firstSession = hosts.BeginSession();
    ASSERT_TRUE(hosts.Register(hosts.EngineInstance(), firstSession, request.emitter, 1,
        harken::MonitorHostOwnership::UnityEmitter, 3));
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, request);
    ASSERT_EQ(started.status, harken::PlayableStartStatus::Accepted);
    const auto root = engine->playableInstances.Classify(started.instance);
    const auto nested = engine->playableInstances.Classify(root.firstChild);
    ASSERT_TRUE(nested.live);
    const auto firstSound = nested.firstChild;
    ASSERT_NE(firstSound, 0u);


    harken::MonitorEmitterOrigin acceptedOrigin{};
    ASSERT_TRUE(engine->playableInstances.CaptureEmitterOrigin(started.instance, &acceptedOrigin));
    ASSERT_EQ(firstSession, acceptedOrigin.host.sdkSession);
    const auto replacementSession = hosts.BeginSession();
    ASSERT_GT(replacementSession, firstSession);
    ASSERT_TRUE(hosts.Register(hosts.EngineInstance(), replacementSession, request.emitter, 1,
        harken::MonitorHostOwnership::UnitySpatialSource, 1));
    ASSERT_TRUE(PumpBlocks(*engine, 120));
    EXPECT_FALSE(engine->playableInstances.Classify(firstSound).live);
    harken::ContainerPlaybackRow current{};
    ASSERT_TRUE(engine->containerPlayback.Capture(root.firstChild, &current));
    const auto secondSound = current.activeChild;
    ASSERT_NE(secondSound, 0u);
    EXPECT_NE(secondSound, firstSound);
    harken::MonitorEmitterOrigin continuedOrigin{};
    ASSERT_TRUE(engine->playableInstances.CaptureEmitterOrigin(secondSound, &continuedOrigin));
    EXPECT_EQ(acceptedOrigin.host, continuedOrigin.host);
    EXPECT_EQ(3u, continuedOrigin.registrationRevision);
    EXPECT_EQ(harken::MonitorHostOwnership::UnityEmitter, continuedOrigin.ownership);
    EXPECT_EQ(replacementSession, hosts.CaptureOrigin(request.emitter).host.sdkSession);
    const auto secondSoundView =
        engine->playableInstances.Classify(secondSound);
    EXPECT_TRUE(secondSoundView.live);
    EXPECT_EQ(secondSoundView.kind, harken::PlayableKind::Sound);
    EXPECT_EQ(secondSoundView.parent, root.firstChild);
    harken::MonitorContentIdentity content{};
    ASSERT_TRUE(engine->playableInstances.CaptureContentIdentity(secondSound, &content));
    EXPECT_EQ(kSound, content.stableId);
    EXPECT_EQ(media.contentRevision, content.contentRevision);
    EXPECT_FALSE(engine->playableInstances.CaptureContentIdentity(firstSound, &content));
    ExpectTreePlaybackRequest(*engine, started.instance, request.playbackRequest);
    ASSERT_TRUE(StopUntilStale(*engine, started.instance));
    EXPECT_EQ(0u, engine->playableInstances.LiveCount());
    EXPECT_EQ(0u, engine->containerPlayback.LiveCount());
}

TEST(PlayableStart,
     NestedSequenceOuterAndInnerLoopTwoCompletesFourSoundsNaturally) {
    harkentest::EngineSession session(harkentest::MakeNullConfig(4, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    std::vector<float> samples(512, 0.25f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &pcm));
    NestedSequenceWorldImage image(
        engine->registry.Lookup(kSound).contentRevision);
    image.SetContainerLoopCount(1, 2);
    image.SetContainerLoopCount(2, 2);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    const auto instanceBaseline = engine->playableInstances.LiveCount();
    const auto containerBaseline = engine->containerPlayback.LiveCount();
    const auto armBaseline = engine->timelineArms.LiveCount();
    const auto voiceBaseline = engine->voices.ActiveCount();
    const auto transactionBaseline = engine->timelinePool.LiveTransactionCount();
    const auto occurrenceBaseline = engine->timelineOccurrences.OccupiedCount();
    const auto compositeBaseline =
        engine->compositeCompletionOwners.OccupiedCount();
    const auto selectionFreeBaseline = engine->selectionMemory.FreeDeltaCount();
    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const auto started = harken::StartPlayable(*engine, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);

    struct ObservedRun {
        harken::PlayableInstanceHandle leaf = 0;
        harken::PlayableInstanceHandle parent = 0;
        harken::TimelineArmToken arm{};
        std::uint64_t audioBaseline = 0;
        std::uint64_t startedSequence = 0;
        std::uint64_t completedSequence = 0;
    };
    std::vector<ObservedRun> runs;
    runs.reserve(4);
    const auto captureAcceptedRun = [&]() {
        const auto* publicRow = FindPlayableRow(*engine, started.instance);
        if (publicRow == nullptr) return;
        for (const auto& service : engine->playableServices) {
        const auto* row = &service;
        if (!row->InvocationValid() || &row->Invocation() != &publicRow->Invocation() ||
            row->activeLeafInstance == 0 ||
            std::any_of(runs.begin(), runs.end(), [&](const auto& run) {
                return run.leaf == row->activeLeafInstance;
            })) {
            continue;
        }
        ASSERT_LT(runs.size(), 8u);
        const auto leaf = engine->playableInstances.Classify(
            row->activeLeafInstance);
        ASSERT_TRUE(leaf.live);
        ASSERT_EQ(harken::PlayableKind::Sound, leaf.kind);
        const auto parent = engine->playableInstances.Classify(leaf.parent);
        ASSERT_TRUE(parent.live);
        ASSERT_EQ(harken::PlayableKind::Container, parent.kind);
        ASSERT_EQ(started.instance, parent.parent);
        ASSERT_EQ(row->activeLeafInstance, row->schedule.ownerInstance);
        ASSERT_EQ(leaf.scheduleEpoch, row->schedule.ownerInstanceScheduleEpoch);
        ASSERT_EQ(row->renderHandle, (static_cast<std::uint64_t>(row->arm.renderGeneration) << 32) |
            row->arm.renderSlot);
        harken::TimelineArmObservation observation{};
        ASSERT_TRUE(engine->timelineArms.Observe(row->arm, &observation));
        ASSERT_EQ(0u, observation.startedBlockSequence);
        ASSERT_EQ(0u, observation.logicalCompletionSequence);
        runs.push_back({row->activeLeafInstance, leaf.parent, row->arm,
                        engine->mixer.BlocksRendered(), 0, 0});
        }
    };
    const auto ownersReclaimed = [&]() {
        return engine->playableInstances.LiveCount() == instanceBaseline &&
            engine->containerPlayback.LiveCount() == containerBaseline &&
            engine->timelineArms.LiveCount() == armBaseline &&
            engine->voices.ActiveCount() == voiceBaseline &&
            engine->timelinePool.LiveTransactionCount() == transactionBaseline &&
            engine->timelineOccurrences.OccupiedCount() == occurrenceBaseline &&
            engine->compositeCompletionOwners.OccupiedCount() == compositeBaseline &&
            engine->selectionMemory.FreeDeltaCount() == selectionFreeBaseline;
    };
    captureAcceptedRun();
    ASSERT_FALSE(HasFatalFailure());
    bool retired = false;
    bool unexpectedReason = false;
    harken::PlayableControlReason lastReason = harken::PlayableControlReason::None;
    std::uint32_t pumped = 0;
    for (; pumped < 512; ++pumped) {
        ASSERT_EQ(VN_OK, Vn_Update());
        captureAcceptedRun();
        ASSERT_FALSE(HasFatalFailure());
        engine->nullBackend.Pump(1);
        // Observe each exact arm before logic can retire it or publish a successor.
        for (auto& run : runs) {
            harken::TimelineArmObservation observation{};
            if (!engine->timelineArms.Observe(run.arm, &observation)) continue;
            if (run.startedSequence == 0 &&
                observation.startedBlockSequence != 0) {
                EXPECT_GT(observation.startedBlockSequence, run.audioBaseline);
                run.startedSequence = observation.startedBlockSequence;
            }
            if (run.completedSequence == 0 &&
                observation.logicalCompletionSequence != 0) {
                EXPECT_NE(0u, run.startedSequence);
                EXPECT_GT(observation.logicalCompletionSequence,
                          run.audioBaseline);
                EXPECT_GE(observation.logicalCompletionSequence,
                          run.startedSequence);
                run.completedSequence = observation.logicalCompletionSequence;
            }
        }
        ASSERT_EQ(VN_OK, Vn_Update());
        captureAcceptedRun();
        ASSERT_FALSE(HasFatalFailure());
        harken::PlayableControlState state{};
        if (harken::QueryPlayable(*engine, started.instance, &state) ==
            harken::PlayableControlStatus::Ok) {
            lastReason = state.reason;
            unexpectedReason = unexpectedReason ||
                (state.reason != harken::PlayableControlReason::None &&
                 state.reason != harken::PlayableControlReason::Natural);
        }
        if (!engine->playableInstances.Classify(started.instance).live &&
            ownersReclaimed() && FindPlayableRow(*engine, started.instance) == nullptr) {
            retired = true;
            break;
        }
    }
    const auto onsetCount = std::count_if(runs.begin(), runs.end(),
        [](const auto& run) { return run.startedSequence != 0; });
    const auto completionCount = std::count_if(runs.begin(), runs.end(),
        [](const auto& run) { return run.completedSequence != 0; });
    std::ostringstream trace;
    trace << "accepted=" << runs.size() << " onsets=" << onsetCount
          << " completions=" << completionCount << " pumped=" << pumped
          << " last_reason=" << static_cast<unsigned>(lastReason);
    for (const auto& run : runs) {
        trace << " [leaf=" << run.leaf << " parent=" << run.parent
              << " arm=" << run.arm.slot << ':' << run.arm.generation
              << " started=" << run.startedSequence
              << " completed=" << run.completedSequence << ']';
    }
    SCOPED_TRACE(trace.str());
    EXPECT_EQ(4u, runs.size());
    EXPECT_EQ(4, onsetCount);
    EXPECT_EQ(4, completionCount);
    if (runs.size() == 4u) {
        EXPECT_EQ(runs[0].parent, runs[1].parent);
        EXPECT_EQ(runs[2].parent, runs[3].parent);
        EXPECT_NE(runs[0].parent, runs[2].parent);
    }
    for (const auto& run : runs) {
        EXPECT_FALSE(engine->playableInstances.Classify(run.leaf).live);
        EXPECT_FALSE(engine->playableInstances.Classify(run.parent).live);
    }
    EXPECT_FALSE(unexpectedReason);
    EXPECT_TRUE(retired);
    EXPECT_FALSE(engine->playableInstances.Classify(started.instance).live);
    EXPECT_EQ(nullptr, FindPlayableRow(*engine, started.instance));
    EXPECT_EQ(instanceBaseline, engine->playableInstances.LiveCount());
    EXPECT_EQ(containerBaseline, engine->containerPlayback.LiveCount());
    EXPECT_EQ(armBaseline, engine->timelineArms.LiveCount());
    EXPECT_EQ(voiceBaseline, engine->voices.ActiveCount());
    EXPECT_EQ(transactionBaseline, engine->timelinePool.LiveTransactionCount());
    EXPECT_EQ(occurrenceBaseline, engine->timelineOccurrences.OccupiedCount());
    EXPECT_EQ(compositeBaseline, engine->compositeCompletionOwners.OccupiedCount());
    EXPECT_EQ(selectionFreeBaseline, engine->selectionMemory.FreeDeltaCount());
    EXPECT_FALSE(engine->runtimeRecreateRequired);
}

TEST(PlayableStart, RecreatedNestedRandomLoopUsesItsIncomingOccurrenceSeed) {
    harkentest::EngineSession session(harkentest::MakeNullConfig(4, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    const std::vector<float> samples(256, 0.5f);
    const auto pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &pcm));
    NestedSequenceWorldImage image(engine->registry.Lookup(kSound).contentRevision);
    image.SetContainerLoopCount(1, 2);
    image.SetContainerLoopCount(2, 2);
    constexpr std::uint32_t kIncoming = 41;
    image.rootChildren[0].stableChildOrdinal = kIncoming;
    std::array<harken::ContainerChildProgramViewV2, 2> children{};
    std::array<harken::PlayableOccurrencePropertyViewV1, 3> occurrences{};
    for (std::uint32_t i = 0; i < children.size(); ++i) {
        children[i] = image.nestedChildren[0];
        children[i].stableChildOrdinal = 7u + 2u * i;
        children[i].authoredStableOrder = i;
        children[i].frequencyWeight = 1;
        occurrences[i] = image.occurrences[0];
        occurrences[i].stableOccurrenceOrdinal = children[i].stableChildOrdinal;
        occurrences[i].occurrenceSemanticFingerprint =
            harken::ComputePlayableOccurrenceFingerprintV1(occurrences[i]);
    }
    occurrences[2] = image.occurrences[1];
    occurrences[2].stableOccurrenceOrdinal = kIncoming;
    occurrences[2].occurrenceSemanticFingerprint =
        harken::ComputePlayableOccurrenceFingerprintV1(occurrences[2]);
    image.containers[0].mode = harken::ContainerModeV1::Random;
    image.containers[0].randomDiscipline = harken::RandomDisciplineV1::Draw;
    image.containers[0].avoidLastN = 0;
    image.containers[0].children = children.data();
    image.containers[0].childCount = children.size();
    image.world.playableOccurrences = occurrences.data();
    image.world.playableOccurrenceCount = occurrences.size();
    image.world.identity.capabilityMask |= harken::kWorldCapabilityRandomDraw;
    image.world.identity.runtimeSemanticFingerprint =
        harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);
    harken::PlayableStartRequest request{};
    request.root = image.Root();
    SelectionInputTrace inputs;
    inputs.Attach(*engine);
    const auto started = harken::StartPlayable(*engine, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    const auto* row = FindPlayableRow(*engine, started.instance);
    ASSERT_NE(nullptr, row);
    harken::SelectionMemoryKeyV1 key{};
    key.world = row->Invocation().worldGeneration;
    key.containerStableId = image.containers[0].containerStableId;
    key.programSemanticFingerprint = image.containers[0].programSemanticFingerprint;
    key.memoryScope = harken::MemoryScopeV1::Global;
    std::vector<std::uint32_t> observedOrdinals;
    for (std::uint32_t block = 0; block < 128; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        inputs.actual.Capture(*engine);
        while (observedOrdinals.size() < inputs.actual.heard.size()) {
            const auto& sound = inputs.actual.heard[observedOrdinals.size()];
            const auto* resource = FrontierServiceForOwner(*engine, sound.parent);
            ASSERT_NE(nullptr, resource);
            ASSERT_EQ(sound.leaf, resource->activeLeafInstance);
            EXPECT_EQ(kIncoming, resource->selectionPath[0].childOrdinal);
            observedOrdinals.push_back(resource->selectedChildOrdinals[1]);
        }
        if (!engine->playableInstances.Classify(started.instance).live) break;
    }
    ASSERT_EQ(4u, inputs.actual.heard.size());
    EXPECT_EQ(inputs.actual.heard[0].parent, inputs.actual.heard[1].parent);
    EXPECT_EQ(inputs.actual.heard[2].parent, inputs.actual.heard[3].parent);
    EXPECT_NE(inputs.actual.heard[0].parent, inputs.actual.heard[2].parent);
    std::size_t ordinal = 0;
    for (const auto& input : inputs.selections) {
        if (input.program != key.containerStableId) continue;
        ASSERT_LT(ordinal, observedOrdinals.size());
        ASSERT_EQ(1u, input.path.size());
        EXPECT_EQ(request.root.stableId, input.path[0].objectId);
        EXPECT_EQ(kIncoming, input.path[0].childOrdinal);
        EXPECT_EQ(kIncoming, input.occurrenceOrdinal);
        EXPECT_EQ(harkentest::ObjectId(0u), input.path[0].trackId);
        EXPECT_EQ(ordinal, input.selectionOrdinal);
        ASSERT_EQ(1u, input.expected.size());
        EXPECT_EQ(input.expected[0], observedOrdinals[ordinal]);
        ++ordinal;
    }
    EXPECT_EQ(4u, ordinal);
    for (const auto& sound : inputs.actual.heard) sound.ExpectNaturalSourceReleased();
    EXPECT_EQ(0u, engine->playableInstances.LiveCount());
    EXPECT_EQ(0u, engine->containerPlayback.LiveCount());
    EXPECT_EQ(0u, engine->timelineArms.LiveCount());
    EXPECT_EQ(0u, engine->voices.ActiveCount());
}

TEST(PlayableStart, NestedContainerIdentityMismatchRejectedBeforeLookup) {
    VnConfig config = harkentest::MakeNullConfig(4, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(session.InitResult(), VN_OK);
    harken::Engine* engine = session.Engine();
    ASSERT_NE(engine, nullptr);

    std::vector<float> samples(4096, 0.25f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(Vn_RegisterPCM(kSound, &pcm), VN_OK);
    const harken::PCMView media = engine->registry.Lookup(kSound);
    ASSERT_TRUE(media.Valid());

    NestedSequenceWorldImage image(media.contentRevision);
    ASSERT_EQ(harken::InstallContainerWorldV1(*engine, image.world).status,
              harken::WorldInstallStatus::Ok);
    // Corrupt only the installed nested child reference. The authority
    // remains live, but the per-edge identity gate must reject the mismatch.
    const auto installed = engine->variables.CurrentPlayableWorld();
    ASSERT_NE(installed.containers, nullptr);
    auto* installedChildren = const_cast<harken::ContainerChildProgramViewV2*>(
        installed.containers[1].children);
    ASSERT_NE(installedChildren, nullptr);
    ++installedChildren[0].playable.contentRevision;
    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, request);
    EXPECT_EQ(harken::PlayableStartStatus::UnknownPlayable, started.status);
    EXPECT_EQ(0u, engine->playableInstances.LiveCount());
}

void ExpectQueueSequenceBranchesComplete(std::uint32_t cycles, bool stopAndReplay = false,
                                         bool refuseInitial = false) {
    harkentest::EngineSession session(harkentest::MakeNullConfig(8, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto& engine = *session.Engine();
    const std::vector<float> samples(256, 0.25f);
    const auto pcm = harkentest::MonoDesc(samples, 48000);
    std::array<std::uint64_t, 4> revisions{};
    for (std::uint32_t index = 0; index < revisions.size(); ++index) {
        ASSERT_EQ(VN_OK, Vn_RegisterPCM(harkentest::ObjectId(2300u + index), &pcm));
        revisions[index] = engine.registry.Lookup(harkentest::ObjectId(2300u + index)).contentRevision;
    }
    QueueSequenceBranchesWorldImage image(revisions, cycles);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
        harken::InstallContainerWorldV1(engine, image.world).status);
    for (std::uint32_t attempt = 0; attempt < (stopAndReplay ? 2u : 1u); ++attempt) {
    SCOPED_TRACE(attempt);
    const bool stopThisRun = stopAndReplay && attempt == 0;
    harken::PlayableStartRequest request{};
    request.root = image.Ref(6);
    engine.forceActionTimelineVoiceOwnerCommitFailureForTest = refuseInitial;
    const auto started = harken::StartPlayable(engine, request);
    if (refuseInitial) {
        EXPECT_NE(harken::PlayableStartStatus::Accepted, started.status);
        EXPECT_EQ(0u, engine.playableInstances.LiveCount());
        EXPECT_EQ(0u, engine.containerPlayback.LiveCount());
        EXPECT_EQ(0u, engine.playablePartitions.OccupiedCount());
        EXPECT_EQ(0u, engine.queueInstances.LiveCount());
        EXPECT_EQ(0u, engine.voices.ActiveCount());
        EXPECT_TRUE(std::all_of(engine.actionPlayScratch.begin(), engine.actionPlayScratch.end(),
            [](const auto& scratch) { return scratch.storage.phase == harken::EngineFrontierAttemptPhase::Free; }));
        EXPECT_TRUE(std::all_of(engine.playableServices.begin(), engine.playableServices.end(),
            [](const auto& service) { return !service.partition.Valid() && !service.actionPrepared; }));
        return;
    }
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    FrontierTrace actual;
    auto& heard = actual.heard;
    bool stopped = false;
    harken::SelectionMemoryKeyV1 stoppedKey{};
    harken::SelectionMemorySnapshotV1 stoppedMemory{};
    harken::PlayableControlReason lastReason = harken::PlayableControlReason::None;
    for (std::uint32_t block = 0; block < 256; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine.nullBackend.Pump(1);
        actual.Capture(engine);
        if (stopThisRun && !stopped && heard.size() == 3u) {
            const auto* rootService = FindPlayableRow(engine, started.instance);
            ASSERT_NE(nullptr, rootService);
            stoppedKey.world = rootService->Invocation().worldGeneration;
            stoppedKey.containerStableId = image.containers[1].containerStableId;
            stoppedKey.programSemanticFingerprint = image.containers[1].programSemanticFingerprint;
            stoppedKey.memoryScope = harken::MemoryScopeV1::Global;
            stoppedMemory = engine.selectionMemory.Snapshot(stoppedKey);
            ASSERT_TRUE(stoppedMemory.found);
            EXPECT_EQ(1u, stoppedMemory.selectionOrdinal);
            EXPECT_EQ(1u, stoppedMemory.sequenceCursor);
            ASSERT_EQ(harken::PlayableControlStatus::Ok, harken::StopPlayable(engine, started.instance, 0));
            stopped = true;
        }
        harken::PlayableControlState state{};
        if (harken::QueryPlayable(engine, started.instance, &state) == harken::PlayableControlStatus::Ok)
            lastReason = state.reason;
        if (!engine.playableInstances.Classify(started.instance).live && engine.timelineArms.LiveCount() == 0 &&
            engine.playablePartitions.OccupiedCount() == 0)
            break;
    }
    std::ostringstream trace;
    trace << "reason=" << static_cast<unsigned>(lastReason);
    for (const auto& arm : heard)
        trace << " [sound=" << harken::ObjectIdString(arm.subject) << " start=" << arm.start << " complete=" << arm.complete << ']';
    SCOPED_TRACE(trace.str());
    ASSERT_EQ(stopThisRun ? 3u : 4u * cycles, heard.size());
    for (std::uint32_t index = 0; index < heard.size(); ++index) {
        // Stop preserves Global Sequence memory after the accepted B1 start.
        const auto child = attempt == 1u && index % 4u >= 2u
            ? (index % 4u == 2u ? 3u : 2u) : index % 4u;
        EXPECT_EQ(harkentest::ObjectId(2300u + child), heard[index].subject);
        EXPECT_NE(0u, heard[index].start);
        EXPECT_EQ(heard[index].expectedStart, heard[index].start);
        if (!stopThisRun || index + 1u < heard.size()) EXPECT_GE(heard[index].complete, heard[index].start);
    }
    EXPECT_FALSE(engine.playableInstances.Classify(started.instance).live);
    EXPECT_EQ(0u, engine.playableInstances.LiveCount());
    EXPECT_EQ(0u, engine.containerPlayback.LiveCount());
    EXPECT_EQ(0u, engine.queueInstances.LiveCount());
    EXPECT_EQ(0u, engine.voices.ActiveCount());
    EXPECT_EQ(0u, engine.playablePartitions.OccupiedCount());
    EXPECT_FALSE(engine.runtimeRecreateRequired);
    if (stopThisRun) {
        const auto retained = engine.selectionMemory.Snapshot(stoppedKey);
        EXPECT_TRUE(retained.found);
        EXPECT_EQ(stoppedMemory.selectionOrdinal, retained.selectionOrdinal);
        EXPECT_EQ(stoppedMemory.sequenceCursor, retained.sequenceCursor);
        EXPECT_EQ(stoppedMemory.resetEpoch, retained.resetEpoch);
    }
    }
}

