TEST(PlayableStart,
     VariableControlContinuousTimingSameWinnerAdvancesExactBank) {
    VnConfig config = harkentest::MakeNullConfig(2, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);

    std::vector<float> samples(65536, 0.25f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &pcm));
    const harken::VariableDefinitionV1 variable = {
        harkentest::ObjectId(41), harken::VariableKindV1::Step, 0.0f, 8.0f, 3.0f};
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harkentest::InstallDefinitionsWorld(
                  engine, &variable, 1,
                  UINT64_C(0x56434453414D4542)).status);
    VariableControlWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->variables.CurrentWorldGeneration(), false, false, true);
    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    ASSERT_TRUE(PumpUntilAudible(*engine));
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    harken::VariableControlInstanceSnapshot before{};
    ASSERT_TRUE(engine->variableControlInstances.Capture(
        row->variableControlInstance, &before));
    ASSERT_TRUE(before.discrete.lastApplied.Valid());
    const VnVoiceHandle render =
        engine->ReadPlayableMember(row->scheduleStorageBase).render;

    ASSERT_EQ(VN_OK, Vn_SetValue(harkentest::ObjectId(41), 3.0f));
    harken::VariableControlInstanceSnapshot after{};
    bool advanced = false;
    for (std::uint32_t block = 0; block < 32 && !advanced; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        ASSERT_TRUE(engine->variableControlInstances.Capture(
            row->variableControlInstance, &after));
        advanced = after.discrete.lastApplied.generation >
            before.discrete.lastApplied.generation;
    }
    ASSERT_TRUE(advanced);
    EXPECT_EQ(before.discrete.decision.slot,
              after.discrete.decision.slot);
    EXPECT_EQ(before.discrete.decision.generation,
              after.discrete.decision.generation);
    EXPECT_EQ(after.discrete.lastApplied.generation,
              after.discrete.newestObserved.generation);
    EXPECT_FALSE(after.discrete.newestPending.Valid());
    EXPECT_FALSE(row->variableControlDiscreteRetargetPrepared);
    EXPECT_NE(nullptr, engine->voices.Resolve(render));
    EXPECT_FALSE(engine->runtimeRecreateRequired);
}

TEST(PlayableStart,
     VariableControlContinuousTimingWinnerToSilenceUsesSourceOnlyExit) {
    VnConfig config = harkentest::MakeNullConfig(2, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);

    std::vector<float> samples(65536, 0.25f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &pcm));
    const harken::VariableDefinitionV1 variable = {
        harkentest::ObjectId(41), harken::VariableKindV1::Step, 0.0f, 8.0f, 3.0f};
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harkentest::InstallDefinitionsWorld(
                  engine, &variable, 1,
                  UINT64_C(0x5643444953434558)).status);
    const std::uint32_t decisionBaseline = engine->decisions.LiveCount();

    VariableControlWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->variables.CurrentWorldGeneration(), false, false, true);
    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    ASSERT_TRUE(PumpUntilAudible(*engine));
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    const auto coordinator = row->frontierEntry.coordinator;
    ASSERT_TRUE(coordinator.Valid());
    const VnVoiceHandle initial =
        engine->ReadPlayableMember(row->scheduleStorageBase).render;
    ASSERT_NE(nullptr, engine->voices.Resolve(initial));

    ASSERT_EQ(VN_OK, Vn_SetValue(harkentest::ObjectId(41), 4.0f));
    bool silent = false;
    for (std::uint32_t block = 0; block < 64 && !silent; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        silent = row->rootInstance == started.instance &&
            row->variableControlDiscreteSilent &&
            row->variableControlDiscreteMemberCount == 0 &&
            engine->voices.Resolve(initial) == nullptr;
    }
    EXPECT_TRUE(silent);
    EXPECT_TRUE(engine->playableInstances.Classify(started.instance).live);
    EXPECT_TRUE(row->variableControlInstance.Valid());
    EXPECT_FALSE(engine->runtimeRecreateRequired);
    for (std::uint32_t block = 0; block < 4; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    ASSERT_NO_FATAL_FAILURE(ExpectVariableControlNaturallyCompleted(*engine, started.instance));
    EXPECT_EQ(decisionBaseline, engine->decisions.LiveCount());
    EXPECT_FALSE(engine->decisions.Contains(coordinator));
    ASSERT_EQ(VN_OK, Vn_SetValue(harkentest::ObjectId(41), 3.0f));
    for (std::uint32_t block = 0; block < 16; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        EXPECT_EQ(0u, engine->voices.ActiveCount());
    }
    const auto retriggered = harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, retriggered.status);
    ASSERT_TRUE(PumpUntilAudible(*engine));
    ASSERT_TRUE(StopUntilStale(*engine, retriggered.instance));
    EXPECT_FALSE(engine->runtimeRecreateRequired);
}

TEST(PlayableStart,
     VariableControlInitialDiscreteAndContinuousUseIndependentDecisions) {
    VnConfig config = harkentest::MakeNullConfig(4, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);

    std::vector<float> samples(4096, 0.125f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &pcm));
    const harken::VariableDefinitionV1 variable = {
        harkentest::ObjectId(41), harken::VariableKindV1::Step, 0.0f, 8.0f, 3.0f};
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harkentest::InstallDefinitionsWorld(
                  engine, &variable, 1,
                  UINT64_C(0x5641524455414C30)).status);
    VariableControlWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->variables.CurrentWorldGeneration(), true);
    const std::uint32_t decisionBaseline = engine->decisions.LiveCount();

    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    EXPECT_EQ(2u, engine->voices.ActiveCount());

    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    const harken::VariableControlInstanceToken instance =
        row->variableControlInstance;
    harken::VariableControlInstanceSnapshot control{};
    ASSERT_TRUE(engine->variableControlInstances.Capture(
        instance, &control));
    EXPECT_EQ(harken::VariableControlSideState::Pending,
              control.discrete.state);
    EXPECT_EQ(harken::VariableControlSideState::Pending,
              control.continuous.state);
    EXPECT_NE(control.discrete.decision.slot,
              control.continuous.decision.slot);

    const bool heard = PumpUntilAudible(*engine);
    const bool captured = engine->variableControlInstances.Capture(
        instance, &control);
    harken::DecisionCommittedSnapshot discreteDecision{};
    harken::DecisionCommittedSnapshot continuousDecision{};
    const bool capturedDiscrete = engine->decisions.CaptureCommitted(
        control.discrete.decision, &discreteDecision);
    const bool capturedContinuous = engine->decisions.CaptureCommitted(
        control.continuous.decision, &continuousDecision);
    ASSERT_TRUE(heard)
        << "recreate=" << engine->runtimeRecreateRequired
        << " phase=" << static_cast<int>(row->phase)
        << " lifecycle=" << static_cast<int>(row->controlLifecycle)
        << " captured=" << captured
        << " decisions=" << engine->decisions.LiveCount()
        << " discrete=" << capturedDiscrete
        << "/" << static_cast<int>(discreteDecision.audioState)
        << " continuous=" << capturedContinuous
        << "/" << static_cast<int>(continuousDecision.audioState);
    ASSERT_TRUE(captured);
    EXPECT_EQ(harken::VariableControlSideState::Committed,
              control.discrete.state);
    EXPECT_EQ(harken::VariableControlSideState::Committed,
              control.continuous.state);
    EXPECT_EQ(decisionBaseline + 3u, engine->decisions.LiveCount());
    EXPECT_TRUE(engine->decisions.Contains(row->frontierEntry.coordinator));

    const std::size_t continuousSlot =
        row->scheduleStorageBase + row->variableControlContinuousMemberOffset;
    ASSERT_LT(continuousSlot,
              engine->playableStorage.memberCount);
    const VnVoiceHandle continuousRender =
        engine->ReadPlayableMember(continuousSlot).render;
    const harken::VoiceRenderContext* continuousVoice =
        engine->voices.Resolve(continuousRender);
    ASSERT_NE(nullptr, continuousVoice);
    const auto* ownedWeight = FrontierOwnedVariableWeight(*continuousVoice, *row);
    ASSERT_NE(nullptr, ownedWeight);
    ASSERT_TRUE(ownedWeight->active);
    EXPECT_EQ(control.continuous.decision.slot,
              ownedWeight->segment.decision.slot);
    EXPECT_EQ(control.continuous.decision.generation,
              ownedWeight->segment.decision.generation);
    EXPECT_EQ(control.continuous.lastApplied.slot,
              ownedWeight->segment.bank.slot);
    EXPECT_EQ(control.continuous.lastApplied.generation,
              ownedWeight->segment.bank.generation);
    EXPECT_FLOAT_EQ(1.0f,
                    ownedWeight->segment.startWeight);
    EXPECT_FLOAT_EQ(1.0f,
                    ownedWeight->segment.endWeight);

    for (std::uint32_t block = 0; block < 96; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    ASSERT_NO_FATAL_FAILURE(ExpectVariableControlNaturallyCompleted(*engine, started.instance));
    EXPECT_FALSE(engine->variableControlInstances.Capture(
        instance, &control));
    EXPECT_EQ(decisionBaseline, engine->decisions.LiveCount());
}

