TEST(PlayableStart,
     VariableControlStopDuringInitialPreparingCancelsBothSideDecisions) {
    VnConfig config = harkentest::MakeNullConfig(4, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    const std::uint32_t voiceBaseline = engine->voices.ActiveCount();
    const std::uint32_t armBaseline = engine->timelineArms.LiveCount();
    const std::uint32_t decisionBaseline = engine->decisions.LiveCount();
    const std::uint32_t groupBaseline = engine->armGroups.LiveCount();
    const std::uint32_t instanceBaseline =
        engine->playableInstances.LiveCount();

    std::vector<float> samples(65536, 0.125f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &pcm));
    const harken::VariableDefinitionV1 variable = {
        harkentest::ObjectId(41), harken::VariableKindV1::Smooth, 0.0f, 8.0f, 3.0f};
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harkentest::InstallDefinitionsWorld(
                  engine, &variable, 1,
                  UINT64_C(0x5643494E49545354)).status);
    VariableControlWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->variables.CurrentWorldGeneration(), true);
    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    ASSERT_EQ(harken::EnginePlayableStartPhase::AwaitingArmAck, row->phase);
    ASSERT_EQ(harken::PlayableControlLifecycle::Preparing,
              row->controlLifecycle);
    ASSERT_EQ(1u, row->variableControlInitialDiscreteMemberCount);
    ASSERT_EQ(1u, row->variableControlInitialContinuousMemberCount);
    ASSERT_TRUE(row->variableControlDiscreteDecision.Valid());
    ASSERT_TRUE(row->variableControlContinuousDecision.Valid());
    ASSERT_TRUE(row->variableControlDiscreteDecisionCommitted);
    ASSERT_TRUE(row->variableControlContinuousDecisionCommitted);
    const harken::DecisionToken discreteDecision =
        row->variableControlDiscreteDecision;
    const harken::DecisionToken continuousDecision =
        row->variableControlContinuousDecision;

    const std::array<harken::ArmGroupToken, 2> cancelledGroups = {
        row->variableControlDiscreteArmGroup, row->variableControlContinuousArmGroup};
    harken::PlayableControlState state{};
    ASSERT_EQ(harken::PlayableControlStatus::Ok,
              harken::QueryPlayable(*engine, started.instance, &state));
    ASSERT_EQ(harken::PlayableControlLifecycle::Preparing, state.lifecycle);
    ASSERT_EQ(harken::PlayableControlStatus::Ok,
              harken::StopPlayable(*engine, started.instance, 0));
    ASSERT_EQ(harken::PlayableControlStatus::Ok,
              harken::QueryPlayable(*engine, started.instance, &state));
    EXPECT_EQ(harken::PlayableControlLifecycle::Cancelling, state.lifecycle);
    EXPECT_EQ(harken::PlayableControlStatus::Ok,
              harken::StopPlayable(*engine, started.instance, 99));

    bool discreteAdmitted = false;
    bool continuousAdmitted = false;
    bool sawRetirementFence = false;
    bool stale = false;
    for (std::uint32_t block = 0; block < 96 && !stale; ++block) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        harken::DecisionCommittedSnapshot snapshot{};
        discreteAdmitted = discreteAdmitted ||
            (engine->decisions.CaptureCommitted(discreteDecision, &snapshot) &&
             snapshot.audioState == harken::AudioGroupState::Admitted);
        continuousAdmitted = continuousAdmitted ||
            (engine->decisions.CaptureCommitted(continuousDecision, &snapshot) &&
             snapshot.audioState == harken::AudioGroupState::Admitted);
        for (const auto groupToken : cancelledGroups) {
            harken::ArmGroupSnapshot group{};
            if (!engine->armGroups.Capture(groupToken, &group) ||
                group.maxTombstoneSequence == 0 ||
                group.maxTombstoneSequence != engine->mixer.BlocksRendered()) continue;
            const auto tombstoneSequence = group.maxTombstoneSequence;
            ASSERT_EQ(VN_OK, Vn_Update());
            EXPECT_EQ(tombstoneSequence, engine->mixer.BlocksRendered());
            EXPECT_TRUE(engine->armGroups.Capture(groupToken, &group));
            sawRetirementFence = true;
        }
        stale = harken::QueryPlayable(
                    *engine, started.instance, &state) ==
            harken::PlayableControlStatus::StaleHandle;
    }

    EXPECT_FALSE(discreteAdmitted);
    EXPECT_FALSE(continuousAdmitted);
    EXPECT_TRUE(stale);
    ASSERT_NO_FATAL_FAILURE(ExpectTransferredDecisionsReclaimed(*engine, decisionBaseline));
    EXPECT_TRUE(sawRetirementFence);
    EXPECT_FALSE(engine->decisions.Contains(discreteDecision));
    EXPECT_FALSE(engine->decisions.Contains(continuousDecision));
    for (const auto groupToken : cancelledGroups) {
        harken::ArmGroupSnapshot group{};
        EXPECT_FALSE(engine->armGroups.Capture(groupToken, &group));
    }
    EXPECT_EQ(voiceBaseline, engine->voices.ActiveCount());
    EXPECT_EQ(armBaseline, engine->timelineArms.LiveCount());
    EXPECT_EQ(decisionBaseline, engine->decisions.LiveCount());
    EXPECT_EQ(groupBaseline, engine->armGroups.LiveCount());
    EXPECT_EQ(instanceBaseline, engine->playableInstances.LiveCount());
    EXPECT_FALSE(engine->runtimeRecreateRequired);
}

static void ExpectVariableControlCancelledDiscreteRetargetReclaimsEverything(bool rejectFuture) {
    VnConfig config = harkentest::MakeNullConfig(3, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    const std::uint32_t decisionBaseline = engine->decisions.LiveCount();

    std::vector<float> samples(rejectFuture ? 2048 : 65536, 0.125f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &pcm));
    const harken::VariableDefinitionV1 variable = {
        harkentest::ObjectId(41), harken::VariableKindV1::Step, 0.0f, 8.0f, 3.0f};
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harkentest::InstallDefinitionsWorld(
                  engine, &variable, 1,
                  UINT64_C(0x56434453544F5052)).status);
    VariableControlDiscreteMembershipWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->variables.CurrentWorldGeneration());
    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    ASSERT_TRUE(PumpUntilAudible(*engine));
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), row);

    ASSERT_EQ(VN_OK, Vn_SetValue(harkentest::ObjectId(41), 7.0f));
    bool prepared = false;
    for (std::uint32_t block = 0; block < 32 && !prepared; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        prepared = row->variableControlDiscreteRetargetPrepared;
        if (!prepared) engine->nullBackend.Pump(1);
    }
    ASSERT_TRUE(prepared);
    const auto entry = row->frontierLifetimeEntry;
    const auto entering = row->VariablePayload().variableControlDiscreteRetargetEnteringArm;
    const auto source = engine->ReadPlayableMember(row->scheduleStorageBase).completion.source;
    const auto sourceRender = row->renderHandle;
    if (rejectFuture) {
        for (std::uint32_t block = 0; block < 8 && !row->variableControlDiscreteRetargetDecisionCommitted; ++block) {
            engine->nullBackend.Pump(1);
            ASSERT_EQ(VN_OK, Vn_Update());
        }
        ASSERT_TRUE(row->variableControlDiscreteRetargetDecisionCommitted);
        harken::Plan03PageGroupView group{};
        ASSERT_TRUE(engine->timelinePool.ResolvePlan03GroupSliceProducer(row->VariableControlDiscreteRetargetSlice(), &group));
        ASSERT_NE(nullptr, group.frontier);
        ASSERT_EQ(harken::FrontierGroupRole::Future, group.frontier->role);
        ASSERT_EQ(entry, group.frontier->entry);
        ASSERT_EQ(harken::AudioSliceInvalidateDisposition::InvalidatedReady,
            group.lease->Invalidate(harken::AudioSliceInvalidateReason::Identity));
        ASSERT_EQ(VN_OK, Vn_Update());
        const auto* activation = engine->decisions.ResolveFrontierActivation(entry.coordinator);
        ASSERT_NE(nullptr, activation);
        harken::FrontierActivationReceipt receipt{};
        ASSERT_EQ(harken::FrontierReceiptRead::Ready, activation->Read(entry, engine->mixer.BlocksRendered(), &receipt));
        EXPECT_EQ(harken::FrontierReceiptOutcome::Applied, receipt.outcome);
        EXPECT_EQ(harken::PlayableControlLifecycle::FailingSourceActive, row->controlLifecycle);
        EXPECT_EQ(harken::PlayableControlReason::StartRefused, row->controlReason);
        EXPECT_NE(nullptr, engine->voices.Resolve(sourceRender));
    } else {
        ASSERT_EQ(harken::PlayableControlStatus::Ok,
                  harken::StopPlayable(*engine, started.instance, 0));
    }

    bool stale = false;
    bool rejectedTargetStarted = false;
    bool sourceEndedNaturally = false;
    for (std::uint32_t block = 0; block < 64 && !stale; ++block) {
        engine->nullBackend.Pump(1);
        harken::SourceTerminalPayload terminal{};
        if (engine->sourceTerminals.Capture(source, engine->mixer.BlocksRendered(), &terminal))
            sourceEndedNaturally = terminal.kind == harken::SourceTerminalKind::Natural;
        ASSERT_EQ(VN_OK, Vn_Update());
        harken::TimelineArmObservation observation{};
        if (engine->timelineArms.Observe(entering, &observation))
            rejectedTargetStarted = rejectedTargetStarted || observation.startedBlockSequence != 0;
        stale = !engine->playableInstances.Classify(started.instance).live &&
            row->phase == harken::EnginePlayableStartPhase::Free;
    }
    EXPECT_FALSE(row->VariablePayload().variableControlDiscreteRetargetDecision.Valid());
    EXPECT_FALSE(row->VariablePayload().variableControlDiscreteRetargetArmGroup.Valid());
    EXPECT_FALSE(row->variableControlDiscreteRetargetCleanupStarted);
    EXPECT_FALSE(row->variableControlDiscreteDecision.Valid());
    EXPECT_FALSE(row->variableControlDiscreteArmGroup.Valid());
    EXPECT_FALSE(row->variableControlDiscreteCleanupStarted);
    EXPECT_FALSE(row->variableControlInstance.Valid());
    EXPECT_TRUE(stale);
    EXPECT_EQ(decisionBaseline, engine->decisions.LiveCount());
    EXPECT_FALSE(engine->runtimeRecreateRequired);
    if (rejectFuture) {
        EXPECT_FALSE(rejectedTargetStarted);
        EXPECT_TRUE(sourceEndedNaturally);
    }
}

TEST(PlayableStart, VariableControlStopDuringPreparedDiscreteRetargetReclaimsEverything) {
    ExpectVariableControlCancelledDiscreteRetargetReclaimsEverything(false);
}

TEST(PlayableStart, VariableControlRejectedDiscreteFutureReclaimsWithoutChangingEntryReceipt) {
    ExpectVariableControlCancelledDiscreteRetargetReclaimsEverything(true);
}

TEST(PlayableStart,
     VariableControlStopInvalidatesCommittedPendingDiscreteRetarget) {
    VnConfig config = harkentest::MakeNullConfig(3, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    const std::uint32_t voiceBaseline = engine->voices.ActiveCount();
    const std::uint32_t armBaseline = engine->timelineArms.LiveCount();
    const std::uint32_t decisionBaseline = engine->decisions.LiveCount();
    const std::uint32_t groupBaseline = engine->armGroups.LiveCount();
    const std::uint32_t instanceBaseline =
        engine->playableInstances.LiveCount();

    std::vector<float> samples(65536, 0.125f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &pcm));
    const harken::VariableDefinitionV1 variable = {
        harkentest::ObjectId(41), harken::VariableKindV1::Step, 0.0f, 8.0f, 3.0f};
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harkentest::InstallDefinitionsWorld(
                  engine, &variable, 1,
                  UINT64_C(0x564344434F4D4D49)).status);
    VariableControlDiscreteMembershipWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->variables.CurrentWorldGeneration());
    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    ASSERT_TRUE(PumpUntilAudible(*engine));
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), row);

    ASSERT_EQ(VN_OK, Vn_SetValue(harkentest::ObjectId(41), 7.0f));
    bool committedPending = false;
    harken::DecisionCommittedSnapshot before{};
    for (std::uint32_t block = 0; block < 32 && !committedPending; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        committedPending =
            row->variableControlDiscreteRetargetDecisionCommitted &&
            engine->decisions.CaptureCommitted(
                row->VariablePayload().variableControlDiscreteRetargetDecision, &before) &&
            before.audioState == harken::AudioGroupState::Pending;
        if (!committedPending) engine->nullBackend.Pump(1);
    }
    ASSERT_TRUE(committedPending);
    const harken::DecisionToken decision =
        row->VariablePayload().variableControlDiscreteRetargetDecision;
    const harken::TimelineArmToken entering =
        row->VariablePayload().variableControlDiscreteRetargetEnteringArm;

    ASSERT_EQ(harken::PlayableControlStatus::Ok,
              harken::StopPlayable(*engine, started.instance, 0));
    harken::DecisionCommittedSnapshot invalidated{};
    ASSERT_TRUE(engine->decisions.CaptureCommitted(decision, &invalidated));
    EXPECT_EQ(harken::AudioGroupState::Invalidated,
              invalidated.audioState);

    bool enteringStarted = false;
    bool stale = false;
    harken::PlayableControlState state{};
    for (std::uint32_t block = 0; block < 96 && !stale; ++block) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        harken::TimelineArmObservation observation{};
        enteringStarted = enteringStarted ||
            (engine->timelineArms.Observe(entering, &observation) &&
             observation.state == harken::ArmState::Started);
        stale = harken::QueryPlayable(
                    *engine, started.instance, &state) ==
            harken::PlayableControlStatus::StaleHandle;
    }
    EXPECT_FALSE(enteringStarted);
    EXPECT_TRUE(stale);
    ASSERT_NO_FATAL_FAILURE(ExpectTransferredDecisionsReclaimed(*engine, decisionBaseline));
    EXPECT_EQ(voiceBaseline, engine->voices.ActiveCount());
    EXPECT_EQ(armBaseline, engine->timelineArms.LiveCount());
    EXPECT_EQ(decisionBaseline, engine->decisions.LiveCount());
    EXPECT_EQ(groupBaseline, engine->armGroups.LiveCount());
    EXPECT_EQ(instanceBaseline, engine->playableInstances.LiveCount());
    EXPECT_FALSE(engine->runtimeRecreateRequired);
}

TEST(PlayableStart,
     VariableControlStopEpochExhaustionHasZeroDecisionOrRowMutation) {
    VnConfig config = harkentest::MakeNullConfig(3, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);

    std::vector<float> samples(65536, 0.125f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &pcm));
    const harken::VariableDefinitionV1 variable = {
        harkentest::ObjectId(41), harken::VariableKindV1::Step, 0.0f, 8.0f, 3.0f};
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harkentest::InstallDefinitionsWorld(
                  engine, &variable, 1,
                  UINT64_C(0x564345504F43485A)).status);
    VariableControlDiscreteMembershipWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->variables.CurrentWorldGeneration());
    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    ASSERT_TRUE(PumpUntilAudible(*engine));
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), row);

    ASSERT_EQ(VN_OK, Vn_SetValue(harkentest::ObjectId(41), 7.0f));
    harken::DecisionCommittedSnapshot beforeDecision{};
    bool committedPending = false;
    for (std::uint32_t block = 0; block < 32 && !committedPending; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        committedPending =
            row->variableControlDiscreteRetargetDecisionCommitted &&
            engine->decisions.CaptureCommitted(
                row->VariablePayload().variableControlDiscreteRetargetDecision,
                &beforeDecision) &&
            beforeDecision.audioState == harken::AudioGroupState::Pending;
        if (!committedPending) engine->nullBackend.Pump(1);
    }
    ASSERT_TRUE(committedPending);
    const harken::DecisionToken decision =
        row->VariablePayload().variableControlDiscreteRetargetDecision;
    const harken::PlayableInstanceView beforeInstance =
        engine->playableInstances.Classify(started.instance);
    const harken::EnginePlayableStartPhase beforePhase = row->phase;
    const harken::PlayableControlLifecycle beforeLifecycle =
        row->controlLifecycle;
    const std::uint32_t beforePendingFuture = row->pendingFutureCount;
    harken::detail::PlayableCancellationTestAccess::ExhaustScheduleEpochs(
        engine->playableInstances);

    EXPECT_EQ(harken::PlayableControlStatus::Backpressure,
              harken::StopPlayable(*engine, started.instance, 0));
    harken::DecisionCommittedSnapshot afterDecision{};
    ASSERT_TRUE(engine->decisions.CaptureCommitted(decision,
                                                   &afterDecision));
    EXPECT_EQ(beforeDecision.audioState, afterDecision.audioState);
    const harken::PlayableInstanceView afterInstance =
        engine->playableInstances.Classify(started.instance);
    EXPECT_EQ(beforeInstance.scheduleEpoch, afterInstance.scheduleEpoch);
    EXPECT_EQ(beforePhase, row->phase);
    EXPECT_EQ(beforeLifecycle, row->controlLifecycle);
    EXPECT_EQ(beforePendingFuture, row->pendingFutureCount);
    EXPECT_FALSE(engine->runtimeRecreateRequired);
}

TEST_P(ClaimedVariableControlSliceCancellationTest,
       WholeSliceCompletesBeforeConcurrentCancellationTakesEffect) {
    VnConfig config = harkentest::MakeNullConfig(3, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    const std::uint32_t voiceBaseline = engine->voices.ActiveCount();
    const std::uint32_t armBaseline = engine->timelineArms.LiveCount();
    const std::uint32_t decisionBaseline = engine->decisions.LiveCount();
    const std::uint32_t groupBaseline = engine->armGroups.LiveCount();
    const std::uint32_t instanceBaseline =
        engine->playableInstances.LiveCount();
    const harken::TransportEpoch transportBefore =
        engine->transportEpochOwner.Current();

    std::vector<float> samples(65536, 0.125f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &pcm));
    const harken::VariableDefinitionV1 variable = {
        harkentest::ObjectId(41), harken::VariableKindV1::Step, 0.0f, 8.0f, 3.0f};
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harkentest::InstallDefinitionsWorld(
                  engine, &variable, 1,
                  UINT64_C(0x5643434C41494D53)).status);
    VariableControlDiscreteMembershipWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->variables.CurrentWorldGeneration());
    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    ASSERT_TRUE(PumpUntilAudible(*engine));
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    PlayableWorldImage replacement(
        engine->registry.Lookup(kSound).contentRevision,
        harken::ContainerModeV1::Random);

    ASSERT_EQ(VN_OK, Vn_SetValue(harkentest::ObjectId(41), 7.0f));
    harken::DecisionCommittedSnapshot pending{};
    bool committedPending = false;
    for (std::uint32_t block = 0; block < 32 && !committedPending; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        committedPending =
            row->variableControlDiscreteRetargetDecisionCommitted &&
            engine->decisions.CaptureCommitted(
                row->VariablePayload().variableControlDiscreteRetargetDecision, &pending) &&
            pending.audioState == harken::AudioGroupState::Pending;
        if (!committedPending) engine->nullBackend.Pump(1);
    }
    ASSERT_TRUE(committedPending);
    const harken::DecisionToken decision =
        row->VariablePayload().variableControlDiscreteRetargetDecision;
    const harken::TimelineArmToken entering =
        row->VariablePayload().variableControlDiscreteRetargetEnteringArm;
    ASSERT_TRUE(entering.Valid());
    const VnVoiceHandle enteringRender =
        (static_cast<std::uint64_t>(entering.renderGeneration) << 32) |
        entering.renderSlot;
    harken::Plan03PageGroupView group{};
    harken::Plan03GroupSliceIdentity identity{};
    identity.absoluteQuantum =
        row->VariablePayload().variableControlDiscreteRetargetFrame /
        engine->config.blockFrames;
    identity.pageGeneration =
        row->VariablePayload().variableControlDiscreteRetargetPages.generation;
    identity.decision = decision;
    ASSERT_TRUE(engine->timelinePool.ResolvePlan03GroupSliceRt(
        identity, &group));
    ASSERT_NE(nullptr, group.lease);
    ASSERT_LE(engine->mixer.BlocksRendered(), identity.absoluteQuantum);
    while (engine->mixer.BlocksRendered() < identity.absoluteQuantum) {
        engine->nullBackend.Pump(1);
    }
    ASSERT_EQ(2u, row->VariablePayload().variableControlDiscreteRetargetGroupMemberCount);
    std::array<harken::TimelineArmObservation, 2> armsBefore{};
    for (std::uint32_t index = 0; index < armsBefore.size(); ++index) {
        ASSERT_TRUE(engine->timelineArms.Observe(
            row->DiscreteRetargetStorage().groupArms[index],
            &armsBefore[index]));
    }
    harken::VariableControlInstanceSnapshot sideBefore{};
    ASSERT_TRUE(engine->variableControlInstances.Capture(
        row->variableControlInstance, &sideBefore));
    const std::size_t currentSlot = row->scheduleStorageBase;
    const VnVoiceHandle currentRender =
        engine->ReadPlayableMember(currentSlot).render;
    ASSERT_NE(0u, currentRender);
    const harken::VoiceLedger::RenderOwner currentOwnerBefore =
        engine->ledger.OwnerForRender(currentRender);
    ASSERT_TRUE(currentOwnerBefore.live);
    const harken::TimelineSemanticTarget currentTargetBefore =
        engine->ReadPlayableMember(currentSlot).voice.Facts().target;

    StopAfterVariableControlSliceClaimContext context{};
    context.engine = engine;
    context.instance = started.instance;
    context.decision = decision;
    context.arm = entering;
    context.replacementWorld = replacement.world;
    context.intent = GetParam();
    harken::detail::VoiceTimelineSinkTestAccess::
        SetVariableControlSliceClaimHook(
            engine->timelineSink,
            &WaitForConcurrentStopAfterVariableControlSliceClaim,
            &context);
    std::thread pumpThread([&context] {
        context.engine->nullBackend.Pump(1);
        context.pumpComplete.store(true, std::memory_order_release);
    });
    for (std::uint32_t attempt = 0;
         attempt < 1000000 &&
         !context.invoked.load(std::memory_order_acquire) &&
         !context.pumpComplete.load(std::memory_order_acquire);
         ++attempt) {
        std::this_thread::yield();
    }
    const bool hookInvoked =
        context.invoked.load(std::memory_order_acquire);
    if (!hookInvoked) {
        context.releaseClaim.store(true, std::memory_order_release);
        pumpThread.join();
        harken::detail::VoiceTimelineSinkTestAccess::
            SetVariableControlSliceClaimHook(engine->timelineSink, nullptr,
                                             nullptr);
        FAIL() << "audio slice claim hook was not reached";
        return;
    }

    ASSERT_EQ(VN_OK, Vn_SetValue(harkentest::ObjectId(41), 3.0f));
    ASSERT_EQ(VN_OK, Vn_Update());
    const std::uint64_t pendingDesiredOrdinal =
        row->VariablePayload().variableControlDiscretePendingDesiredOrdinal;

    switch (context.intent) {
    case StopAfterVariableControlSliceClaimContext::Intent::Stop:
        context.operationAccepted =
            harken::StopPlayable(*context.engine, context.instance, 0) ==
            harken::PlayableControlStatus::Ok;
        break;
    case StopAfterVariableControlSliceClaimContext::Intent::WorldReplacement:
        row->variableControlWorldUsesCurrentAuthority = true;
        context.operationAccepted =
            harken::InstallContainerWorldV1(
                *context.engine, context.replacementWorld).status ==
            harken::WorldInstallStatus::Backpressure;
        break;
    case StopAfterVariableControlSliceClaimContext::Intent::TransportReset:
        context.operationAccepted =
            harken::BeginRuntimeTransportReset(*context.engine, 0) ==
            harken::RuntimeTransportResetStatus::Backpressure;
        break;
    }
    const VnResult updateWhileClaimed = Vn_Update();
    harken::DecisionCommittedSnapshot decisionWhileClaimed{};
    const bool decisionPreserved = engine->decisions.CaptureCommitted(
        decision, &decisionWhileClaimed);
    std::array<harken::TimelineArmObservation, 2> armsWhileClaimed{};
    bool armsPreserved = true;
    for (std::uint32_t index = 0; index < armsWhileClaimed.size(); ++index) {
        armsPreserved = engine->timelineArms.Observe(
                            row->DiscreteRetargetStorage().groupArms[index],
                            &armsWhileClaimed[index]) &&
            armsWhileClaimed[index].state == armsBefore[index].state &&
            armsPreserved;
    }
    harken::VariableControlInstanceSnapshot sideWhileClaimed{};
    const bool sidePreserved = engine->variableControlInstances.Capture(
        row->variableControlInstance, &sideWhileClaimed);
    const harken::VoiceLedger::RenderOwner currentOwnerWhileClaimed =
        engine->ledger.OwnerForRender(currentRender);
    const harken::TimelineSemanticTarget currentTargetWhileClaimed =
        engine->ReadPlayableMember(currentSlot).voice.Facts().target;
    const bool rowRetargetPreserved =
        row->variableControlDiscreteRetargetPrepared &&
        row->variableControlDiscreteRetargetDecisionCommitted &&
        row->VariablePayload().variableControlDiscreteRetargetDecision.slot == decision.slot &&
        row->VariablePayload().variableControlDiscreteRetargetDecision.generation ==
            decision.generation;

    context.releaseClaim.store(true, std::memory_order_release);
    pumpThread.join();
    harken::detail::VoiceTimelineSinkTestAccess::
        SetVariableControlSliceClaimHook(engine->timelineSink, nullptr,
                                         nullptr);

    EXPECT_TRUE(context.operationAccepted);
    EXPECT_EQ(VN_OK, updateWhileClaimed);
    EXPECT_NE(0u, pendingDesiredOrdinal);
    ASSERT_TRUE(decisionPreserved);
    EXPECT_EQ(harken::AudioGroupState::Pending,
              decisionWhileClaimed.audioState);
    EXPECT_TRUE(armsPreserved);
    ASSERT_TRUE(sidePreserved);
    EXPECT_EQ(harken::VariableControlSideState::Transitioning,
              sideWhileClaimed.discrete.state);
    EXPECT_EQ(sideBefore.discrete.decision.slot,
              sideWhileClaimed.discrete.decision.slot);
    EXPECT_EQ(sideBefore.discrete.decision.generation,
              sideWhileClaimed.discrete.decision.generation);
    EXPECT_EQ(sideBefore.discrete.lastApplied.slot,
              sideWhileClaimed.discrete.lastApplied.slot);
    EXPECT_EQ(sideBefore.discrete.lastApplied.generation,
              sideWhileClaimed.discrete.lastApplied.generation);
    EXPECT_TRUE(rowRetargetPreserved);
    EXPECT_TRUE(currentOwnerWhileClaimed.live);
    EXPECT_EQ(currentOwnerBefore.ledgerSlot,
              currentOwnerWhileClaimed.ledgerSlot);
    EXPECT_EQ(currentOwnerBefore.parent.internalToken,
              currentOwnerWhileClaimed.parent.internalToken);
    EXPECT_EQ(currentTargetBefore.programSemanticFingerprint,
              currentTargetWhileClaimed.programSemanticFingerprint);
    EXPECT_EQ(currentTargetBefore.occurrenceOrdinal,
              currentTargetWhileClaimed.occurrenceOrdinal);
    harken::DecisionCommittedSnapshot invalidated{};
    ASSERT_TRUE(engine->decisions.CaptureCommitted(decision, &invalidated));
    EXPECT_EQ(harken::AudioGroupState::Admitted,
              invalidated.audioState);
    harken::TimelineArmObservation enteringAfterSlice{};
    ASSERT_TRUE(engine->timelineArms.Observe(entering,
                                            &enteringAfterSlice));
    EXPECT_EQ(harken::ArmState::Tombstoned, enteringAfterSlice.state);
    const harken::VoiceRenderContext* enteringVoice =
        engine->voices.Resolve(enteringRender);
    ASSERT_NE(nullptr, enteringVoice);
    EXPECT_FALSE(enteringVoice->timelineGated);
    const std::uint32_t expectedReason =
        GetParam() == StopAfterVariableControlSliceClaimContext::Intent::
                          TransportReset
            ? harken::AudioSliceReasonTransportReset
            : GetParam() == StopAfterVariableControlSliceClaimContext::Intent::
                                WorldReplacement
                  ? harken::AudioSliceReasonWorldReplacement
                  : harken::AudioSliceReasonCancel;
    const harken::AudioSliceLeaseSnapshot lease = group.lease->Capture();
    EXPECT_EQ(harken::AudioSliceState::SliceApplied, lease.state);
    EXPECT_EQ(expectedReason,
              lease.pendingReasonBits & expectedReason);
    EXPECT_TRUE(lease.invalidateAfterSlice);

    bool stale = false;
    bool restored = false;
    bool operationComplete = false;
    for (std::uint32_t block = 0;
         block < 256 && !(stale && restored && operationComplete); ++block) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        stale = !engine->playableInstances.Classify(started.instance).live;
        restored = engine->voices.ActiveCount() == voiceBaseline &&
            engine->timelineArms.LiveCount() == armBaseline &&
            engine->decisions.LiveCount() == decisionBaseline &&
            engine->armGroups.LiveCount() == groupBaseline &&
            engine->playableInstances.LiveCount() == instanceBaseline &&
            engine->variables.PendingCount() == 0;
        switch (GetParam()) {
        case StopAfterVariableControlSliceClaimContext::Intent::Stop:
            operationComplete = true;
            break;
        case StopAfterVariableControlSliceClaimContext::Intent::
            WorldReplacement:
            operationComplete =
                harken::InstallContainerWorldV1(
                    *engine, replacement.world).status ==
                harken::WorldInstallStatus::Ok;
            break;
        case StopAfterVariableControlSliceClaimContext::Intent::
            TransportReset:
            operationComplete =
                harken::BeginRuntimeTransportReset(*engine, 0) ==
                harken::RuntimeTransportResetStatus::Complete;
            break;
        }
    }
    EXPECT_TRUE(stale);
    EXPECT_TRUE(restored);
    EXPECT_TRUE(operationComplete);
    EXPECT_EQ(0u, row->VariablePayload().variableControlDiscretePendingDesiredOrdinal);
    EXPECT_EQ(0u, row->VariablePayload().variableControlDiscretePendingDesiredFrame);
    EXPECT_FALSE(row->variableControlDeferredCancellation);
    EXPECT_FALSE(row->variableControlDeferredCancellationSlice.Valid());
    EXPECT_EQ(0u, row->variableControlDeferredCancellationReasonBit);
    if (GetParam() == StopAfterVariableControlSliceClaimContext::Intent::
                          TransportReset) {
        EXPECT_GT(engine->transportEpochOwner.Current(), transportBefore);
    }
    EXPECT_FALSE(engine->runtimeRecreateRequired);
}

INSTANTIATE_TEST_SUITE_P(
    StopWorldAndReset,
    ClaimedVariableControlSliceCancellationTest,
    testing::Values(
        StopAfterVariableControlSliceClaimContext::Intent::Stop,
        StopAfterVariableControlSliceClaimContext::Intent::WorldReplacement,
        StopAfterVariableControlSliceClaimContext::Intent::TransportReset));

TEST_P(ClaimedInitialVariableControlSliceCancellationTest,
       WholeInitialSliceCompletesBeforeConcurrentCancellationTakesEffect) {
    VnConfig config = harkentest::MakeNullConfig(4, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    const std::uint32_t voiceBaseline = engine->voices.ActiveCount();
    const std::uint32_t armBaseline = engine->timelineArms.LiveCount();
    const std::uint32_t decisionBaseline = engine->decisions.LiveCount();
    const std::uint32_t groupBaseline = engine->armGroups.LiveCount();
    const std::uint32_t instanceBaseline =
        engine->playableInstances.LiveCount();

    std::vector<float> samples(65536, 0.125f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &pcm));
    const bool continuous =
        GetParam().side == harken::VariableControlSide::Continuous;
    const harken::VariableDefinitionV1 variable = {
        harkentest::ObjectId(41),
        continuous ? harken::VariableKindV1::Smooth
                   : harken::VariableKindV1::Step,
        0.0f, 8.0f, 3.0f};
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harkentest::InstallDefinitionsWorld(
                  engine, &variable, 1,
                  UINT64_C(0x5643494E434C4149)).status);
    VariableControlDiscreteMembershipWorldImage discreteImage(
        engine->registry.Lookup(kSound).contentRevision,
        engine->variables.CurrentWorldGeneration());
    VariableControlMembershipWorldImage continuousImage(
        engine->registry.Lookup(kSound).contentRevision,
        engine->variables.CurrentWorldGeneration());
    harken::PlayableStartRequest request{};
    request.root = continuous ? continuousImage.Root() : discreteImage.Root();
    const harken::PlayableWorldViewV1& world =
        continuous ? continuousImage.world : discreteImage.world;
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), row);

    harken::DecisionCommittedSnapshot pending{};
    bool committedPending = false;
    for (std::uint32_t block = 0; block < 32 && !committedPending; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        const bool committed = continuous
            ? row->variableControlContinuousDecisionCommitted
            : row->variableControlDiscreteDecisionCommitted;
        const harken::DecisionToken candidate = continuous
            ? row->variableControlContinuousDecision
            : row->variableControlDiscreteDecision;
        committedPending = committed &&
            engine->decisions.CaptureCommitted(candidate, &pending) &&
            pending.audioState == harken::AudioGroupState::Pending;
        if (!committedPending) engine->nullBackend.Pump(1);
    }
    ASSERT_TRUE(committedPending);
    if (GetParam().intent ==
        StopAfterVariableControlSliceClaimContext::Intent::WorldReplacement) {
        row->variableControlWorldUsesCurrentAuthority = true;
    }
    const harken::DecisionToken decision = continuous
        ? row->variableControlContinuousDecision
        : row->variableControlDiscreteDecision;
    const std::size_t memberBase =
        static_cast<std::size_t>(row->scheduleStorageBase) +
        (continuous ? row->variableControlContinuousMemberOffset : 0u);
    const std::uint32_t memberCount = continuous
        ? row->variableControlInitialContinuousMemberCount
        : row->variableControlInitialDiscreteMemberCount;
    ASSERT_EQ(continuous ? continuousImage.children.size() : 1u, memberCount);
    const harken::TimelineArmToken member = continuous
        ? row->variableControlInitialArms.Continuous()[0]
        : row->arm;
    ASSERT_TRUE(member.Valid());
    const VnVoiceHandle render =
        engine->ReadPlayableMember(memberBase).render;
    ASSERT_NE(0u, render);
    const auto* activation = engine->decisions.ResolveFrontierActivation(row->frontierEntry.coordinator);
    ASSERT_NE(nullptr, activation);
    const auto identity = activation->Descriptor().primary;
    harken::Plan03PageGroupView group{};
    ASSERT_TRUE(engine->timelinePool.ResolvePlan03GroupSliceProducer(
        identity, &group));
    ASSERT_NE(nullptr, group.lease);
    ASSERT_LE(engine->mixer.BlocksRendered(), identity.absoluteQuantum);
    while (engine->mixer.BlocksRendered() < identity.absoluteQuantum) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    harken::TimelineArmObservation armBefore{};
    ASSERT_TRUE(engine->timelineArms.Observe(member, &armBefore));
    harken::VariableControlInstanceSnapshot instanceBefore{};
    ASSERT_TRUE(engine->variableControlInstances.Capture(
        row->variableControlInstance, &instanceBefore));
    const harken::VariableControlSideSnapshot sideBefore = continuous
        ? instanceBefore.continuous
        : instanceBefore.discrete;
    const harken::VoiceLedger::RenderOwner ownerBefore =
        engine->ledger.OwnerForRender(render);
    ASSERT_TRUE(ownerBefore.live);
    const harken::TimelineSemanticTarget targetBefore =
        engine->ReadPlayableMember(memberBase).voice.Facts().target;
    PlayableWorldImage replacement(
        engine->registry.Lookup(kSound).contentRevision,
        harken::ContainerModeV1::Random);

    StopAfterVariableControlSliceClaimContext context{};
    context.engine = engine;
    context.instance = started.instance;
    context.decision = decision;
    context.arm = member;
    context.replacementWorld = replacement.world;
    context.intent = GetParam().intent;
    harken::detail::VoiceTimelineSinkTestAccess::
        SetVariableControlSliceClaimHook(
            engine->timelineSink,
            &WaitForConcurrentStopAfterVariableControlSliceClaim,
            &context);
    std::thread pumpThread([&context] {
        context.engine->nullBackend.Pump(1);
        context.pumpComplete.store(true, std::memory_order_release);
    });
    for (std::uint32_t attempt = 0;
         attempt < 1000000 &&
         !context.invoked.load(std::memory_order_acquire) &&
         !context.pumpComplete.load(std::memory_order_acquire);
         ++attempt) {
        std::this_thread::yield();
    }
    const bool hookInvoked =
        context.invoked.load(std::memory_order_acquire);
    if (!hookInvoked) {
        context.releaseClaim.store(true, std::memory_order_release);
        pumpThread.join();
        harken::detail::VoiceTimelineSinkTestAccess::
            SetVariableControlSliceClaimHook(engine->timelineSink, nullptr,
                                             nullptr);
        FAIL() << "initial audio slice claim hook was not reached";
        return;
    }
    switch (context.intent) {
    case StopAfterVariableControlSliceClaimContext::Intent::Stop:
        context.operationAccepted =
            harken::StopPlayable(*engine, started.instance, 0) ==
            harken::PlayableControlStatus::Ok;
        break;
    case StopAfterVariableControlSliceClaimContext::Intent::WorldReplacement:
        context.operationAccepted =
            harken::InstallContainerWorldV1(
                *engine, replacement.world).status ==
            harken::WorldInstallStatus::Backpressure;
        break;
    case StopAfterVariableControlSliceClaimContext::Intent::TransportReset:
        context.operationAccepted =
            harken::BeginRuntimeTransportReset(*engine, 0) ==
            harken::RuntimeTransportResetStatus::Backpressure;
        break;
    }
    const VnResult updateWhileClaimed = Vn_Update();
    harken::DecisionCommittedSnapshot decisionWhileClaimed{};
    const bool decisionPreserved = engine->decisions.CaptureCommitted(
        decision, &decisionWhileClaimed);
    harken::TimelineArmObservation armWhileClaimed{};
    const bool armPreserved = engine->timelineArms.Observe(
        member, &armWhileClaimed);
    harken::VariableControlInstanceSnapshot instanceWhileClaimed{};
    const bool sideCaptured = engine->variableControlInstances.Capture(
        row->variableControlInstance, &instanceWhileClaimed);
    const harken::VariableControlSideSnapshot sideWhileClaimed = continuous
        ? instanceWhileClaimed.continuous
        : instanceWhileClaimed.discrete;
    const harken::VoiceLedger::RenderOwner ownerWhileClaimed =
        engine->ledger.OwnerForRender(render);
    const harken::TimelineSemanticTarget targetWhileClaimed =
        engine->ReadPlayableMember(memberBase).voice.Facts().target;
    const bool rowDecisionPreserved = continuous
        ? row->variableControlContinuousDecisionCommitted &&
              row->variableControlContinuousDecision.slot == decision.slot &&
              row->variableControlContinuousDecision.generation ==
                  decision.generation
        : row->variableControlDiscreteDecisionCommitted &&
              row->variableControlDiscreteDecision.slot == decision.slot &&
              row->variableControlDiscreteDecision.generation ==
                  decision.generation;

    context.releaseClaim.store(true, std::memory_order_release);
    pumpThread.join();
    harken::detail::VoiceTimelineSinkTestAccess::
        SetVariableControlSliceClaimHook(engine->timelineSink, nullptr,
                                         nullptr);

    EXPECT_TRUE(context.operationAccepted);
    EXPECT_EQ(VN_OK, updateWhileClaimed);
    ASSERT_TRUE(decisionPreserved);
    EXPECT_EQ(harken::AudioGroupState::Pending,
              decisionWhileClaimed.audioState);
    ASSERT_TRUE(armPreserved);
    EXPECT_EQ(armBefore.state, armWhileClaimed.state);
    ASSERT_TRUE(sideCaptured);
    EXPECT_EQ(harken::VariableControlSideState::Transitioning, sideWhileClaimed.state);
    EXPECT_EQ(sideBefore.decision.slot, sideWhileClaimed.decision.slot);
    EXPECT_EQ(sideBefore.decision.generation,
              sideWhileClaimed.decision.generation);
    EXPECT_EQ(sideBefore.lastApplied.slot,
              sideWhileClaimed.lastApplied.slot);
    EXPECT_EQ(sideBefore.lastApplied.generation,
              sideWhileClaimed.lastApplied.generation);
    EXPECT_TRUE(rowDecisionPreserved);
    EXPECT_TRUE(ownerWhileClaimed.live);
    EXPECT_EQ(ownerBefore.ledgerSlot, ownerWhileClaimed.ledgerSlot);
    EXPECT_EQ(ownerBefore.parent.internalToken,
              ownerWhileClaimed.parent.internalToken);
    EXPECT_EQ(targetBefore.programSemanticFingerprint,
              targetWhileClaimed.programSemanticFingerprint);
    EXPECT_EQ(targetBefore.occurrenceOrdinal,
              targetWhileClaimed.occurrenceOrdinal);
    harken::DecisionCommittedSnapshot invalidated{};
    ASSERT_TRUE(engine->decisions.CaptureCommitted(decision, &invalidated));
    EXPECT_EQ(harken::AudioGroupState::Admitted,
              invalidated.audioState);
    harken::TimelineArmObservation memberAfterSlice{};
    ASSERT_TRUE(engine->timelineArms.Observe(member, &memberAfterSlice));
    EXPECT_EQ(harken::ArmState::Tombstoned, memberAfterSlice.state);
    EXPECT_EQ(identity.absoluteQuantum + 1u, memberAfterSlice.startedBlockSequence);
    const harken::VoiceRenderContext* voice = engine->voices.Resolve(render);
    ASSERT_NE(nullptr, voice);
    EXPECT_FALSE(voice->timelineGated);
    const std::uint32_t expectedReason =
        GetParam().intent ==
                StopAfterVariableControlSliceClaimContext::Intent::
                    TransportReset
            ? harken::AudioSliceReasonTransportReset
            : GetParam().intent ==
                      StopAfterVariableControlSliceClaimContext::Intent::
                          WorldReplacement
                  ? harken::AudioSliceReasonWorldReplacement
                  : harken::AudioSliceReasonCancel;
    const harken::AudioSliceLeaseSnapshot lease = group.lease->Capture();
    EXPECT_EQ(harken::AudioSliceState::SliceApplied, lease.state);
    EXPECT_EQ(expectedReason, lease.pendingReasonBits & expectedReason);
    EXPECT_TRUE(lease.invalidateAfterSlice);
    harken::FrontierActivationReceipt receipt{};
    ASSERT_EQ(harken::FrontierReceiptRead::Ready,
        activation->Read(row->frontierEntry, engine->mixer.BlocksRendered(), &receipt));
    EXPECT_EQ(harken::FrontierReceiptOutcome::Applied, receipt.outcome);

    ASSERT_EQ(VN_OK, Vn_Update());
    EXPECT_FALSE(row->variableControlDeferredCancellation);
    ASSERT_EQ(VN_OK, Vn_Update());
    EXPECT_FALSE(row->variableControlDeferredCancellation);
    bool stale = false;
    bool baselineRestored = false;
    for (std::uint32_t block = 0;
         block < 128 && !(stale && baselineRestored); ++block) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        stale = !engine->playableInstances.Classify(started.instance).live;
        baselineRestored =
            engine->voices.ActiveCount() == voiceBaseline &&
            engine->timelineArms.LiveCount() == armBaseline &&
            engine->decisions.LiveCount() == decisionBaseline &&
            engine->armGroups.LiveCount() == groupBaseline &&
            engine->playableInstances.LiveCount() == instanceBaseline;
    }
    EXPECT_TRUE(stale);
    EXPECT_TRUE(baselineRestored);
    EXPECT_FALSE(engine->runtimeRecreateRequired);
}

