TEST(PlayableStart,
     CurrentWorldReplacementInvalidatesCommittedPendingDiscreteRetarget) {
    VnConfig config = harkentest::MakeNullConfig(3, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    const std::uint32_t voiceBaseline = engine->voices.ActiveCount();
    const std::uint32_t armBaseline = engine->timelineArms.LiveCount();
    const std::uint32_t decisionBaseline = engine->decisions.LiveCount();
    const std::uint32_t groupBaseline = engine->armGroups.LiveCount();
    const std::uint32_t instanceBaseline =
        engine->playableInstances.LiveCount();

    std::vector<float> samples(65536, 0.125f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &pcm));
    const harken::VariableDefinitionV1 variable = {
        harkentest::ObjectId(41), harken::VariableKindV1::Step, 0.0f, 8.0f, 3.0f};
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harkentest::InstallDefinitionsWorld(
                  engine, &variable, 1,
                  UINT64_C(0x5643445245564953)).status);
    VariableControlDiscreteMembershipWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->variables.CurrentWorldGeneration());
    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    ASSERT_TRUE(PumpUntilAudible(*engine));
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), row);

    ASSERT_EQ(VN_OK, Vn_SetValue(harkentest::ObjectId(41), 7.0f));
    bool committedPending = false;
    for (std::uint32_t block = 0; block < 32 && !committedPending; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        harken::DecisionCommittedSnapshot snapshot{};
        committedPending =
            row->variableControlDiscreteRetargetDecisionCommitted &&
            engine->decisions.CaptureCommitted(
                row->VariablePayload().variableControlDiscreteRetargetDecision, &snapshot) &&
            snapshot.audioState == harken::AudioGroupState::Pending;
        if (!committedPending) engine->nullBackend.Pump(1);
    }
    ASSERT_TRUE(committedPending);
    row->variableControlWorldUsesCurrentAuthority = true;
    const harken::DecisionToken replacedDecision =
        row->VariablePayload().variableControlDiscreteRetargetDecision;
    const harken::TimelineArmToken entering =
        row->VariablePayload().variableControlDiscreteRetargetEnteringArm;
    ASSERT_TRUE(replacedDecision.Valid());

    PlayableWorldImage replacement(
        engine->registry.Lookup(kSound).contentRevision,
        harken::ContainerModeV1::Random);
    EXPECT_EQ(harken::WorldInstallStatus::Backpressure,
              harken::InstallContainerWorldV1(
                  *engine, replacement.world).status);

    harken::DecisionCommittedSnapshot invalidated{};
    ASSERT_TRUE(engine->decisions.CaptureCommitted(
        replacedDecision, &invalidated));
    EXPECT_EQ(harken::AudioGroupState::Invalidated,
              invalidated.audioState);

    bool replacedDecisionAdmitted = false;
    bool enteringStarted = false;
    bool stale = false;
    harken::PlayableControlState state{};
    for (std::uint32_t block = 0; block < 96 && !stale; ++block) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        harken::DecisionCommittedSnapshot committed{};
        if (engine->decisions.CaptureCommitted(
                replacedDecision, &committed)) {
            replacedDecisionAdmitted = replacedDecisionAdmitted ||
                committed.audioState == harken::AudioGroupState::Admitted ||
                committed.audioState ==
                    harken::AudioGroupState::PostStartInvalidated ||
                committed.audioState ==
                    harken::AudioGroupState::PostStartDeadlineInvalidated;
        }
        harken::TimelineArmObservation observation{};
        enteringStarted = enteringStarted ||
            (engine->timelineArms.Observe(entering, &observation) &&
             observation.state == harken::ArmState::Started);
        stale = harken::QueryPlayable(
                    *engine, started.instance, &state) ==
            harken::PlayableControlStatus::StaleHandle;
    }
    EXPECT_FALSE(replacedDecisionAdmitted);
    EXPECT_FALSE(enteringStarted);
    EXPECT_TRUE(stale);
    EXPECT_EQ(voiceBaseline, engine->voices.ActiveCount());
    EXPECT_EQ(armBaseline, engine->timelineArms.LiveCount());
    ASSERT_NO_FATAL_FAILURE(ExpectTransferredDecisionsReclaimed(*engine, decisionBaseline));
    EXPECT_EQ(groupBaseline, engine->armGroups.LiveCount());
    EXPECT_EQ(instanceBaseline, engine->playableInstances.LiveCount());
    EXPECT_FALSE(engine->runtimeRecreateRequired);
}

TEST(PlayableStart,
     TransportResetInvalidatesCommittedPendingDiscreteRetarget) {
    VnConfig config = harkentest::MakeNullConfig(3, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    const std::uint32_t voiceBaseline = engine->voices.ActiveCount();
    const std::uint32_t armBaseline = engine->timelineArms.LiveCount();
    const std::uint32_t decisionBaseline = engine->decisions.LiveCount();
    const std::uint32_t groupBaseline = engine->armGroups.LiveCount();
    const std::uint32_t instanceBaseline =
        engine->playableInstances.LiveCount();

    std::vector<float> samples(65536, 0.125f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &pcm));
    const harken::VariableDefinitionV1 variable = {
        harkentest::ObjectId(41), harken::VariableKindV1::Step, 0.0f, 8.0f, 3.0f};
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harkentest::InstallDefinitionsWorld(
                  engine, &variable, 1,
                  UINT64_C(0x5643445452524553)).status);
    VariableControlDiscreteMembershipWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->variables.CurrentWorldGeneration());
    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    ASSERT_TRUE(PumpUntilAudible(*engine));
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), row);

    ASSERT_EQ(VN_OK, Vn_SetValue(harkentest::ObjectId(41), 7.0f));
    bool committedPending = false;
    for (std::uint32_t block = 0; block < 32 && !committedPending; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        harken::DecisionCommittedSnapshot snapshot{};
        committedPending =
            row->variableControlDiscreteRetargetDecisionCommitted &&
            engine->decisions.CaptureCommitted(
                row->VariablePayload().variableControlDiscreteRetargetDecision, &snapshot) &&
            snapshot.audioState == harken::AudioGroupState::Pending;
        if (!committedPending) engine->nullBackend.Pump(1);
    }
    ASSERT_TRUE(committedPending);
    const harken::DecisionToken decision =
        row->VariablePayload().variableControlDiscreteRetargetDecision;
    const harken::TimelineArmToken entering =
        row->VariablePayload().variableControlDiscreteRetargetEnteringArm;
    const std::uint64_t resetFrame =
        engine->mixer.BlocksRendered() * engine->config.blockFrames;

    EXPECT_EQ(harken::RuntimeTransportResetStatus::Backpressure,
              harken::BeginRuntimeTransportReset(*engine, resetFrame));
    harken::DecisionCommittedSnapshot invalidated{};
    ASSERT_TRUE(engine->decisions.CaptureCommitted(decision, &invalidated));
    EXPECT_EQ(harken::AudioGroupState::Invalidated,
              invalidated.audioState);

    bool enteringStarted = false;
    harken::RuntimeTransportResetStatus reset =
        harken::RuntimeTransportResetStatus::Backpressure;
    for (std::uint32_t block = 0;
         block < 128 &&
         reset == harken::RuntimeTransportResetStatus::Backpressure;
         ++block) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        harken::TimelineArmObservation observation{};
        enteringStarted = enteringStarted ||
            (engine->timelineArms.Observe(entering, &observation) &&
             observation.state == harken::ArmState::Started);
        reset = harken::BeginRuntimeTransportReset(*engine, resetFrame);
    }
    EXPECT_EQ(harken::RuntimeTransportResetStatus::Complete, reset);
    EXPECT_FALSE(enteringStarted);
    harken::PlayableControlState state{};
    EXPECT_EQ(harken::PlayableControlStatus::StaleHandle,
              harken::QueryPlayable(*engine, started.instance, &state));
    EXPECT_EQ(voiceBaseline, engine->voices.ActiveCount());
    EXPECT_EQ(armBaseline, engine->timelineArms.LiveCount());
    EXPECT_EQ(decisionBaseline, engine->decisions.LiveCount());
    EXPECT_EQ(groupBaseline, engine->armGroups.LiveCount());
    EXPECT_EQ(instanceBaseline, engine->playableInstances.LiveCount());
    EXPECT_FALSE(engine->runtimeRecreateRequired);
}

TEST(PlayableStart,
     VariableControlStopDuringPreparedContinuousRetargetRejectsLateCommit) {
    VnConfig config = harkentest::MakeNullConfig(4, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    const std::uint32_t voiceBaseline = engine->voices.ActiveCount();
    const std::uint32_t armBaseline = engine->timelineArms.LiveCount();
    const std::uint32_t decisionBaseline = engine->decisions.LiveCount();
    const std::uint32_t groupBaseline = engine->armGroups.LiveCount();
    const std::uint32_t instanceBaseline =
        engine->playableInstances.LiveCount();

    std::vector<float> samples(65536, 0.125f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &pcm));
    const harken::VariableDefinitionV1 variable = {
        harkentest::ObjectId(41), harken::VariableKindV1::Smooth, 0.0f, 8.0f, 3.0f};
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harkentest::InstallDefinitionsWorld(
                  engine, &variable, 1,
                  UINT64_C(0x56434353544F5052)).status);
    VariableControlMembershipWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->variables.CurrentWorldGeneration());
    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    ASSERT_TRUE(PumpUntilAudible(*engine));
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), row);

    ASSERT_EQ(VN_OK, Vn_SetValue(harkentest::ObjectId(41), 7.0f));
    bool prepared = false;
    for (std::uint32_t block = 0; block < 32 && !prepared; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        prepared = row->variableControlRetargetPrepared &&
            !row->variableControlRetargetDecisionCommitted;
        if (!prepared) engine->nullBackend.Pump(1);
    }
    ASSERT_TRUE(prepared);
    const harken::DecisionToken stoppedDecision =
        row->VariablePayload().variableControlRetargetDecision;
    ASSERT_TRUE(stoppedDecision.Valid());
    harken::PlayableControlState state{};
    ASSERT_EQ(harken::PlayableControlStatus::Ok,
              harken::QueryPlayable(*engine, started.instance, &state));
    ASSERT_EQ(harken::PlayableControlLifecycle::Active, state.lifecycle);

    ASSERT_EQ(harken::PlayableControlStatus::Ok,
              harken::StopPlayable(*engine, started.instance, 0));
    ASSERT_EQ(harken::PlayableControlStatus::Ok,
              harken::QueryPlayable(*engine, started.instance, &state));
    EXPECT_EQ(harken::PlayableControlLifecycle::Cancelling, state.lifecycle);
    EXPECT_EQ(harken::PlayableControlStatus::Ok,
              harken::StopPlayable(*engine, started.instance, 99));

    bool stoppedDecisionCommitted = false;
    bool stale = false;
    for (std::uint32_t block = 0; block < 96 && !stale; ++block) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        harken::DecisionCommittedSnapshot committed{};
        stoppedDecisionCommitted = stoppedDecisionCommitted ||
            engine->decisions.CaptureCommitted(
                stoppedDecision, &committed);
        stale = harken::QueryPlayable(
                    *engine, started.instance, &state) ==
            harken::PlayableControlStatus::StaleHandle;
    }
    EXPECT_FALSE(stoppedDecisionCommitted);
    EXPECT_TRUE(stale)
        << "phase=" << static_cast<unsigned>(row->phase)
        << " lifecycle=" << static_cast<unsigned>(row->controlLifecycle)
        << " retargetPrepared=" << row->variableControlRetargetPrepared
        << " retargetCommitted="
        << row->variableControlRetargetDecisionCommitted
        << " retargetCleanup="
        << row->variableControlRetargetCleanupStarted
        << " retargetFinal="
        << row->variableControlRetargetMembershipFinalized
        << " retargetDecision="
        << row->VariablePayload().variableControlRetargetDecision.Valid()
        << " continuousDecision="
        << row->variableControlContinuousDecision.Valid()
        << " continuousCleanup="
        << row->variableControlContinuousCleanupStarted
        << " vcInstance=" << row->variableControlInstance.Valid();
    ASSERT_NO_FATAL_FAILURE(ExpectTransferredDecisionsReclaimed(*engine, decisionBaseline));
    EXPECT_EQ(voiceBaseline, engine->voices.ActiveCount());
    EXPECT_EQ(armBaseline, engine->timelineArms.LiveCount());
    EXPECT_EQ(decisionBaseline, engine->decisions.LiveCount());
    EXPECT_EQ(groupBaseline, engine->armGroups.LiveCount());
    EXPECT_EQ(instanceBaseline, engine->playableInstances.LiveCount());
    EXPECT_FALSE(engine->runtimeRecreateRequired);
}

