TEST(PlayableStart,
     VariableControlInitialMultiSidePageShortfallHasZeroMutation) {
    VnConfig config = harkentest::MakeNullConfig(4, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);

    const std::uint64_t observedFrame = engine->mixer.BlocksRendered() *
        engine->config.blockFrames;
    const std::uint64_t leadFrames = std::max<std::uint64_t>(
        1u, engine->timelinePool.PublishLeadQuanta()) *
        engine->config.blockFrames;
    const std::uint64_t startFrame = std::max(
        engine->timelinePool.PublishCutoffFrame(),
        observedFrame + leadFrames);
    std::array<harken::ScheduledEventInput, 128> firstEvents{};
    std::array<harken::ScheduledEventInput, 127> secondEvents{};
    for (std::uint32_t index = 0; index < firstEvents.size(); ++index) {
        firstEvents[index].executeFrame = startFrame;
        firstEvents[index].logicCommitSequence = index + 1u;
        firstEvents[index].eventIndex = index;
    }
    for (std::uint32_t index = 0; index < secondEvents.size(); ++index) {
        secondEvents[index].executeFrame = startFrame;
        secondEvents[index].logicCommitSequence = index + 129u;
        secondEvents[index].eventIndex = index;
    }
    harken::TransactionRequest filler{};
    filler.transactionId = 1;
    filler.transportEpoch = engine->timelinePool.Epoch();
    filler.events = firstEvents.data();
    filler.eventCount = firstEvents.size();
    ASSERT_EQ(harken::ReserveStatus::Committed,
              engine->timelinePool.Reserve(
                  filler, harken::PrePublishLatePolicy::Refuse,
                  engine->timelinePool.PublishCutoffFrame()).status);
    filler.transactionId = 2;
    filler.events = secondEvents.data();
    filler.eventCount = secondEvents.size();
    ASSERT_EQ(harken::ReserveStatus::Committed,
              engine->timelinePool.Reserve(
                  filler, harken::PrePublishLatePolicy::Refuse,
                  engine->timelinePool.PublishCutoffFrame()).status);

    std::vector<float> samples(4096, 0.125f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &pcm));
    const harken::VariableDefinitionV1 variable = {
        harkentest::ObjectId(41), harken::VariableKindV1::Step, 0.0f, 8.0f, 3.0f};
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harkentest::InstallDefinitionsWorld(
                  engine, &variable, 1,
                  UINT64_C(0x5643494E49544641)).status);
    VariableControlWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->variables.CurrentWorldGeneration(), true);
    const std::uint32_t voiceBaseline = engine->voices.ActiveCount();
    const std::uint32_t armBaseline = engine->timelineArms.LiveCount();
    const std::uint32_t decisionBaseline = engine->decisions.LiveCount();
    const std::uint32_t groupBaseline = engine->armGroups.LiveCount();
    const std::uint32_t instanceBaseline =
        engine->playableInstances.LiveCount();

    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult refused =
        harken::StartPlayable(*engine, image.world, request);
    EXPECT_EQ(harken::PlayableStartStatus::Backpressure, refused.status);
    EXPECT_EQ(0u, refused.instance);
    EXPECT_EQ(voiceBaseline, engine->voices.ActiveCount());
    EXPECT_EQ(armBaseline, engine->timelineArms.LiveCount());
    EXPECT_EQ(decisionBaseline, engine->decisions.LiveCount());
    EXPECT_EQ(groupBaseline, engine->armGroups.LiveCount());
    EXPECT_EQ(instanceBaseline, engine->playableInstances.LiveCount());
    EXPECT_TRUE(std::none_of(
        engine->playableServices.begin(), engine->playableServices.end(),
        [](const harken::EnginePlayableServiceRow& row) {
            return row.phase != harken::EnginePlayableStartPhase::Free;
        }));
    EXPECT_FALSE(engine->runtimeRecreateRequired);
}


TEST(PlayableStart,
     VariableControlInitialCommitBatchShortfallStaysRetryable) {
    VnConfig config = harkentest::MakeNullConfig(4, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    ASSERT_EQ(256u, engine->config.maxEventsPerQuantum);

    const std::uint64_t observedFrame = engine->mixer.BlocksRendered() *
        engine->config.blockFrames;
    const std::uint64_t leadFrames = std::max<std::uint64_t>(
        1u, engine->timelinePool.PublishLeadQuanta()) *
        engine->config.blockFrames;
    const std::uint64_t startFrame = std::max(
        engine->timelinePool.PublishCutoffFrame(),
        observedFrame + leadFrames);
    // Four slots remain. Member preflight fits; the commit batch also needs
    // the coordinator event and one event for each active side.
    std::array<harken::ScheduledEventInput, 128> firstEvents{};
    std::array<harken::ScheduledEventInput, 124> secondEvents{};
    for (std::uint32_t index = 0; index < firstEvents.size(); ++index) {
        firstEvents[index].executeFrame = startFrame;
        firstEvents[index].logicCommitSequence = index + 1u;
        firstEvents[index].eventIndex = index;
    }
    for (std::uint32_t index = 0; index < secondEvents.size(); ++index) {
        secondEvents[index].executeFrame = startFrame;
        secondEvents[index].logicCommitSequence = index + 129u;
        secondEvents[index].eventIndex = index;
    }
    harken::TransactionRequest filler{};
    filler.transactionId = 1;
    filler.transportEpoch = engine->timelinePool.Epoch();
    filler.events = firstEvents.data();
    filler.eventCount = firstEvents.size();
    ASSERT_EQ(harken::ReserveStatus::Committed,
              engine->timelinePool.Reserve(
                  filler, harken::PrePublishLatePolicy::Refuse,
                  engine->timelinePool.PublishCutoffFrame()).status);
    filler.transactionId = 2;
    filler.events = secondEvents.data();
    filler.eventCount = secondEvents.size();
    ASSERT_EQ(harken::ReserveStatus::Committed,
              engine->timelinePool.Reserve(
                  filler, harken::PrePublishLatePolicy::Refuse,
                  engine->timelinePool.PublishCutoffFrame()).status);

    std::vector<float> samples(4096, 0.125f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &pcm));
    const harken::VariableDefinitionV1 variable = {
        harkentest::ObjectId(41), harken::VariableKindV1::Step, 0.0f, 8.0f, 3.0f};
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harkentest::InstallDefinitionsWorld(
                  engine, &variable, 1,
                  UINT64_C(0x5643494E49544642)).status);
    VariableControlWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->variables.CurrentWorldGeneration(), true);
    const std::uint32_t voiceBaseline = engine->voices.ActiveCount();
    const std::uint32_t armBaseline = engine->timelineArms.LiveCount();
    const std::uint32_t decisionBaseline = engine->decisions.LiveCount();
    const std::uint32_t groupBaseline = engine->armGroups.LiveCount();
    const std::uint32_t instanceBaseline =
        engine->playableInstances.LiveCount();

    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult refused =
        harken::StartPlayable(*engine, image.world, request);
    EXPECT_EQ(harken::PlayableStartStatus::Backpressure, refused.status);
    EXPECT_EQ(0u, refused.instance);
    EXPECT_EQ(voiceBaseline, engine->voices.ActiveCount());
    EXPECT_EQ(armBaseline, engine->timelineArms.LiveCount());
    EXPECT_EQ(decisionBaseline, engine->decisions.LiveCount());
    EXPECT_EQ(groupBaseline, engine->armGroups.LiveCount());
    EXPECT_EQ(instanceBaseline, engine->playableInstances.LiveCount());
    EXPECT_TRUE(std::none_of(
        engine->playableServices.begin(), engine->playableServices.end(),
        [](const harken::EnginePlayableServiceRow& row) {
            return row.phase != harken::EnginePlayableStartPhase::Free;
        }));
    EXPECT_FALSE(engine->runtimeRecreateRequired);

    bool accepted = false;
    for (int step = 0; step < 48 && !accepted; ++step) {
        engine->nullBackend.Pump(8);
        ASSERT_EQ(VN_OK, Vn_Update());
        harken::PlayableStartRequest again{};
        again.root = image.Root();
        const harken::PlayableStartResult started =
            harken::StartPlayable(*engine, image.world, again);
        ASSERT_FALSE(engine->runtimeRecreateRequired);
        if (started.status == harken::PlayableStartStatus::Accepted) {
            accepted = true;
            EXPECT_NE(0u, started.instance);
        } else {
            EXPECT_EQ(harken::PlayableStartStatus::Backpressure, started.status);
        }
    }
    EXPECT_TRUE(accepted);
}

TEST(PlayableStart,
     VariableControlDiscreteReplacementPageShortfallHasZeroMutation) {
    VnConfig config = harkentest::MakeNullConfig(4, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);

    std::vector<float> samples(65536, 0.125f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &pcm));
    const harken::VariableDefinitionV1 variable = {
        harkentest::ObjectId(41), harken::VariableKindV1::Step, 0.0f, 8.0f, 3.0f};
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harkentest::InstallDefinitionsWorld(
                  engine, &variable, 1,
                  UINT64_C(0x5643445041474546)).status);
    VariableControlDiscreteMembershipWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->variables.CurrentWorldGeneration());
    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    ASSERT_TRUE(PumpUntilAudible(*engine));
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
    });
    ASSERT_NE(engine->playableServices.end(), row);
    // Settle the initial Start retirement before preparing the failed replacement.
    for (unsigned block = 0; block < 3; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    ASSERT_EQ(VN_OK, Vn_Update());
    ASSERT_EQ(VN_OK, Vn_SetValue(harkentest::ObjectId(41), 7.0f));
    engine->nullBackend.Pump(8);
    ASSERT_EQ(VN_OK, Vn_Update());
    harken::VariableControlInstanceSnapshot sideBefore{};
    ASSERT_TRUE(engine->variableControlInstances.Capture(
        row->variableControlInstance, &sideBefore));
    while (engine->mixer.BlocksRendered() * engine->config.blockFrames <
           row->variableControlDiscreteNextEvaluationFrame) {
        engine->nullBackend.Pump(1);
    }
    const std::uint64_t observedSequence = engine->mixer.BlocksRendered();
    const std::uint64_t observedFrame =
        observedSequence * engine->config.blockFrames;
    const std::uint64_t configuredRunway = std::max<std::uint64_t>(
        4u, engine->timelinePool.PublishLeadQuanta() + 2u);
    const std::uint64_t consumerFrontier =
        engine->timelinePool.ConsumerFrontier().load(
            std::memory_order_acquire);
    const std::uint64_t catchUpBacklog =
        observedSequence > consumerFrontier
            ? observedSequence - consumerFrontier
            : 0;
    const std::uint64_t firstOpen = std::max(
        engine->timelinePool.PublishCutoffFrame(),
        observedFrame +
            (configuredRunway + catchUpBacklog) *
                engine->config.blockFrames);
    std::uint64_t decisionFrame = 0;
    ASSERT_TRUE(harken::ResolveVariableControlCadenceFrame(
        row->startFrame, image.container.evaluationPeriodFrames,
        std::max(firstOpen,
                 row->variableControlDiscreteNextEvaluationFrame),
        &decisionFrame));
    std::array<harken::ScheduledEventInput, 128> firstEvents{};
    std::array<harken::ScheduledEventInput, 127> secondEvents{};
    for (std::uint32_t index = 0; index < firstEvents.size(); ++index) {
        firstEvents[index].executeFrame = decisionFrame;
        firstEvents[index].logicCommitSequence = index + 1u;
        firstEvents[index].eventIndex = index;
    }
    for (std::uint32_t index = 0; index < secondEvents.size(); ++index) {
        secondEvents[index].executeFrame = decisionFrame;
        secondEvents[index].logicCommitSequence = index + 129u;
        secondEvents[index].eventIndex = index;
    }
    harken::TransactionRequest filler{};
    filler.transactionId = UINT64_C(0xD15C0001);
    filler.transportEpoch = engine->timelinePool.Epoch();
    filler.events = firstEvents.data();
    filler.eventCount = firstEvents.size();
    ASSERT_EQ(harken::ReserveStatus::Committed,
              engine->timelinePool.Reserve(
                  filler, harken::PrePublishLatePolicy::Refuse,
                  engine->timelinePool.PublishCutoffFrame()).status);
    filler.transactionId = UINT64_C(0xD15C0002);
    filler.events = secondEvents.data();
    filler.eventCount = secondEvents.size();
    ASSERT_EQ(harken::ReserveStatus::Committed,
              engine->timelinePool.Reserve(
                  filler, harken::PrePublishLatePolicy::Refuse,
                  engine->timelinePool.PublishCutoffFrame()).status);
    std::uint32_t page = 0;
    ASSERT_TRUE(engine->timelinePool.PageForFrame(decisionFrame, &page));
    const harken::HorizonPageHeader* pageBefore =
        engine->timelinePool.Page(page);
    ASSERT_NE(nullptr, pageBefore);
    const std::uint32_t transactionsBefore =
        pageBefore->committedTransactionCount;
    const std::uint32_t voicesBefore = engine->voices.ActiveCount();
    const std::uint32_t armsBefore = engine->timelineArms.LiveCount();
    const std::uint32_t decisionsBefore = engine->decisions.LiveCount();
    const std::uint32_t groupsBefore = engine->armGroups.LiveCount();
    const std::uint32_t ledgerBefore =
        engine->ledger.AvailableEntryCount();
    const std::uint64_t commandsBefore = engine->commands.PublishedHead();
    const std::uint32_t leafCountBefore = row->scheduleLeafCount;

    ASSERT_EQ(VN_OK, Vn_Update());

    EXPECT_FALSE(row->variableControlDiscreteRetargetPrepared);
    EXPECT_EQ(leafCountBefore, row->scheduleLeafCount);
    EXPECT_EQ(voicesBefore, engine->voices.ActiveCount());
    EXPECT_EQ(armsBefore, engine->timelineArms.LiveCount());
    EXPECT_EQ(decisionsBefore, engine->decisions.LiveCount());
    EXPECT_EQ(groupsBefore, engine->armGroups.LiveCount());
    EXPECT_EQ(ledgerBefore, engine->ledger.AvailableEntryCount());
    EXPECT_EQ(commandsBefore, engine->commands.PublishedHead());
    harken::VariableControlInstanceSnapshot sideAfter{};
    ASSERT_TRUE(engine->variableControlInstances.Capture(
        row->variableControlInstance, &sideAfter));
    EXPECT_EQ(sideBefore.discrete.state, sideAfter.discrete.state);
    EXPECT_EQ(sideBefore.discrete.decision.slot,
              sideAfter.discrete.decision.slot);
    EXPECT_EQ(sideBefore.discrete.decision.generation,
              sideAfter.discrete.decision.generation);
    EXPECT_EQ(sideBefore.discrete.lastApplied.generation,
              sideAfter.discrete.lastApplied.generation);
    ASSERT_TRUE(engine->timelinePool.PageForFrame(decisionFrame, &page));
    const harken::HorizonPageHeader* pageAfter =
        engine->timelinePool.Page(page);
    ASSERT_NE(nullptr, pageAfter);
    EXPECT_EQ(transactionsBefore,
              pageAfter->committedTransactionCount);
    EXPECT_FALSE(engine->runtimeRecreateRequired);
}

