TEST(PlayableStart,
     VariableControlTransitionMixUsesAuthoredTargetCurve) {
    VnConfig config = harkentest::MakeNullConfig(3, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);

    std::vector<float> samples(65536, 0.125f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &pcm));
    const harken::VariableDefinitionV1 variable = {
        harkentest::ObjectId(41), harken::VariableKindV1::Step, 0.0f, 8.0f, 3.0f};
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harkentest::InstallDefinitionsWorld(
                  engine, &variable, 1,
                  UINT64_C(0x5643545243555256)).status);
    VariableControlDiscreteMembershipWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->variables.CurrentWorldGeneration());
    image.container.maxActiveRows = 0;
    image.container.maxLiveRows = 0;
    image.SetImmediateFades(128, 128);
    image.transitionCurves[1].curve.handles[0] = {
        1.0f / 3.0f, 0.0f, 2.0f / 3.0f, 0.0f};

    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    ASSERT_TRUE(PumpUntilAudible(*engine));
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), row);

    ASSERT_EQ(VN_OK, Vn_SetValue(harkentest::ObjectId(41), 7.0f));
    for (std::uint32_t block = 0;
         block < 64 && !row->variableControlDiscreteRetargetPrepared;
         ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        if (!row->variableControlDiscreteRetargetPrepared) {
            engine->nullBackend.Pump(1);
        }
    }
    ASSERT_TRUE(row->variableControlDiscreteRetargetPrepared);
    const std::uint64_t decisionFrame =
        row->VariablePayload().variableControlDiscreteRetargetFrame;
    while (engine->mixer.BlocksRendered() * engine->config.blockFrames <
           decisionFrame) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    ASSERT_EQ(decisionFrame,
              engine->mixer.BlocksRendered() * engine->config.blockFrames);
    const std::uint32_t channels = engine->nullBackend.Channels();
    const std::uint32_t frames = engine->nullBackend.BlockFrames();
    const float beforeTransition = std::abs(
        engine->nullBackend.LastBlock()[(frames - 1u) * channels]);

    ASSERT_EQ(VN_OK, Vn_Update());
    engine->nullBackend.Pump(1);
    const float firstTransitionBlockLast = std::abs(
        engine->nullBackend.LastBlock()[(frames - 1u) * channels]);
    ASSERT_EQ(VN_OK, Vn_Update());
    engine->nullBackend.Pump(1);
    const float completedTransitionLast = std::abs(
        engine->nullBackend.LastBlock()[(frames - 1u) * channels]);

    ASSERT_GT(beforeTransition, harkentest::kSilenceFloor);
    ASSERT_GT(completedTransitionLast, harkentest::kSilenceFloor);
    EXPECT_LT(firstTransitionBlockLast,
              completedTransitionLast * 0.75f);
}

TEST(PlayableStart,
     SequenceQueueNaturalEndFadesBeforeKnownCompletion) {
    VnConfig config = harkentest::MakeNullConfig(3, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);

    std::vector<float> first(2048, 0.25f);
    std::vector<float> second(2048, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSecondSound, &secondPcm));
    SequenceQueueWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision);
    image.EnableNaturalEndTransition(256, 192);
    const std::uint32_t transitionBaseline =
        engine->transitionInstances.LiveCount();

    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    ASSERT_TRUE(row->queueContinuationPrepared);
    ASSERT_TRUE(row->QueueFiling().queueTransition.Valid());
    const harken::TransitionInstanceToken transitionToken =
        row->QueueFiling().queueTransition;
    const harken::QueueInstanceToken queueToken = row->queueInstance;
    const VnVoiceHandle sourceVoice = row->renderHandle;
    const VnVoiceHandle targetVoice =
        row->QueuePayload().queueSuccessorRenderHandle;
    const std::uint64_t naturalEndFrame = row->QueuePayload().queueCompletionFrame;
    const std::uint64_t audibleFrame = naturalEndFrame - 256u;
    ASSERT_TRUE(row->QueuePayload().queueSourceArm.Valid());
    const harken::TimelineArmToken sourceArmToken = row->QueuePayload().queueSourceArm;
    ASSERT_EQ(1u, row->QueueRuntimeViews().queueSourceRuntimeProgram.payloadCount);
    EXPECT_EQ(harken::TimelineEventKind::Envelope,
              row->QueueRuntimeViews().queueSourceRuntimeProgram.payloads[0].kind);
    EXPECT_EQ(audibleFrame,
              row->QueueRuntimeViews().queueSourceRuntimeProgram.payloads[0].
                  envelopeStartFrame);
    EXPECT_EQ(naturalEndFrame,
              row->QueueRuntimeViews().queueSourceRuntimeProgram.payloads[0].
                  envelopeEndFrame);
    EXPECT_EQ(naturalEndFrame,
              row->QueueFiling().queueSuccessorSchedule.entryAnchorFrame);
    harken::TransitionInstanceSnapshot transition{};
    ASSERT_TRUE(engine->transitionInstances.Capture(
        transitionToken, &transition));
    EXPECT_EQ(audibleFrame, transition.audibleFrame);

    while (engine->mixer.BlocksRendered() *
               engine->config.blockFrames <= audibleFrame) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    const auto* sourceAtFade = engine->voices.Resolve(sourceVoice);
    const auto* targetBeforeEnd = engine->voices.Resolve(targetVoice);
    ASSERT_NE(nullptr, sourceAtFade);
    ASSERT_NE(nullptr, targetBeforeEnd);
    EXPECT_TRUE(sourceAtFade->timelineEnvelopes[1].active);
    EXPECT_TRUE(targetBeforeEnd->timelineGated);
    ASSERT_TRUE(engine->transitionInstances.Capture(
        transitionToken, &transition));
    EXPECT_EQ(harken::TransitionAudibleGateState::Locked,
              transition.state);
    harken::DecisionCommittedSnapshot decisionAtFade{};
    ASSERT_TRUE(engine->decisions.CaptureCommitted(
        row->QueueFiling().queueDecision, &decisionAtFade));
    EXPECT_EQ(harken::AudioGroupState::AudioClaimed,
              decisionAtFade.audioState);
    harken::QueueInstanceSnapshot queue{};
    ASSERT_TRUE(engine->queueInstances.Capture(queueToken, &queue));
    EXPECT_EQ(harken::ConditionalQueueActivation::Waiting,
              queue.pendingActivation);

    const std::uint64_t completionQuantum =
        naturalEndFrame / engine->config.blockFrames;
    for (std::uint32_t block = 0;
         block < 8 &&
         engine->timelinePool.ConsumerFrontier().load() <=
             completionQuantum;
         ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    EXPECT_GT(engine->timelinePool.ConsumerFrontier().load(),
              completionQuantum);
    ASSERT_TRUE(engine->queueInstances.Capture(queueToken, &queue));
    harken::DecisionCommittedSnapshot decisionAfter{};
    ASSERT_TRUE(engine->decisions.CaptureCommitted(
        row->QueueFiling().queueDecision, &decisionAfter));
    harken::TimelineArmObservation sourceArmAfter{};
    ASSERT_TRUE(engine->timelineArms.Observe(
        sourceArmToken, &sourceArmAfter));
    EXPECT_EQ(2u, decisionAfter.sliceCount);
    EXPECT_EQ(harken::ArmState::Tombstoned, sourceArmAfter.state);
    EXPECT_EQ(0u,
              engine->timelineExecutor.Stats().armFailedTransactions);
    EXPECT_EQ(harken::ConditionalQueueActivation::Activated,
              queue.pendingActivation);
    EXPECT_EQ(nullptr, engine->voices.Resolve(sourceVoice));
    const auto* targetAfterEnd = engine->voices.Resolve(targetVoice);
    ASSERT_NE(nullptr, targetAfterEnd);
    EXPECT_FALSE(targetAfterEnd->timelineGated);
    EXPECT_TRUE(targetAfterEnd->timelineEnvelopes[0].active);
    for (std::uint32_t block = 0;
         block < 48 &&
         engine->transitionInstances.LiveCount() != transitionBaseline;
         ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    EXPECT_EQ(transitionBaseline,
              engine->transitionInstances.LiveCount());
    EXPECT_FALSE(engine->runtimeRecreateRequired);
}

TEST(PlayableStart,
     SequenceQueueNaturalEndSameQuantumAppliesPreludeAndCompletionSlices) {
    VnConfig config = harkentest::MakeNullConfig(3, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);

    std::vector<float> first(96, 0.25f);
    std::vector<float> second(96, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSecondSound, &secondPcm));
    SequenceQueueWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision);
    image.EnableNaturalEndTransition(32, 0);

    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    ASSERT_TRUE(row->queueContinuationPrepared);
    const std::uint64_t preludeFrame = row->QueuePayload().queueCompletionFrame - 32u;
    ASSERT_EQ(preludeFrame / engine->config.blockFrames,
              row->QueuePayload().queueCompletionFrame / engine->config.blockFrames);
    const std::uint64_t transitionQuantum =
        preludeFrame / engine->config.blockFrames;
    const harken::DecisionToken decision = row->QueueFiling().queueDecision;
    for (std::uint32_t block = 0;
         block < 8 && !row->QueueFiling().queueDecisionCommitted; ++block) {
        ASSERT_LT(engine->mixer.BlocksRendered(), transitionQuantum);
        ASSERT_EQ(VN_OK, Vn_Update());
        if (!row->QueueFiling().queueDecisionCommitted) {
            engine->nullBackend.Pump(1);
        }
    }
    ASSERT_TRUE(row->QueueFiling().queueDecisionCommitted);
    ASSERT_LT(engine->mixer.BlocksRendered(), transitionQuantum);
    const auto completionFrame = row->QueuePayload().queueCompletionFrame;
    for (std::uint16_t index = 0; index < 2; ++index) {
        harken::Plan03PageGroupView prepared{};
        const auto identity = harkentest::QueueContinuationSlice(*engine, decision, index);
        ASSERT_TRUE(engine->timelinePool.ResolvePlan03GroupSliceProducer(identity, &prepared));
        ASSERT_NE(nullptr, prepared.lease);
        EXPECT_EQ(harken::AudioSliceState::Ready, prepared.lease->Capture().state);
    }
    // A complete acknowledged group need not freeze its distant page yet.
    // Reach the existing rolling lead while both slices are still in the future.
    while (engine->timelinePool.PublishCutoffFrame() <= transitionQuantum * config.blockFrames) {
        ASSERT_LT(engine->mixer.BlocksRendered() + 1u, transitionQuantum);
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    ASSERT_LT(engine->mixer.BlocksRendered(), transitionQuantum);
    EXPECT_EQ(completionFrame, row->QueuePayload().queueCompletionFrame);
    ASSERT_EQ(VN_OK, Vn_Update());
    harken::Plan03PageGroupView preludeGroup{}, completionGroup{};
    ASSERT_TRUE(engine->timelinePool.ResolvePlan03GroupSliceRt(
        harkentest::QueueContinuationSlice(*engine, decision, 0), &preludeGroup));
    ASSERT_TRUE(engine->timelinePool.ResolvePlan03GroupSliceRt(
        harkentest::QueueContinuationSlice(*engine, decision, 1), &completionGroup));
    ASSERT_NE(nullptr, preludeGroup.lease);
    ASSERT_NE(nullptr, completionGroup.lease);

    while (engine->mixer.BlocksRendered() <=
           transitionQuantum) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }

    EXPECT_EQ(harken::AudioSliceState::SliceApplied,
              preludeGroup.lease->Capture().state);
    EXPECT_EQ(harken::AudioSliceState::SliceApplied,
              completionGroup.lease->Capture().state);
}

// These private scheduling declarations consume real Lane capacity without
// publishing events, pinning resources or acquiring any audio authority.
class QueueLaneCapacityPressure {
public:
    explicit QueueLaneCapacityPressure(harken::Engine& engine) : lane_(engine.immediateActionLane) {}
    ~QueueLaneCapacityPressure() {
        for (const auto handle : handles_) {
            EXPECT_TRUE(lane_.Cancel(handle));
            EXPECT_TRUE(lane_.Retire(handle));
        }
    }
    bool Place(std::uint64_t frame, std::uint32_t events, std::uint32_t groups) {
        while (events != 0 || groups != 0) {
            const auto eventCount = std::min(events, lane_.EventsPerAttempt());
            const auto groupCount = std::min(groups, lane_.EventsPerAttempt());
            harken::ImmediateLaneHandle handle{};
            if (!lane_.Reserve(1, {eventCount, groupCount, 0, 1}, &handle)) return false;
            handles_.push_back(handle);
            for (std::uint32_t i = 0; i < groupCount; ++i) {
                harken::ImmediateLaneDeclaredGroup group{};
                group.identity = {0, 1, {0, 1}, static_cast<std::uint16_t>(i)};
                group.identity.committedRow = i;
                group.identity.rowClaimGeneration = 1;
                group.identity.transportEpoch = 1;
                if (!lane_.DeclareGroup(handle, group)) return false;
            }
            std::vector<harken::ImmediateLaneEvent> input(eventCount);
            for (auto& event : input) event.event.program.program = &program_;
            if (!lane_.Prepare(handle, input.data(), eventCount) ||
                !lane_.TryPlaceExactPrivate(handle, frame)) return false;
            events -= eventCount;
            groups -= groupCount;
        }
        return true;
    }
    bool ExhaustAttempts() {
        for (std::uint32_t i = 0; i < lane_.AttemptCapacity(); ++i) {
            harken::ImmediateLaneHandle handle{};
            if (!lane_.Reserve(1, {1, 0, 0, 1}, &handle)) return false;
            handles_.push_back(handle);
        }
        harken::ImmediateLaneHandle extra{};
        return !lane_.Reserve(1, {1, 0, 0, 1}, &extra);
    }
private:
    harken::ImmediateActionLane& lane_;
    harken::TimelineProgramView program_{};
    std::vector<harken::ImmediateLaneHandle> handles_;
};

TEST(PlayableStart,
     SequenceQueueNaturalEndSameQuantumLaneCapacityPublishesNeitherSlice) {
    VnConfig config = harkentest::MakeNullConfig(4, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);

    std::vector<float> first(96, 0.25f);
    std::vector<float> second(96, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSecondSound, &secondPcm));
    SequenceQueueWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision);
    image.EnableNaturalEndTransition(32, 0);

    const std::uint64_t startFrame =
        KnownFiniteQueuePublishableStart(*engine);
    const std::uint64_t completionFrame = startFrame + first.size();
    const std::uint64_t preludeFrame = completionFrame - 32u;
    ASSERT_EQ(preludeFrame / engine->config.blockFrames,
              completionFrame / engine->config.blockFrames);

    const auto groupCapacity = engine->config.maxPlan03GroupHeadersPerPage;
    ASSERT_GE(groupCapacity, 2u);
    QueueLaneCapacityPressure pressure(*engine);
    ASSERT_TRUE(pressure.Place(preludeFrame, 0, groupCapacity - 1u));
    const std::uint32_t transitionBaseline =
        engine->transitionInstances.LiveCount();

    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    EXPECT_EQ(completionFrame, row->QueuePayload().queueCompletionFrame);
    EXPECT_FALSE(row->queueContinuationPrepared);
    EXPECT_FALSE(row->QueueFiling().queueConditional.Valid());
    EXPECT_FALSE(row->QueueFiling().queueTransition.Valid());
    harken::ArmGroupSnapshot abandonedGroup{};
    EXPECT_FALSE(engine->armGroups.Capture(row->QueueFiling().queueArmGroup, &abandonedGroup));
    EXPECT_EQ(nullptr, engine->timelineArms.Resolve(row->QueueFiling().queueSuccessorArm));
    EXPECT_EQ(nullptr, engine->voices.Resolve(row->QueuePayload().queueSuccessorRenderHandle));
    EXPECT_EQ(transitionBaseline,
              engine->transitionInstances.LiveCount());
    EXPECT_TRUE(pressure.Place(preludeFrame, 0, 1));
}

TEST(PlayableStart,
     SequenceQueueTransitionLaneEventShortfallHasZeroMutation) {
    VnConfig config = harkentest::MakeNullConfig(4, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);

    std::vector<float> first(96, 0.25f);
    std::vector<float> second(96, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSecondSound, &secondPcm));
    SequenceQueueWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision,
        harken::QueueCycleV1::Once, false,
        harken::AuthoredCompletionClassV1::FiniteMediaCandidate,
        harken::SignalOnlyPolicyV1::StopQueue,
        harken::QueueSpliceV1::Butt, true);
    image.EnableImmediateTransition(1, 1);

    const std::uint64_t startFrame =
        KnownFiniteQueuePublishableStart(*engine);
    const std::uint64_t completionFrame = startFrame + first.size();
    ASSERT_EQ(completionFrame / engine->config.blockFrames,
              (completionFrame + 1u) / engine->config.blockFrames);

    QueueLaneCapacityPressure pressure(*engine);
    const auto eventCapacity = engine->immediateActionLane.MaxEventsPerQuantum();
    ASSERT_GT(eventCapacity, 3u);
    ASSERT_TRUE(pressure.Place(completionFrame, eventCapacity - 3u, 0));

    std::uint32_t page = 0;
    ASSERT_TRUE(engine->timelinePool.PageForFrame(completionFrame, &page));
    const harken::HorizonPageHeader* pageBefore =
        engine->timelinePool.Page(page);
    ASSERT_NE(nullptr, pageBefore);
    const std::uint32_t transactionsBefore =
        pageBefore->committedTransactionCount;
    const std::uint32_t transitionsBefore =
        engine->transitionInstances.LiveCount();

    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), row);

    EXPECT_EQ(completionFrame, row->QueuePayload().queueCompletionFrame);
    EXPECT_FALSE(row->queueContinuationPrepared);
    EXPECT_FALSE(row->QueueFiling().queueConditional.Valid());
    EXPECT_FALSE(row->QueueFiling().queueTransition.Valid());
    EXPECT_FALSE(row->QueuePayload().queueSourceArm.Valid());
    harken::ArmGroupSnapshot abandonedGroup{};
    EXPECT_FALSE(engine->armGroups.Capture(row->QueueFiling().queueArmGroup, &abandonedGroup));
    EXPECT_EQ(nullptr, engine->timelineArms.Resolve(row->QueueFiling().queueSuccessorArm));
    EXPECT_EQ(nullptr, engine->voices.Resolve(row->QueuePayload().queueSuccessorRenderHandle));
    EXPECT_EQ(transitionsBefore,
              engine->transitionInstances.LiveCount());
    const harken::HorizonPageHeader* pageAfter =
        engine->timelinePool.Page(page);
    ASSERT_NE(nullptr, pageAfter);
    EXPECT_EQ(transactionsBefore,
              pageAfter->committedTransactionCount);
    EXPECT_FALSE(engine->runtimeRecreateRequired);
    bool heardCurrent = false;
    for (std::uint32_t block = 0; block < 40; ++block) {
        engine->nullBackend.Pump(1);
        const auto* output = engine->nullBackend.LastBlock();
        ASSERT_NE(nullptr, output);
        for (std::uint32_t sample = 0; sample < 2u * config.blockFrames; ++sample)
            heardCurrent = heardCurrent || output[sample] > 0.01f;
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    EXPECT_TRUE(heardCurrent);
    EXPECT_EQ(0u, engine->voices.ActiveCount());
    EXPECT_EQ(0u, engine->playableInstances.LiveCount());
    EXPECT_EQ(0u, engine->queueInstances.LiveCount());
    EXPECT_EQ(0u, engine->armGroups.LiveCount());
    EXPECT_EQ(0u, engine->timelineArms.LiveCount());
    EXPECT_EQ(0u, engine->timelineOccurrences.OccupiedCount());
    EXPECT_FALSE(engine->runtimeRecreateRequired);
}

TEST(PlayableStart,
     SequenceQueueNaturalEndZeroDurationSourceFadeUsesTargetAudiblePhase) {
    VnConfig config = harkentest::MakeNullConfig(3, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);

    std::vector<float> first(2048, 0.25f);
    std::vector<float> second(2048, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSecondSound, &secondPcm));
    SequenceQueueWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision);
    image.EnableNaturalEndTransition(1, 192);
    image.transitionRules[0].sourceFade.durationFrames = 0;
    const std::uint32_t transitionBaseline =
        engine->transitionInstances.LiveCount();

    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    ASSERT_TRUE(row->queueContinuationPrepared);
    ASSERT_TRUE(row->QueueFiling().queueTransition.Valid());
    EXPECT_FALSE(row->QueuePayload().queueSourceArm.Valid());
    EXPECT_EQ(0u, row->QueueRuntimeViews().queueSourceRuntimeProgram.payloadCount);
    harken::ArmGroupSnapshot group{};
    ASSERT_TRUE(engine->armGroups.Capture(row->QueueFiling().queueArmGroup, &group));
    EXPECT_EQ(1u, group.memberCount);
    const harken::TransitionInstanceToken transitionToken =
        row->QueueFiling().queueTransition;
    const harken::DecisionToken decisionToken = row->QueueFiling().queueDecision;
    const harken::QueueInstanceToken queueToken = row->queueInstance;
    const VnVoiceHandle sourceVoice = row->renderHandle;
    const VnVoiceHandle targetVoice = row->QueuePayload().queueSuccessorRenderHandle;
    const std::uint64_t completionQuantum =
        row->QueuePayload().queueCompletionFrame / engine->config.blockFrames;
    harken::TransitionInstanceSnapshot transition{};
    ASSERT_TRUE(engine->transitionInstances.Capture(
        transitionToken, &transition));
    EXPECT_EQ(row->QueuePayload().queueCompletionFrame, transition.audibleFrame);

    const std::uint64_t listenBlocks = completionQuantum + 8u;
    for (std::uint32_t block = 0;
         block < listenBlocks &&
         engine->timelinePool.ConsumerFrontier().load() <=
             completionQuantum;
         ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    EXPECT_GT(engine->timelinePool.ConsumerFrontier().load(),
              completionQuantum);
    harken::DecisionCommittedSnapshot decision{};
    ASSERT_TRUE(engine->decisions.CaptureCommitted(
        decisionToken, &decision));
    EXPECT_EQ(1u, decision.sliceCount);
    harken::QueueInstanceSnapshot queue{};
    ASSERT_TRUE(engine->queueInstances.Capture(queueToken, &queue));
    EXPECT_EQ(harken::ConditionalQueueActivation::Activated,
              queue.pendingActivation);
    ASSERT_TRUE(engine->transitionInstances.Capture(
        transitionToken, &transition));
    EXPECT_EQ(harken::TransitionAudibleGateState::Locked,
              transition.state);
    EXPECT_EQ(nullptr, engine->voices.Resolve(sourceVoice));
    const auto* target = engine->voices.Resolve(targetVoice);
    ASSERT_NE(nullptr, target);
    EXPECT_FALSE(target->timelineGated);
    EXPECT_TRUE(target->timelineEnvelopes[0].active);
    EXPECT_EQ(0u,
              engine->timelineExecutor.Stats().armFailedTransactions);

    for (std::uint32_t block = 0;
         block < 48 &&
         engine->transitionInstances.LiveCount() != transitionBaseline;
         ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    EXPECT_EQ(transitionBaseline,
              engine->transitionInstances.LiveCount());
    EXPECT_FALSE(engine->runtimeRecreateRequired);
}

TEST_P(NaturalEndQueueCancellationTest,
       FadePreludeCancellationReclaimsTransitionAuthority) {
    VnConfig config = harkentest::MakeNullConfig(3, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);

    std::vector<float> first(1024, 0.25f);
    std::vector<float> second(1024, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSecondSound, &secondPcm));
    PlayableWorldImage current(
        engine->registry.Lookup(kSound).contentRevision,
        harken::ContainerModeV1::Random);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(
                  *engine, current.world).status);
    const harken::WorldGeneration worldBefore =
        engine->variables.CurrentWorldGeneration();
    const harken::TransportEpoch transportBefore =
        engine->transportEpochOwner.Current();
    SequenceQueueWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision);
    image.EnableNaturalEndTransition(256, 192);
    const std::uint32_t voiceBaseline = engine->voices.ActiveCount();
    const std::uint32_t armBaseline = engine->timelineArms.LiveCount();
    const std::uint32_t queueBaseline =
        engine->queueInstances.LiveCount();
    const std::uint32_t decisionBaseline = engine->decisions.LiveCount();
    const std::uint32_t groupBaseline = engine->armGroups.LiveCount();
    const std::uint32_t occurrenceBaseline =
        engine->timelineOccurrences.OccupiedCount();
    const std::uint32_t transitionBaseline =
        engine->transitionInstances.LiveCount();
    const std::uint32_t instanceBaseline =
        engine->playableInstances.LiveCount();

    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    ASSERT_TRUE(row->QueuePayload().queueSourceArm.Valid());
    ASSERT_TRUE(row->QueueFiling().queueTransition.Valid());
    const harken::TimelineArmToken sourceArm = row->QueuePayload().queueSourceArm;
    const harken::TimelineArmToken targetArm = row->QueueFiling().queueSuccessorArm;
    const harken::TransitionInstanceToken transition =
        row->QueueFiling().queueTransition;

    bool preludeApplied = false;
    const std::uint64_t preludeLimit =
        row->QueuePayload().queueCompletionFrame / engine->config.blockFrames + 8u;
    while (engine->mixer.BlocksRendered() <= preludeLimit &&
           !preludeApplied) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        harken::TimelineArmObservation arm{};
        harken::TransitionInstanceSnapshot gate{};
        preludeApplied = engine->timelineArms.Observe(sourceArm, &arm) &&
            arm.state == harken::ArmState::AudioClaimed &&
            engine->transitionInstances.Capture(transition, &gate) &&
            gate.state == harken::TransitionAudibleGateState::Locked;
    }
    ASSERT_TRUE(preludeApplied);
    PlayableWorldImage replacement(
        engine->registry.Lookup(kSound).contentRevision,
        harken::ContainerModeV1::Sequence);
    switch (GetParam()) {
    case StopAfterVariableControlSliceClaimContext::Intent::Stop:
        ASSERT_EQ(harken::PlayableControlStatus::Ok,
                  harken::StopPlayable(*engine, started.instance, 0));
        break;
    case StopAfterVariableControlSliceClaimContext::Intent::WorldReplacement:
        row->queueWorldUsesCurrentAuthority = true;
        ASSERT_EQ(harken::WorldInstallStatus::Backpressure,
                  harken::InstallContainerWorldV1(
                      *engine, replacement.world).status);
        break;
    case StopAfterVariableControlSliceClaimContext::Intent::TransportReset:
        ASSERT_EQ(harken::RuntimeTransportResetStatus::Backpressure,
                  harken::BeginRuntimeTransportReset(*engine, 0));
        break;
    }
    harken::TimelineArmObservation cancelledSource{};
    ASSERT_TRUE(engine->timelineArms.Observe(
        sourceArm, &cancelledSource));
    EXPECT_EQ(harken::ArmState::CancelRequested,
              cancelledSource.state);
    harken::TransitionInstanceSnapshot retainedTransition{};
    ASSERT_TRUE(engine->transitionInstances.Capture(
        transition, &retainedTransition));
    EXPECT_EQ(transitionBaseline + 1u,
              engine->transitionInstances.LiveCount());
    ASSERT_EQ(VN_OK, Vn_Update());
    EXPECT_TRUE(engine->transitionInstances.Capture(
        transition, &retainedTransition));

    bool operationComplete =
        GetParam() == StopAfterVariableControlSliceClaimContext::Intent::Stop;
    bool targetStarted = false;
    for (std::uint32_t block = 0;
         block < 256 &&
         (engine->playableInstances.Classify(started.instance).live ||
          !operationComplete);
         ++block) {
        harken::TimelineArmObservation target{};
        targetStarted = targetStarted ||
            (engine->timelineArms.Observe(targetArm, &target) &&
             target.state == harken::ArmState::Started);
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        if (GetParam() == StopAfterVariableControlSliceClaimContext::Intent::
                              WorldReplacement) {
            operationComplete = harken::InstallContainerWorldV1(
                *engine, replacement.world).status ==
                harken::WorldInstallStatus::Ok;
        } else if (GetParam() ==
                   StopAfterVariableControlSliceClaimContext::Intent::
                       TransportReset) {
            operationComplete = harken::BeginRuntimeTransportReset(
                *engine, 0) ==
                harken::RuntimeTransportResetStatus::Complete;
        }
    }
    EXPECT_FALSE(targetStarted);
    EXPECT_FALSE(engine->playableInstances.Classify(started.instance).live);
    EXPECT_TRUE(operationComplete);
    EXPECT_EQ(voiceBaseline, engine->voices.ActiveCount());
    EXPECT_EQ(armBaseline, engine->timelineArms.LiveCount());
    EXPECT_EQ(queueBaseline, engine->queueInstances.LiveCount());
    EXPECT_EQ(decisionBaseline, engine->decisions.LiveCount());
    EXPECT_EQ(groupBaseline, engine->armGroups.LiveCount());
    EXPECT_EQ(occurrenceBaseline,
              engine->timelineOccurrences.OccupiedCount());
    EXPECT_EQ(transitionBaseline,
              engine->transitionInstances.LiveCount());
    EXPECT_EQ(instanceBaseline, engine->playableInstances.LiveCount());
    if (GetParam() == StopAfterVariableControlSliceClaimContext::Intent::
                          WorldReplacement) {
        EXPECT_NE(worldBefore,
                  engine->variables.CurrentWorldGeneration());
    }
    if (GetParam() == StopAfterVariableControlSliceClaimContext::Intent::
                          TransportReset) {
        EXPECT_GT(engine->transportEpochOwner.Current(), transportBefore);
    }
    EXPECT_FALSE(engine->runtimeRecreateRequired);
}

INSTANTIATE_TEST_SUITE_P(
    StopWorldAndReset,
    NaturalEndQueueCancellationTest,
    testing::Values(
        StopAfterVariableControlSliceClaimContext::Intent::Stop,
        StopAfterVariableControlSliceClaimContext::Intent::WorldReplacement,
        StopAfterVariableControlSliceClaimContext::Intent::TransportReset));

TEST_P(ClaimedQueueSliceCancellationTest,
       ClaimedPreludeDefersCancellationWithoutPartialMutation) {
    VnConfig config = harkentest::MakeNullConfig(3, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);

    std::vector<float> first(1024, 0.25f);
    std::vector<float> second(1024, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSecondSound, &secondPcm));
    SequenceQueueWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision);
    image.EnableNaturalEndTransition(256, 192);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(
                  *engine, image.InstallView()).status);
    const harken::WorldGeneration installedWorld =
        engine->variables.CurrentWorldGeneration();
    const harken::TransportEpoch transportBefore =
        engine->transportEpochOwner.Current();
    const std::uint32_t voiceBaseline = engine->voices.ActiveCount();
    const std::uint32_t armBaseline = engine->timelineArms.LiveCount();
    const std::uint32_t queueBaseline =
        engine->queueInstances.LiveCount();
    const std::uint32_t decisionBaseline = engine->decisions.LiveCount();
    const std::uint32_t groupBaseline = engine->armGroups.LiveCount();
    const std::uint32_t occurrenceBaseline =
        engine->timelineOccurrences.OccupiedCount();
    const std::uint32_t transitionBaseline =
        engine->transitionInstances.LiveCount();
    const std::uint32_t instanceBaseline =
        engine->playableInstances.LiveCount();

    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult started =
        harken::StartCurrentPlayable(request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    ASSERT_TRUE(row->QueueFiling().queueTransition.Valid());
    ASSERT_TRUE(row->QueuePayload().queueSourceArm.Valid());
    ASSERT_TRUE(row->QueueFiling().queueSuccessorArm.Valid());

    harken::DecisionCommittedSnapshot pending{};
    bool committedPending = false;
    for (std::uint32_t block = 0; block < 16 && !committedPending; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        committedPending = row->QueueFiling().queueDecisionCommitted &&
            engine->decisions.CaptureCommitted(
                row->QueueFiling().queueDecision, &pending) &&
            pending.audioState == harken::AudioGroupState::Pending;
        if (!committedPending) engine->nullBackend.Pump(1);
    }
    ASSERT_TRUE(committedPending);
    ASSERT_EQ(2u, pending.sliceCount);
    const harken::DecisionToken decision = row->QueueFiling().queueDecision;
    const harken::ConditionalQueueVersionToken conditional =
        row->QueueFiling().queueConditional;
    const harken::TransitionInstanceToken transition =
        row->QueueFiling().queueTransition;
    const harken::TimelineArmToken sourceArm = row->QueuePayload().queueSourceArm;
    const harken::TimelineArmToken targetArm = row->QueueFiling().queueSuccessorArm;
    harken::TransitionInstanceSnapshot gate{};
    ASSERT_TRUE(engine->transitionInstances.Capture(transition, &gate));
    const std::uint64_t preludeQuantum =
        gate.audibleFrame / engine->config.blockFrames;
    std::uint32_t page = 0;
    ASSERT_TRUE(engine->timelinePool.PageForFrame(gate.audibleFrame, &page));
    const harken::HorizonPageHeader* header =
        engine->timelinePool.Page(page);
    ASSERT_NE(nullptr, header);
    harken::Plan03PageGroupView group{};
    const auto identity = harkentest::QueueContinuationSlice(*engine, decision, 0);
    ASSERT_TRUE(engine->timelinePool.ResolvePlan03GroupSliceProducer(
        identity, &group));
    ASSERT_NE(nullptr, group.lease);
    harken::Plan03PageGroupView completionGroup{};
    const auto completionIdentity = harkentest::QueueContinuationSlice(*engine, decision, 1);
    ASSERT_TRUE(engine->timelinePool.ResolvePlan03GroupSliceProducer(
        completionIdentity, &completionGroup));
    ASSERT_NE(nullptr, completionGroup.lease);
    ASSERT_LE(engine->mixer.BlocksRendered(), preludeQuantum);
    while (engine->mixer.BlocksRendered() < preludeQuantum) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
    }

    PlayableWorldImage replacement(
        engine->registry.Lookup(kSound).contentRevision,
        harken::ContainerModeV1::Random);
    StopAfterVariableControlSliceClaimContext context{};
    context.engine = engine;
    context.instance = started.instance;
    context.intent = GetParam();
    harken::detail::VoiceTimelineSinkTestAccess::SetQueueSliceClaimHook(
        engine->timelineSink,
        &WaitForConcurrentStopAfterVariableControlSliceClaim,
        &context);
    std::thread pumpThread([&context] {
        context.engine->nullBackend.Pump(1);
        context.pumpComplete.store(true, std::memory_order_release);
    });
    for (std::uint32_t attempt = 0;
         attempt < 1000000 &&
         !context.invoked.load(std::memory_order_acquire) &&
         !context.pumpComplete.load(std::memory_order_acquire);
         ++attempt) {
        std::this_thread::yield();
    }
    if (!context.invoked.load(std::memory_order_acquire)) {
        context.releaseClaim.store(true, std::memory_order_release);
        pumpThread.join();
        harken::detail::VoiceTimelineSinkTestAccess::SetQueueSliceClaimHook(
            engine->timelineSink, nullptr, nullptr);
        FAIL() << "queue audio slice claim hook was not reached";
        return;
    }

    bool operationAccepted = false;
    bool initialBackpressure = false;
    switch (GetParam()) {
    case StopAfterVariableControlSliceClaimContext::Intent::Stop:
        operationAccepted =
            harken::StopPlayable(*engine, started.instance, 0) ==
            harken::PlayableControlStatus::Ok;
        break;
    case StopAfterVariableControlSliceClaimContext::Intent::WorldReplacement:
        initialBackpressure =
            harken::InstallContainerWorldV1(
                *engine, replacement.world).status ==
            harken::WorldInstallStatus::Backpressure;
        break;
    case StopAfterVariableControlSliceClaimContext::Intent::TransportReset:
        initialBackpressure =
            harken::BeginRuntimeTransportReset(*engine, 0) ==
            harken::RuntimeTransportResetStatus::Backpressure;
        break;
    }
    harken::DecisionCommittedSnapshot whileClaimed{};
    const bool decisionPreserved =
        engine->decisions.CaptureCommitted(decision, &whileClaimed);
    harken::QueueInstanceSnapshot queueWhileClaimed{};
    const bool queuePreserved = engine->queueInstances.Capture(
        row->queueInstance, &queueWhileClaimed);
    harken::TimelineArmObservation sourceWhileClaimed{};
    const bool sourcePreserved = engine->timelineArms.Observe(
        sourceArm, &sourceWhileClaimed);
    const harken::AudioSliceLeaseSnapshot leaseWhileClaimed =
        group.lease->Capture();
    const harken::AudioSliceLeaseSnapshot completionWhileClaimed =
        completionGroup.lease->Capture();
    const std::uint32_t expectedReason =
        GetParam() == StopAfterVariableControlSliceClaimContext::Intent::
                          TransportReset
            ? harken::AudioSliceReasonTransportReset
            : GetParam() ==
                      StopAfterVariableControlSliceClaimContext::Intent::
                          WorldReplacement
                  ? harken::AudioSliceReasonWorldReplacement
                  : harken::AudioSliceReasonCancel;

    context.releaseClaim.store(true, std::memory_order_release);
    pumpThread.join();
    harken::detail::VoiceTimelineSinkTestAccess::SetQueueSliceClaimHook(
        engine->timelineSink, nullptr, nullptr);

    if (GetParam() ==
        StopAfterVariableControlSliceClaimContext::Intent::Stop) {
        EXPECT_TRUE(operationAccepted);
    } else {
        EXPECT_TRUE(initialBackpressure);
    }
    EXPECT_EQ(harken::AudioGroupState::Pending, whileClaimed.audioState);
    EXPECT_EQ(conditional.version, queueWhileClaimed.pendingVersion);
    EXPECT_EQ(harken::ConditionalQueueActivation::Waiting, queueWhileClaimed.pendingActivation);
    EXPECT_EQ(harken::ArmState::Published, sourceWhileClaimed.state);
    ASSERT_TRUE(decisionPreserved);
    ASSERT_TRUE(queuePreserved);
    ASSERT_TRUE(sourcePreserved);
    EXPECT_EQ(harken::AudioSliceState::SliceClaimed,
              leaseWhileClaimed.state);
    EXPECT_TRUE(leaseWhileClaimed.invalidateAfterSlice);
    EXPECT_EQ(expectedReason,
              leaseWhileClaimed.pendingReasonBits & expectedReason);
    EXPECT_EQ(harken::AudioSliceState::Ready,
              completionWhileClaimed.state);
    EXPECT_FALSE(completionWhileClaimed.invalidateAfterSlice);
    EXPECT_EQ(0u, completionWhileClaimed.pendingReasonBits);

    bool operationComplete = operationAccepted;
    bool targetStarted = false;
    std::uint64_t rootRetiredBlock = UINT64_MAX;
    const auto resourcesReleased = [&] {
        return engine->voices.ActiveCount() == voiceBaseline &&
            engine->timelineArms.LiveCount() == armBaseline &&
            engine->queueInstances.LiveCount() == queueBaseline &&
            engine->decisions.LiveCount() == decisionBaseline &&
            engine->armGroups.LiveCount() == groupBaseline &&
            engine->timelineOccurrences.OccupiedCount() == occurrenceBaseline &&
            engine->transitionInstances.LiveCount() == transitionBaseline &&
            engine->playableInstances.LiveCount() == instanceBaseline;
    };
    for (std::uint32_t block = 0; block < 256 &&
         (engine->playableInstances.Classify(started.instance).live ||
          !operationComplete || !resourcesReleased());
         ++block) {
        harken::TimelineArmObservation target{};
        targetStarted = targetStarted ||
            (engine->timelineArms.Observe(targetArm, &target) &&
             target.state == harken::ArmState::Started);
        switch (GetParam()) {
        case StopAfterVariableControlSliceClaimContext::Intent::Stop:
            break;
        case StopAfterVariableControlSliceClaimContext::Intent::
            WorldReplacement:
            operationComplete = harken::InstallContainerWorldV1(
                *engine, replacement.world).status ==
                harken::WorldInstallStatus::Ok;
            break;
        case StopAfterVariableControlSliceClaimContext::Intent::
            TransportReset:
            operationComplete = harken::BeginRuntimeTransportReset(
                *engine, 0) ==
                harken::RuntimeTransportResetStatus::Complete;
            break;
        }
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        if (rootRetiredBlock == UINT64_MAX && !engine->playableInstances.Classify(started.instance).live) {
            rootRetiredBlock = engine->mixer.BlocksRendered();
            RecordProperty("voices_at_root_retirement", engine->voices.ActiveCount());
        }
    }
    RecordProperty("root_retired_block", std::to_string(rootRetiredBlock));
    RecordProperty("resource_observed_block", std::to_string(engine->mixer.BlocksRendered()));
    for (const auto arm : {sourceArm, targetArm}) {
        const VnVoiceHandle render = (std::uint64_t(arm.renderGeneration) << 32) | arm.renderSlot;
        EXPECT_EQ(nullptr, engine->voices.Resolve(render));
        harken::TimelineArmObservation observed{};
        EXPECT_FALSE(engine->timelineArms.Observe(arm, &observed));
    }
    EXPECT_FALSE(targetStarted);
    EXPECT_TRUE(operationComplete);
    EXPECT_FALSE(engine->playableInstances.Classify(started.instance).live);
    EXPECT_EQ(voiceBaseline, engine->voices.ActiveCount());
    EXPECT_EQ(armBaseline, engine->timelineArms.LiveCount());
    EXPECT_EQ(queueBaseline, engine->queueInstances.LiveCount());
    EXPECT_EQ(decisionBaseline, engine->decisions.LiveCount());
    EXPECT_EQ(groupBaseline, engine->armGroups.LiveCount());
    EXPECT_EQ(occurrenceBaseline,
              engine->timelineOccurrences.OccupiedCount());
    EXPECT_EQ(transitionBaseline,
              engine->transitionInstances.LiveCount());
    EXPECT_EQ(instanceBaseline, engine->playableInstances.LiveCount());
    if (GetParam() == StopAfterVariableControlSliceClaimContext::Intent::
                          WorldReplacement) {
        EXPECT_NE(installedWorld,
                  engine->variables.CurrentWorldGeneration());
    }
    if (GetParam() == StopAfterVariableControlSliceClaimContext::Intent::
                          TransportReset) {
        EXPECT_GT(engine->transportEpochOwner.Current(), transportBefore);
    }
    EXPECT_FALSE(engine->runtimeRecreateRequired);
}

INSTANTIATE_TEST_SUITE_P(
    StopWorldAndReset,
    ClaimedQueueSliceCancellationTest,
    testing::Values(
        StopAfterVariableControlSliceClaimContext::Intent::Stop,
        StopAfterVariableControlSliceClaimContext::Intent::WorldReplacement,
        StopAfterVariableControlSliceClaimContext::Intent::TransportReset));

TEST(PlayableStart,
     SequenceQueueSameResolvedProgramKeyAdvancesWithoutRestart) {
    for (const bool parented : {false, true}) {
    SCOPED_TRACE(parented);
    VnConfig config = harkentest::MakeNullConfig(8, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);

    std::vector<float> first(512, 0.25f);
    std::vector<float> second(512, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSecondSound, &secondPcm));
    SequenceQueueWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision);
    image.ResolveSecondChildToFirst();
    image.EnableImmediateTransition(128, 128);
    const std::uint32_t queueBaseline =
        engine->queueInstances.LiveCount();
    const std::uint32_t decisionBaseline = engine->decisions.LiveCount();
    const std::uint32_t groupBaseline = engine->armGroups.LiveCount();
    const std::uint32_t occurrenceBaseline =
        engine->timelineOccurrences.OccupiedCount();

    DirectTrackWorldImage outer(engine->registry.Lookup(kSound).contentRevision);
    outer.properties[1].authoredStableOrder = 3;
    outer.properties[1].programSemanticFingerprint = harken::ComputePlayablePropertyFingerprintV1(outer.properties[1]);
    outer.track.rootDefinition.expectedProgramSemanticFingerprint = outer.properties[1].programSemanticFingerprint;
    outer.placement.content = image.Root();
    outer.track.scheduleSemanticFingerprint = harken::ComputeTrackScheduleFingerprintV1(outer.track);
    outer.occurrence.childPlayable = outer.placement.content;
    outer.occurrence.parentProgramSemanticFingerprint = outer.properties[1].programSemanticFingerprint;
    outer.occurrence.occurrenceSemanticFingerprint = harken::ComputePlayableOccurrenceFingerprintV1(outer.occurrence);
    auto world = image.world;
    const std::array properties{image.properties[0], image.properties[1], image.properties[2], outer.properties[1]};
    const std::array occurrences{image.occurrences[0], image.occurrences[1], outer.occurrence};
    if (parented) {
        world.properties = properties.data();
        world.propertyCount = properties.size();
        world.occurrences = occurrences.data();
        world.occurrenceCount = occurrences.size();
        world.trackSchedules = &outer.track;
        world.trackScheduleCount = 1;
    }
    harken::PlayableStartRequest request{};
    request.root = parented ? outer.Root() : image.Root();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.queueMode && candidate.queueInstance.Valid();
    });
    ASSERT_NE(engine->playableServices.end(), row);
    const auto queueOwner = row->ownerInstance;
    ASSERT_TRUE(row->queueContinuationPrepared);
    EXPECT_EQ(1u, engine->voices.ActiveCount());
    EXPECT_EQ(0u, row->QueuePayload().queueSuccessorRenderHandle);
    EXPECT_EQ(0u, row->QueueRuntimeViews().queueSuccessorRuntimeProgram.payloadCount);
    harken::ArmGroupSnapshot preparedGroup{};
    ASSERT_TRUE(engine->armGroups.Capture(
        row->QueueFiling().queueArmGroup, &preparedGroup));
    EXPECT_EQ(harken::ArmGroupState::Ready, preparedGroup.state);
    EXPECT_EQ(0u, preparedGroup.memberCount);
    const VnVoiceHandle incumbent = row->renderHandle;
    ASSERT_NE(0u, incumbent);

    bool advanced = false;
    std::uint32_t maximumVoices = engine->voices.ActiveCount();
    for (std::uint32_t block = 0; block < 48; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        const auto active = std::find_if(
            engine->playableServices.begin(), engine->playableServices.end(),
            [&](const harken::EnginePlayableServiceRow& candidate) {
                return candidate.ownerInstance == queueOwner;
            });
        maximumVoices = std::max(
            maximumVoices, engine->voices.ActiveCount());
        if (active != engine->playableServices.end()) {
            EXPECT_EQ(0u, active->QueuePayload().queueSuccessorRenderHandle);
            EXPECT_TRUE(active->renderHandle == incumbent ||
                        active->renderHandle == 0u);
            harken::EffectiveQueueState effective{};
            if (active->queueInstance.Valid() &&
                engine->queueInstances.ResolveEffective(
                    active->queueInstance, &effective) &&
                effective.cursor == 1u &&
                effective.currentChildOrdinal ==
                    image.children[1].stableChildOrdinal) {
                advanced = true;
            }
        }
        engine->nullBackend.Pump(1);
    }
    EXPECT_TRUE(advanced);
    EXPECT_EQ(1u, maximumVoices);
    EXPECT_EQ(nullptr, engine->voices.Resolve(incumbent));
    EXPECT_EQ(queueBaseline, engine->queueInstances.LiveCount());
    EXPECT_EQ(decisionBaseline, engine->decisions.LiveCount());
    EXPECT_EQ(groupBaseline, engine->armGroups.LiveCount());
    EXPECT_EQ(occurrenceBaseline,
              engine->timelineOccurrences.OccupiedCount());
    EXPECT_FALSE(engine->runtimeRecreateRequired);
    }
}

TEST(PlayableStart, StopReclaimsPreparedSameKeyQueueContinuation) {
    VnConfig config = harkentest::MakeNullConfig(2, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);

    std::vector<float> first(4096, 0.25f);
    std::vector<float> second(4096, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSecondSound, &secondPcm));
    SequenceQueueWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision);
    image.ResolveSecondChildToFirst();
    image.EnableImmediateTransition(128, 128);
    const std::uint32_t voiceBaseline = engine->voices.ActiveCount();
    const std::uint32_t armBaseline = engine->timelineArms.LiveCount();
    const std::uint32_t queueBaseline =
        engine->queueInstances.LiveCount();
    const std::uint32_t decisionBaseline = engine->decisions.LiveCount();
    const std::uint32_t groupBaseline = engine->armGroups.LiveCount();
    const std::uint32_t occurrenceBaseline =
        engine->timelineOccurrences.OccupiedCount();
    const std::uint32_t instanceBaseline =
        engine->playableInstances.LiveCount();

    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    const auto active = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& row) {
            return row.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), active);
    ASSERT_TRUE(active->QueueFiling().queueSameProgramKey);
    harken::ArmGroupSnapshot group{};
    ASSERT_TRUE(engine->armGroups.Capture(active->QueueFiling().queueArmGroup, &group));
    ASSERT_EQ(0u, group.memberCount);

    ASSERT_EQ(harken::PlayableControlStatus::Ok,
              harken::StopPlayable(*engine, started.instance, 0));
    for (std::uint32_t block = 0; block < 96 &&
         engine->playableInstances.Classify(started.instance).live;
         ++block) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
    }

    EXPECT_FALSE(engine->playableInstances.Classify(started.instance).live);
    EXPECT_EQ(voiceBaseline, engine->voices.ActiveCount());
    EXPECT_EQ(armBaseline, engine->timelineArms.LiveCount());
    EXPECT_EQ(queueBaseline, engine->queueInstances.LiveCount());
    EXPECT_EQ(decisionBaseline, engine->decisions.LiveCount());
    EXPECT_EQ(groupBaseline, engine->armGroups.LiveCount());
    EXPECT_EQ(occurrenceBaseline,
              engine->timelineOccurrences.OccupiedCount());
    EXPECT_EQ(instanceBaseline, engine->playableInstances.LiveCount());
    EXPECT_FALSE(engine->runtimeRecreateRequired);
}

TEST(PlayableStart, WorldReplacementReclaimsSameKeyQueueContinuation) {
    VnConfig config = harkentest::MakeNullConfig(2, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);

    std::vector<float> first(4096, 0.25f);
    std::vector<float> second(4096, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSecondSound, &secondPcm));
    SequenceQueueWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision);
    image.ResolveSecondChildToFirst();
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(
                  *engine, image.InstallView()).status);
    const std::uint32_t voiceBaseline = engine->voices.ActiveCount();
    const std::uint32_t armBaseline = engine->timelineArms.LiveCount();
    const std::uint32_t queueBaseline =
        engine->queueInstances.LiveCount();
    const std::uint32_t decisionBaseline = engine->decisions.LiveCount();
    const std::uint32_t groupBaseline = engine->armGroups.LiveCount();
    const std::uint32_t occurrenceBaseline =
        engine->timelineOccurrences.OccupiedCount();
    const std::uint32_t instanceBaseline =
        engine->playableInstances.LiveCount();

    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult started =
        harken::StartCurrentPlayable(request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    ASSERT_TRUE(PumpUntilAudible(*engine));
    ASSERT_EQ(VN_OK, Vn_Update());

    PlayableWorldImage replacement(
        engine->registry.Lookup(kSound).contentRevision,
        harken::ContainerModeV1::Random);
    EXPECT_EQ(harken::WorldInstallStatus::Backpressure,
              harken::InstallContainerWorldV1(
                  *engine, replacement.world).status);
    harken::PlayableControlState state{};
    bool stale = false;
    for (std::uint32_t block = 0; block < 96 && !stale; ++block) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        stale = harken::QueryCurrentPlayable(started.instance, &state) ==
            harken::PlayableControlStatus::StaleHandle;
    }

    EXPECT_TRUE(stale);
    EXPECT_EQ(voiceBaseline, engine->voices.ActiveCount());
    EXPECT_EQ(armBaseline, engine->timelineArms.LiveCount());
    EXPECT_EQ(queueBaseline, engine->queueInstances.LiveCount());
    EXPECT_EQ(decisionBaseline, engine->decisions.LiveCount());
    EXPECT_EQ(groupBaseline, engine->armGroups.LiveCount());
    EXPECT_EQ(occurrenceBaseline,
              engine->timelineOccurrences.OccupiedCount());
    EXPECT_EQ(instanceBaseline, engine->playableInstances.LiveCount());
    EXPECT_FALSE(engine->runtimeRecreateRequired);
}

TEST(PlayableStart,
     CurrentWorldReplacementFailsActiveQueueWithoutUsingStaleViews) {
    VnConfig config = harkentest::MakeNullConfig(4, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);

    std::vector<float> first(4096, 0.25f);
    std::vector<float> second(4096, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSecondSound, &secondPcm));
    SequenceQueueWorldImage queue(
        engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision);
    const auto queueInstall = queue.InstallView();
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, queueInstall).status);
    const harken::WorldGeneration firstGeneration =
        engine->variables.CurrentWorldGeneration();
    const harken::WorldIdentityV1 firstIdentity =
        *engine->variables.CurrentWorldIdentity();
    const std::uint32_t voiceBaseline = engine->voices.ActiveCount();
    const std::uint32_t armBaseline = engine->timelineArms.LiveCount();
    const std::uint32_t occurrenceBaseline =
        engine->timelineOccurrences.OccupiedCount();
    const std::uint32_t decisionBaseline = engine->decisions.LiveCount();
    const std::uint32_t groupBaseline = engine->armGroups.LiveCount();
    const std::uint32_t queueBaseline =
        engine->queueInstances.LiveCount();
    const std::uint32_t instanceBaseline =
        engine->playableInstances.LiveCount();

    harken::PlayableStartRequest request{};
    request.root = queue.Root();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    ASSERT_TRUE(PumpUntilAudible(*engine));
    ASSERT_EQ(VN_OK, Vn_Update());
    const auto active = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& row) {
            return row.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), active);
    const harken::QueueInstanceToken queueToken = active->queueInstance;
    ASSERT_TRUE(queueToken.Valid());
    harken::QueueInstanceSnapshot activeQueue{};
    ASSERT_TRUE(engine->queueInstances.Capture(queueToken, &activeQueue));
    ASSERT_EQ(harken::QueueFailurePhase::Healthy,
              activeQueue.failurePhase);

    std::uint64_t replacementFingerprint = 0;
    {
        PlayableWorldImage replacement(
            engine->registry.Lookup(kSound).contentRevision,
            harken::ContainerModeV1::Random);
        replacementFingerprint =
            replacement.world.identity.runtimeSemanticFingerprint;
        const harken::WorldInstallResult firstAttempt =
            harken::InstallContainerWorldV1(*engine, replacement.world);
        EXPECT_EQ(harken::WorldInstallStatus::Backpressure,
                  firstAttempt.status);
        EXPECT_EQ(firstGeneration, firstAttempt.priorGeneration);
        EXPECT_EQ(0u, firstAttempt.resultGeneration);
        EXPECT_EQ(firstGeneration,
                  engine->variables.CurrentWorldGeneration());
        ASSERT_NE(nullptr, engine->variables.CurrentWorldIdentity());
        EXPECT_EQ(firstIdentity.runtimeSemanticFingerprint,
                  engine->variables.CurrentWorldIdentity()
                      ->runtimeSemanticFingerprint);

        const harken::WorldInstallResult repeatedAttempt =
            harken::InstallContainerWorldV1(*engine, replacement.world);
        EXPECT_EQ(harken::WorldInstallStatus::Backpressure,
                  repeatedAttempt.status);
        EXPECT_EQ(firstGeneration,
                  engine->variables.CurrentWorldGeneration());

        replacement.properties = {};
        replacement.occurrence = {};
        replacement.child = {};
        replacement.container = {};
        replacement.world = {};
    }

    const harken::PlayableStartResult blocked =
        harken::StartCurrentPlayable(request);
    EXPECT_EQ(harken::PlayableStartStatus::Backpressure, blocked.status);
    EXPECT_EQ(0u, blocked.instance);
    EXPECT_EQ(0u, blocked.ticket);

    harken::PlayableControlState state{};
    ASSERT_EQ(harken::PlayableControlStatus::Ok,
              harken::QueryCurrentPlayable(started.instance, &state));
    EXPECT_EQ(harken::PlayableControlLifecycle::FailingSourceActive,
              state.lifecycle);
    EXPECT_EQ(harken::PlayableControlReason::ContentRevision,
              state.reason);

    harken::QueueInstanceSnapshot failedQueue{};
    ASSERT_TRUE(engine->queueInstances.Capture(queueToken, &failedQueue));
    EXPECT_EQ(harken::QueueFailureReason::WorldReplaced,
              failedQueue.failureReason);

    bool stale = false;
    for (std::uint32_t block = 0; block < 96 && !stale; ++block) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        EXPECT_EQ(firstGeneration,
                  engine->variables.CurrentWorldGeneration());
        ASSERT_NE(nullptr, engine->variables.CurrentWorldIdentity());
        EXPECT_EQ(firstIdentity.runtimeSemanticFingerprint,
                  engine->variables.CurrentWorldIdentity()
                      ->runtimeSemanticFingerprint);
        stale = harken::QueryCurrentPlayable(started.instance, &state) ==
            harken::PlayableControlStatus::StaleHandle;
    }
    EXPECT_TRUE(stale);
    EXPECT_EQ(voiceBaseline, engine->voices.ActiveCount());
    EXPECT_EQ(armBaseline, engine->timelineArms.LiveCount());
    EXPECT_EQ(occurrenceBaseline,
              engine->timelineOccurrences.OccupiedCount());
    EXPECT_EQ(decisionBaseline, engine->decisions.LiveCount());
    EXPECT_EQ(groupBaseline, engine->armGroups.LiveCount());
    EXPECT_EQ(queueBaseline, engine->queueInstances.LiveCount());
    EXPECT_EQ(instanceBaseline, engine->playableInstances.LiveCount());
    EXPECT_FALSE(engine->runtimeRecreateRequired);

    ASSERT_TRUE(WaitUntilReclaimed(*engine, started.instance));
    PlayableWorldImage retry(
        engine->registry.Lookup(kSound).contentRevision,
        harken::ContainerModeV1::Random);
    ASSERT_EQ(replacementFingerprint,
              retry.world.identity.runtimeSemanticFingerprint);
    const harken::WorldInstallResult installed =
        harken::InstallContainerWorldV1(*engine, retry.world);
    EXPECT_EQ(harken::WorldInstallStatus::Ok, installed.status);
    EXPECT_EQ(firstGeneration, installed.priorGeneration);
    EXPECT_EQ(firstGeneration + 1u, installed.resultGeneration);
    EXPECT_EQ(firstGeneration + 1u,
              engine->variables.CurrentWorldGeneration());
    ASSERT_NE(nullptr, engine->variables.CurrentWorldIdentity());
    EXPECT_EQ(replacementFingerprint,
              engine->variables.CurrentWorldIdentity()
                  ->runtimeSemanticFingerprint);
}

TEST(PlayableStart, TransportResetDrainsActiveCurrentSequenceQueue) {
    VnConfig config = harkentest::MakeNullConfig(4, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);

    std::vector<float> first(256, 0.25f);
    std::vector<float> second(256, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSecondSound, &secondPcm));
    SequenceQueueWorldImage queue(
        engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision);
    const auto queueInstall = queue.InstallView();
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(
                  *engine, queueInstall).status);
    const harken::WorldGeneration worldGeneration =
        engine->variables.CurrentWorldGeneration();
    const std::uint64_t epochBefore =
        engine->variables.CurrentTransportEpoch();
    const std::uint32_t voiceBaseline = engine->voices.ActiveCount();
    const std::uint32_t armBaseline = engine->timelineArms.LiveCount();
    const std::uint32_t occurrenceBaseline =
        engine->timelineOccurrences.OccupiedCount();
    const std::uint32_t decisionBaseline = engine->decisions.LiveCount();
    const std::uint32_t groupBaseline = engine->armGroups.LiveCount();
    const std::uint32_t queueBaseline =
        engine->queueInstances.LiveCount();
    const std::uint32_t instanceBaseline =
        engine->playableInstances.LiveCount();

    harken::PlayableStartRequest request{};
    request.root = queue.Root();
    const harken::PlayableWorldViewV1 currentWorld =
        engine->variables.CurrentPlayableWorld();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, currentWorld, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    harken::PlayableControlState state{};
    const auto startedRow = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), startedRow);
    const std::uint64_t activeLimit =
        startedRow->startFrame / engine->config.blockFrames + 8u;
    while (engine->mixer.BlocksRendered() <= activeLimit) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_EQ(harken::PlayableControlStatus::Ok,
                  harken::QueryPlayable(*engine, started.instance, &state));
        if (state.lifecycle == harken::PlayableControlLifecycle::Active) break;
    }
    ASSERT_EQ(harken::PlayableControlLifecycle::Active, state.lifecycle);
    ASSERT_EQ(harken::PlayableControlReason::None, state.reason);
    const auto active = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& row) {
            return row.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), active);
    ASSERT_TRUE(active->queueWorldUsesCurrentAuthority);
    const harken::QueueInstanceToken queueToken = active->queueInstance;
    ASSERT_TRUE(queueToken.Valid());

    const std::uint64_t resetFrame =
        engine->mixer.BlocksRendered() * engine->config.blockFrames;
    EXPECT_EQ(harken::RuntimeTransportResetStatus::Backpressure,
              harken::BeginRuntimeTransportReset(*engine, resetFrame));
    EXPECT_EQ(harken::RuntimeTransportResetStatus::InvalidRequest,
              harken::BeginRuntimeTransportReset(
                  *engine, resetFrame + engine->config.blockFrames));
    EXPECT_EQ(epochBefore, engine->variables.CurrentTransportEpoch());
    EXPECT_EQ(worldGeneration, engine->variables.CurrentWorldGeneration());
    EXPECT_FALSE(engine->runtimeRecreateRequired);
    ASSERT_EQ(harken::PlayableControlStatus::Ok,
              harken::QueryPlayable(*engine, started.instance, &state));
    EXPECT_EQ(harken::PlayableControlLifecycle::Cancelling,
              state.lifecycle);
    EXPECT_EQ(harken::PlayableControlReason::None, state.reason);
    harken::QueueInstanceSnapshot resetQueue{};
    ASSERT_TRUE(engine->queueInstances.Capture(queueToken, &resetQueue));
    EXPECT_EQ(harken::QueueFailurePhase::FailingSourceActive,
              resetQueue.failurePhase);
    EXPECT_EQ(harken::QueueFailureReason::TransportReset,
              resetQueue.failureReason);

    const std::uint64_t acceptedBefore =
        engine->variables.AcceptedCount();
    EXPECT_EQ(VN_BACKPRESSURE, Vn_SetValue(harkentest::ObjectId(41), 1.0f));
    EXPECT_EQ(acceptedBefore, engine->variables.AcceptedCount());
    const harken::PlayableStartResult blocked =
        harken::StartPlayable(*engine, request);
    EXPECT_EQ(harken::PlayableStartStatus::Backpressure, blocked.status);
    EXPECT_EQ(0u, blocked.instance);
    EXPECT_EQ(0u, blocked.ticket);
    ASSERT_NE(queue.world.generation,
              engine->variables.CurrentPlayableWorld().generation);
    const std::uint64_t commandHeadBeforePinnedStart =
        engine->commands.PublishedHead();
    const std::uint32_t voicesBeforePinnedStart =
        engine->voices.ActiveCount();
    const std::uint32_t armsBeforePinnedStart =
        engine->timelineArms.LiveCount();
    const std::uint32_t decisionsBeforePinnedStart =
        engine->decisions.LiveCount();
    const std::uint32_t groupsBeforePinnedStart =
        engine->armGroups.LiveCount();
    const std::uint32_t queuesBeforePinnedStart =
        engine->queueInstances.LiveCount();
    const std::uint32_t instancesBeforePinnedStart =
        engine->playableInstances.LiveCount();
    const harken::PlayableStartResult pinnedBlocked =
        harken::StartPlayable(*engine, queue.world, request);
    EXPECT_EQ(harken::PlayableStartStatus::Backpressure,
              pinnedBlocked.status);
    EXPECT_EQ(0u, pinnedBlocked.instance);
    EXPECT_EQ(0u, pinnedBlocked.ticket);
    EXPECT_EQ(commandHeadBeforePinnedStart,
              engine->commands.PublishedHead());
    EXPECT_EQ(voicesBeforePinnedStart, engine->voices.ActiveCount());
    EXPECT_EQ(armsBeforePinnedStart, engine->timelineArms.LiveCount());
    EXPECT_EQ(decisionsBeforePinnedStart, engine->decisions.LiveCount());
    EXPECT_EQ(groupsBeforePinnedStart, engine->armGroups.LiveCount());
    EXPECT_EQ(queuesBeforePinnedStart,
              engine->queueInstances.LiveCount());
    EXPECT_EQ(instancesBeforePinnedStart,
              engine->playableInstances.LiveCount());

    harken::RuntimeTransportResetStatus reset =
        harken::RuntimeTransportResetStatus::Backpressure;
    for (std::uint32_t block = 0;
         block < 128 &&
         reset == harken::RuntimeTransportResetStatus::Backpressure;
         ++block) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        reset = harken::BeginRuntimeTransportReset(*engine, resetFrame);
    }
    EXPECT_EQ(harken::RuntimeTransportResetStatus::Complete, reset);
    EXPECT_EQ(epochBefore + 1u,
              engine->variables.CurrentTransportEpoch());
    EXPECT_EQ(harken::RuntimeTransportResetStatus::Complete,
              harken::BeginRuntimeTransportReset(*engine, resetFrame));
    EXPECT_EQ(epochBefore + 2u,
              engine->variables.CurrentTransportEpoch());
    EXPECT_EQ(worldGeneration, engine->variables.CurrentWorldGeneration());
    EXPECT_EQ(harken::PlayableControlStatus::StaleHandle,
              harken::QueryPlayable(*engine, started.instance, &state));
    harken::QueueInstanceSnapshot queueSnapshot{};
    EXPECT_FALSE(engine->queueInstances.Capture(queueToken, &queueSnapshot));
    EXPECT_EQ(voiceBaseline, engine->voices.ActiveCount());
    EXPECT_EQ(armBaseline, engine->timelineArms.LiveCount());
    EXPECT_EQ(occurrenceBaseline,
              engine->timelineOccurrences.OccupiedCount());
    EXPECT_EQ(decisionBaseline, engine->decisions.LiveCount());
    EXPECT_EQ(groupBaseline, engine->armGroups.LiveCount());
    EXPECT_EQ(queueBaseline, engine->queueInstances.LiveCount());
    EXPECT_EQ(instanceBaseline, engine->playableInstances.LiveCount());
    EXPECT_FALSE(engine->runtimeRecreateRequired);
}

TEST(PlayableStart,
     CompletedTransportResetDoesNotCacheSameFrameAcrossNewWork) {
    VnConfig config = harkentest::MakeNullConfig(2, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);

    std::vector<float> samples(65536, 0.25f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &pcm));
    PlayableWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        harken::ContainerModeV1::Sequence);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);
    const std::uint64_t epochBefore =
        engine->variables.CurrentTransportEpoch();
    ASSERT_EQ(harken::RuntimeTransportResetStatus::Complete,
              harken::BeginRuntimeTransportReset(*engine, 0));
    ASSERT_EQ(epochBefore + 1u,
              engine->variables.CurrentTransportEpoch());

    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    ASSERT_TRUE(PumpUntilAudible(*engine));

    harken::RuntimeTransportResetStatus reset =
        harken::BeginRuntimeTransportReset(*engine, 0);
    EXPECT_EQ(harken::RuntimeTransportResetStatus::Backpressure, reset);
    for (std::uint32_t block = 0;
         block < 128 &&
         reset == harken::RuntimeTransportResetStatus::Backpressure;
         ++block) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        reset = harken::BeginRuntimeTransportReset(*engine, 0);
    }
    EXPECT_EQ(harken::RuntimeTransportResetStatus::Complete, reset);
    EXPECT_EQ(epochBefore + 2u,
              engine->variables.CurrentTransportEpoch());
    harken::PlayableControlState state{};
    EXPECT_EQ(harken::PlayableControlStatus::StaleHandle,
              harken::QueryPlayable(*engine, started.instance, &state));
    EXPECT_FALSE(engine->runtimeRecreateRequired);
}

TEST(PlayableStart,
     TransportResetInvalidatesSequenceQueueResumeCheckpoint) {
    VnConfig config = harkentest::MakeNullConfig(3, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);

    std::vector<float> first(4096, 0.25f);
    std::vector<float> second(4096, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSecondSound, &secondPcm));
    SequenceQueueWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision,
        harken::QueueCycleV1::Once, true);
    VnEmitterHandle emitter = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&emitter));

    harken::QueueCheckpointKey key{};
    key.world = image.world.generation;
    key.containerStableId = image.container.containerStableId;
    key.programSemanticFingerprint =
        image.container.programSemanticFingerprint;
    key.resetEpoch = engine->variables.CurrentTransportEpoch();
    key.emitterSlot = static_cast<std::uint32_t>(emitter);
    key.emitterGeneration = static_cast<std::uint32_t>(emitter >> 32);
    harken::QueueCheckpointImage checkpoint{};
    checkpoint.effective.version = 9;
    checkpoint.effective.cursor = 1;
    checkpoint.effective.currentChildOrdinal =
        image.children[1].stableChildOrdinal;
    checkpoint.effective.selectionOrdinal = 9;
    checkpoint.replayCurrent = true;
    ASSERT_TRUE(engine->queueCheckpoints.Store(key, checkpoint));
    ASSERT_EQ(1u, engine->queueCheckpoints.LiveCount());

    const std::uint64_t resetFrame =
        engine->mixer.BlocksRendered() * engine->config.blockFrames;
    ASSERT_EQ(harken::RuntimeTransportResetStatus::Complete,
              harken::BeginRuntimeTransportReset(*engine, resetFrame));
    EXPECT_EQ(0u, engine->queueCheckpoints.LiveCount());

    harken::PlayableStartRequest request{};
    request.root = image.Root();
    request.emitter = emitter;
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    harken::QueueInstanceSnapshot fresh{};
    ASSERT_TRUE(engine->queueInstances.Capture(row->queueInstance, &fresh));
    EXPECT_EQ(engine->variables.CurrentTransportEpoch(), fresh.resetEpoch);
    EXPECT_EQ(1u, fresh.logicMirror.version);
    EXPECT_EQ(0u, fresh.logicMirror.cursor);
    EXPECT_EQ(image.children[0].stableChildOrdinal,
              fresh.logicMirror.currentChildOrdinal);
}

