TEST(PlayableStart,
     TransportResetRepeatedPollDoesNotRecancelFailingQueue) {
    VnConfig config = harkentest::MakeNullConfig(4, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);

    std::vector<float> first(65536, 0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &firstPcm));
    SequenceQueueWorldImage image(
        engine->registry.Lookup(kSound).contentRevision, 1);
    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    ASSERT_EQ(harken::PlayableControlLifecycle::FailingSourceActive,
              row->controlLifecycle);
    const std::uint64_t scheduleEpochBefore =
        engine->playableInstances.Classify(started.instance).scheduleEpoch;
    const std::uint64_t resetFrame =
        engine->mixer.BlocksRendered() * engine->config.blockFrames;
    ASSERT_EQ(harken::RuntimeTransportResetStatus::Backpressure,
              harken::BeginRuntimeTransportReset(*engine, resetFrame));
    const std::uint64_t cancelledEpoch =
        engine->playableInstances.Classify(started.instance).scheduleEpoch;
    ASSERT_NE(scheduleEpochBefore, cancelledEpoch);
    ASSERT_EQ(harken::EnginePlayableStartPhase::Cancelling, row->phase);
    const std::uint64_t commandHead = engine->commands.PublishedHead();

    EXPECT_EQ(harken::RuntimeTransportResetStatus::Backpressure,
              harken::BeginRuntimeTransportReset(*engine, resetFrame));
    EXPECT_EQ(cancelledEpoch,
              engine->playableInstances.Classify(
                  started.instance).scheduleEpoch);
    EXPECT_EQ(commandHead, engine->commands.PublishedHead());
    EXPECT_FALSE(engine->runtimeRecreateRequired);

    harken::RuntimeTransportResetStatus reset =
        harken::RuntimeTransportResetStatus::Backpressure;
    for (std::uint32_t block = 0;
         block < 128 &&
         reset == harken::RuntimeTransportResetStatus::Backpressure;
         ++block) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        reset = harken::BeginRuntimeTransportReset(*engine, resetFrame);
    }
    EXPECT_EQ(harken::RuntimeTransportResetStatus::Complete, reset);
    EXPECT_FALSE(engine->runtimeRecreateRequired);
}

TEST(PlayableStart,
     TransportResetClearsLegacyTimelineDeferredAndProgramAuthority) {
    VnConfig config = harkentest::MakeNullConfig(2, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);

    const harken::PlayableInstanceHandle owner =
        engine->playableInstances.Acquire(harken::PlayableKind::Segment, 0);
    ASSERT_NE(0u, owner);
    const std::uint64_t ownerScheduleEpoch =
        engine->playableInstances.Classify(owner).scheduleEpoch;
    const harken::ProgramGeneration generation =
        engine->timelinePrograms.Publish(1, engine->mixer.BlocksRendered());
    ASSERT_NE(0u, generation);
    auto set = std::make_unique<harken::EngineTimelineProgramSet>();
    set->generation = generation;
    set->programs.programs.emplace_back();
    set->programs.programs.back().payloads.resize(1);
    set->programs.programs.back().Seal(generation);
    const harken::TimelineProgramView* runtimeProgram =
        &set->programs.programs.back().view;
    engine->timelineProgramSets[generation & 1u] = std::move(set);

    harken::EventTemplate nearEvent{};
    nearEvent.logicCommitSequence = 1;
    nearEvent.payload = 101;
    harken::ProgramView nearProgram{};
    nearProgram.ownerInstance = owner;
    nearProgram.ownerInstanceScheduleEpoch = ownerScheduleEpoch;
    nearProgram.transactionId = 101;
    nearProgram.entryAnchorFrame =
        engine->timelinePool.PublishCutoffFrame() + 64u;
    nearProgram.events = &nearEvent;
    nearProgram.eventCount = 1;
    nearProgram.runtimeProgram = {generation, runtimeProgram};
    harken::PostInput nearInput{};
    nearInput.transportEpoch = engine->transportEpochOwner.Current();
    nearInput.logicCommitSequence = 1;
    ASSERT_EQ(harken::PostStatus::Reserved,
              engine->timelinePlanner.PostPlay(
                  nearProgram, nearInput).status);
    const std::uint64_t oldQuantum = nearProgram.entryAnchorFrame / 64u;

    harken::EventTemplate farEvent{};
    farEvent.logicCommitSequence = 2;
    farEvent.payload = 202;
    harken::ProgramView farProgram = nearProgram;
    farProgram.transactionId = 202;
    farProgram.entryAnchorFrame =
        engine->timelinePool.WindowEndFrame() + 64u;
    farProgram.events = &farEvent;
    harken::PostInput farInput = nearInput;
    farInput.logicCommitSequence = 2;
    ASSERT_EQ(harken::PostStatus::Deferred,
              engine->timelinePlanner.PostPlay(
                  farProgram, farInput).status);
    ASSERT_EQ(1u, engine->timelineDeferred.Count());
    ASSERT_EQ(1u, engine->timelinePool.LiveTransactionCount());

    const harken::TransportEpoch epochBefore =
        engine->transportEpochOwner.Current();
    harken::RuntimeTransportResetStatus reset =
        harken::BeginRuntimeTransportReset(*engine, 0);
    ASSERT_EQ(harken::RuntimeTransportResetStatus::Backpressure, reset);
    for (std::uint32_t block = 0;
         block < 128 &&
         reset == harken::RuntimeTransportResetStatus::Backpressure;
         ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        reset = harken::BeginRuntimeTransportReset(*engine, 0);
    }
    ASSERT_EQ(harken::RuntimeTransportResetStatus::Complete, reset);
    EXPECT_EQ(epochBefore + 1u,
              engine->transportEpochOwner.Current());
    EXPECT_EQ(0u, engine->timelineDeferred.Count());
    EXPECT_EQ(0u, engine->timelinePool.LiveTransactionCount());
    EXPECT_FALSE(engine->timelinePlanner.HasLiveProgramGeneration(
        generation));
    EXPECT_FALSE(engine->timelinePrograms.IsReadable(generation));
    EXPECT_EQ(nullptr, engine->timelineProgramSets[0]);
    EXPECT_EQ(nullptr, engine->timelineProgramSets[1]);
    std::array<harken::ConsumedEvent, 1> consumed{};
    EXPECT_EQ(0u, engine->timelinePool.ConsumePageRt(
                      oldQuantum, consumed.data(), consumed.size()));
    EXPECT_FALSE(engine->runtimeRecreateRequired);
}

TEST(PlayableStart,
     CurrentWorldReplacementDrainsVariableControlCurrentAuthority) {
    VnConfig config = harkentest::MakeNullConfig(3, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);

    std::vector<float> samples(65536, 0.25f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &pcm));
    const harken::VariableDefinitionV1 variable = {
        harkentest::ObjectId(41), harken::VariableKindV1::Step, 0.0f, 8.0f, 3.0f};
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harkentest::InstallDefinitionsWorld(
                  engine, &variable, 1,
                  UINT64_C(0x565243574F524C44)).status);
    VnEmitterHandle emitter = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&emitter));
    ASSERT_EQ(VN_OK, Vn_SetEmitterValue(emitter, harkentest::ObjectId(41), 3.0f));
    harkentest::AdvanceVariableWrite(engine);
    const harken::WorldGeneration firstGeneration =
        engine->variables.CurrentWorldGeneration();
    VariableControlWorldImage control(
        engine->registry.Lookup(kSound).contentRevision,
        firstGeneration, true, true);
    harken::PlayableStartRequest request{};
    request.root = control.Root();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, control.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    ASSERT_TRUE(PumpUntilAudible(*engine));
    const auto active = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& row) {
            return row.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), active);
    active->variableControlWorldUsesCurrentAuthority = true;

    PlayableWorldImage replacement(
        engine->registry.Lookup(kSound).contentRevision,
        harken::ContainerModeV1::Random);
    const harken::WorldInstallResult blocked =
        harken::InstallContainerWorldV1(*engine, replacement.world);
    EXPECT_EQ(harken::WorldInstallStatus::Backpressure, blocked.status);
    EXPECT_EQ(firstGeneration,
              engine->variables.CurrentWorldGeneration());
    const std::uint64_t acceptedBefore =
        engine->variables.AcceptedCount();
    EXPECT_EQ(VN_BACKPRESSURE, Vn_SetValue(harkentest::ObjectId(41), 4.0f));
    EXPECT_EQ(VN_BACKPRESSURE,
              Vn_SetEmitterValue(emitter, harkentest::ObjectId(41), 4.0f));
    EXPECT_EQ(acceptedBefore, engine->variables.AcceptedCount());
    harken::PlayableControlState state{};
    EXPECT_EQ(harken::PlayableControlStatus::Ok,
              harken::QueryPlayable(*engine, started.instance, &state));
    EXPECT_EQ(harken::PlayableControlReason::ContentRevision,
              state.reason);
}

TEST(PlayableStart, RandomQueueOncePlaysOneDeterministicWeightedPermutation) {
    VnConfig config = harkentest::MakeNullConfig(4, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);

    std::array<std::vector<float>, 3> samples = {
        std::vector<float>(512, 0.125f),
        std::vector<float>(512, -0.25f),
        std::vector<float>(512, 0.375f)};
    const std::array<VnObjectId, 3> soundIds = {
        kSound, kSecondSound, kThirdSound};
    std::array<std::uint64_t, 3> revisions{};
    for (std::uint32_t i = 0; i < samples.size(); ++i) {
        const VnPCMDesc pcm = harkentest::MonoDesc(samples[i], 48000);
        ASSERT_EQ(VN_OK, Vn_RegisterPCM(harkentest::ObjectId(soundIds[i]), &pcm));
        revisions[i] = engine->registry.Lookup(soundIds[i]).contentRevision;
    }
    RandomQueueWorldImage image(revisions);
    VnEmitterHandle emitter = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&emitter));

    harken::PlayableStartRequest request{};
    request.root = image.Root();
    request.emitter = emitter;
    request.callerSeed = 77;
    harken::RandomQueueSeedContext seed{};
    seed.worldSemanticFingerprint =
        image.world.identity.runtimeSemanticFingerprint;
    seed.rootStableId = request.root.stableId;
    seed.callerSeed = request.callerSeed;
    seed.acceptedPostOrdinal = engine->logicCommits.Current() + 1u;
    seed.emitterSlot = static_cast<std::uint32_t>(emitter);
    seed.emitterGeneration = 1; // First emitter incarnation in this engine.
    seed.resetEpoch = 1;
    harken::EffectiveQueueState initial{};
    initial.version = 1;
    initial.selectionOrdinal = 1;
    std::array<harken::SelectionChildV1, 3> childScratch{};
    std::array<std::uint32_t, 3> remaining{};
    std::array<std::uint32_t, 3> expected{};
    ASSERT_EQ(harken::SelectionStatusV1::Ok,
              harken::BuildRandomQueuePermutationV1(
                  image.container, seed, initial, childScratch.data(),
                  remaining.data(), expected.data(), expected.size()));

    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);

    std::vector<std::uint32_t> heard;
    std::vector<VnObjectId> logicalLeaves;
    std::vector<std::uint64_t> logicalStates;
    float minimum = 0.0f;
    float maximum = 0.0f;
    for (std::uint32_t block = 0; block < 64 && heard.size() < 3; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        const auto activeRow = std::find_if(
            engine->playableServices.begin(), engine->playableServices.end(),
            [&](const harken::EnginePlayableServiceRow& candidate) {
                return candidate.rootInstance == started.instance;
            });
        if (activeRow != engine->playableServices.end() &&
            (logicalLeaves.empty() ||
             logicalLeaves.back() != activeRow->leaf.stableId)) {
            logicalLeaves.push_back(activeRow->leaf.stableId);
            harken::EffectiveQueueState state{};
            const bool stateOk = engine->queueInstances.ResolveEffective(
                activeRow->queueInstance, &state);
            logicalStates.push_back(
                (stateOk ? state.cursor : 99u) * 100u +
                (activeRow->QueueFiling().queueDecision.Valid() ? 1u : 0u));
        }
        engine->nullBackend.Pump(1);
        const float* output = engine->nullBackend.LastBlock();
        for (std::uint32_t frame = 0; frame < engine->config.blockFrames;
             ++frame) {
            const float value = output[2u * frame];
            minimum = std::min(minimum, value);
            maximum = std::max(maximum, value);
            std::uint32_t ordinal = 0;
            if (value == 0.125f) ordinal = 7;
            if (value == -0.25f) ordinal = 8;
            if (value == 0.375f) ordinal = 9;
            if (ordinal != 0 &&
                (heard.empty() || heard.back() != ordinal)) {
                heard.push_back(ordinal);
            }
        }
    }
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    harken::QueueInstanceSnapshot queue{};
    const bool captured =
        row != engine->playableServices.end() &&
        engine->queueInstances.Capture(row->queueInstance, &queue);
    ASSERT_EQ(expected.size(), heard.size())
        << "expected=" << expected[0] << "," << expected[1] << ","
        << expected[2] << " heard="
        << (heard.size() > 0 ? heard[0] : 0) << ","
        << (heard.size() > 1 ? heard[1] : 0) << ","
        << (heard.size() > 2 ? heard[2] : 0)
        << " row=" << (row != engine->playableServices.end())
        << " captured=" << captured
        << " cursor=" << (captured ? queue.logicMirror.cursor : 99)
        << " child="
        << (captured ? queue.logicMirror.currentChildOrdinal : 0)
        << " failure="
        << (captured ? static_cast<int>(queue.failurePhase) : -1)
        << " reason="
        << (row != engine->playableServices.end()
                ? static_cast<int>(row->controlReason)
                : -1)
        << " recreate=" << engine->runtimeRecreateRequired
        << " min=" << minimum << " max=" << maximum
        << " leaves="
        << harken::ObjectIdString(logicalLeaves.size() > 0 ? logicalLeaves[0] : VnObjectId{}) << ","
        << harken::ObjectIdString(logicalLeaves.size() > 1 ? logicalLeaves[1] : VnObjectId{}) << ","
        << harken::ObjectIdString(logicalLeaves.size() > 2 ? logicalLeaves[2] : VnObjectId{})
        << " states="
        << (logicalStates.size() > 0 ? logicalStates[0] : 0) << ","
        << (logicalStates.size() > 1 ? logicalStates[1] : 0) << ","
        << (logicalStates.size() > 2 ? logicalStates[2] : 0);
    EXPECT_TRUE(std::equal(expected.begin(), expected.end(), heard.begin()));
}

TEST(PlayableStart, RandomQueueLoopCarriesPreviousTailIntoNextCycle) {
    VnConfig config = harkentest::MakeNullConfig(4, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);

    std::array<std::vector<float>, 3> samples = {
        std::vector<float>(512, 0.125f),
        std::vector<float>(512, -0.25f),
        std::vector<float>(512, 0.375f)};
    const std::array<VnObjectId, 3> soundIds = {
        kSound, kSecondSound, kThirdSound};
    std::array<std::uint64_t, 3> revisions{};
    for (std::uint32_t i = 0; i < samples.size(); ++i) {
        const VnPCMDesc pcm = harkentest::MonoDesc(samples[i], 48000);
        ASSERT_EQ(VN_OK, Vn_RegisterPCM(harkentest::ObjectId(soundIds[i]), &pcm));
        revisions[i] = engine->registry.Lookup(soundIds[i]).contentRevision;
    }
    RandomQueueWorldImage image(revisions, harken::QueueCycleV1::Loop);
    VnEmitterHandle emitter = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&emitter));
    harken::PlayableStartRequest request{};
    request.root = image.Root();
    request.emitter = emitter;
    request.callerSeed = 77;
    harken::RandomQueueSeedContext seed{};
    seed.worldSemanticFingerprint =
        image.world.identity.runtimeSemanticFingerprint;
    seed.rootStableId = request.root.stableId;
    seed.callerSeed = request.callerSeed;
    seed.acceptedPostOrdinal = engine->logicCommits.Current() + 1u;
    seed.emitterSlot = static_cast<std::uint32_t>(emitter);
    seed.emitterGeneration = 1; // First emitter incarnation in this engine.
    seed.resetEpoch = 1;
    harken::EffectiveQueueState state{};
    state.version = 1;
    state.selectionOrdinal = 1;
    std::array<harken::SelectionChildV1, 3> childScratch{};
    std::array<std::uint32_t, 3> remaining{};
    std::array<std::uint32_t, 3> firstCycle{};
    ASSERT_EQ(harken::SelectionStatusV1::Ok,
              harken::BuildRandomQueuePermutationV1(
                  image.container, seed, state, childScratch.data(),
                  remaining.data(), firstCycle.data(), firstCycle.size()));
    const auto initialCycle = firstCycle;
    state.currentChildOrdinal = firstCycle[0];
    for (std::uint32_t step = 0; step < firstCycle.size(); ++step) {
        harken::EffectiveQueueState next{};
        ASSERT_EQ(harken::QueueSequenceStepStatus::Successor,
                  harken::ResolveRandomQueueStep(
                      image.container, seed, state, childScratch.data(),
                      remaining.data(), firstCycle.data(), firstCycle.size(),
                      &next));
        state = next;
    }
    std::array<std::uint32_t, 3> secondCycle{};
    ASSERT_EQ(harken::SelectionStatusV1::Ok,
              harken::BuildRandomQueuePermutationV1(
                  image.container, seed, state, childScratch.data(),
                  remaining.data(), secondCycle.data(), secondCycle.size()));
    ASSERT_NE(initialCycle.back(), secondCycle.front());

    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    std::vector<std::uint32_t> heard;
    for (std::uint32_t block = 0; block < 96 && heard.size() < 4; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        const float* output = engine->nullBackend.LastBlock();
        for (std::uint32_t frame = 0; frame < engine->config.blockFrames;
             ++frame) {
            const float value = output[2u * frame];
            std::uint32_t ordinal = 0;
            if (value == 0.125f) ordinal = 7;
            if (value == -0.25f) ordinal = 8;
            if (value == 0.375f) ordinal = 9;
            if (ordinal != 0 &&
                (heard.empty() || heard.back() != ordinal)) {
                heard.push_back(ordinal);
            }
        }
    }
    const std::array<std::uint32_t, 4> expected = {
        initialCycle[0], initialCycle[1], initialCycle[2], secondCycle[0]};
    ASSERT_EQ(expected.size(), heard.size());
    EXPECT_TRUE(std::equal(expected.begin(), expected.end(), heard.begin()));
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    harken::EffectiveQueueState effective{};
    ASSERT_TRUE(engine->queueInstances.ResolveEffective(
        row->queueInstance, &effective));
    EXPECT_GE(effective.cycleOrdinal, 1u);
    EXPECT_EQ(1u, effective.randomInitialRecentCount);
    EXPECT_EQ(initialCycle.back(), effective.randomInitialRecent[0]);
}

TEST(PlayableStart, RandomQueueResumeUsesOriginalSeedAndExactCurrent) {
    VnConfig config = harkentest::MakeNullConfig(4, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    std::array<std::vector<float>, 3> samples = {
        std::vector<float>(512, 0.125f),
        std::vector<float>(512, -0.25f),
        std::vector<float>(512, 0.375f)};
    const std::array<VnObjectId, 3> soundIds = {
        kSound, kSecondSound, kThirdSound};
    std::array<std::uint64_t, 3> revisions{};
    for (std::uint32_t i = 0; i < samples.size(); ++i) {
        const VnPCMDesc pcm = harkentest::MonoDesc(samples[i], 48000);
        ASSERT_EQ(VN_OK, Vn_RegisterPCM(harkentest::ObjectId(soundIds[i]), &pcm));
        revisions[i] = engine->registry.Lookup(soundIds[i]).contentRevision;
    }
    RandomQueueWorldImage image(
        revisions, harken::QueueCycleV1::Once, true);
    VnEmitterHandle emitter = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&emitter));
    harken::RandomQueueSeedContext seed{};
    seed.worldSemanticFingerprint =
        image.world.identity.runtimeSemanticFingerprint;
    seed.rootStableId = image.Root().stableId;
    seed.callerSeed = 77;
    seed.acceptedPostOrdinal = 101;
    seed.emitterSlot = static_cast<std::uint32_t>(emitter);
    seed.emitterGeneration = 1; // First emitter incarnation in this engine.
    seed.resetEpoch = 1;
    harken::EffectiveQueueState state{};
    state.version = 19;
    state.cursor = 1;
    state.selectionOrdinal = 1;
    std::array<harken::SelectionChildV1, 3> childScratch{};
    std::array<std::uint32_t, 3> remaining{};
    std::array<std::uint32_t, 3> permutation{};
    ASSERT_EQ(harken::SelectionStatusV1::Ok,
              harken::BuildRandomQueuePermutationV1(
                  image.container, seed, state, childScratch.data(),
                  remaining.data(), permutation.data(), permutation.size()));
    state.currentChildOrdinal = permutation[state.cursor];
    harken::QueueCheckpointKey key{};
    key.world = image.world.generation;
    key.containerStableId = image.container.containerStableId;
    key.programSemanticFingerprint =
        image.container.programSemanticFingerprint;
    key.resetEpoch = 1;
    key.emitterSlot = seed.emitterSlot;
    key.emitterGeneration = static_cast<std::uint32_t>(emitter >> 32);
    harken::QueueCheckpointImage checkpoint{};
    checkpoint.effective = state;
    checkpoint.randomSeed = seed;
    checkpoint.randomSeedValid = true;
    checkpoint.replayCurrent = true;
    ASSERT_TRUE(engine->queueCheckpoints.Store(key, checkpoint));

    harken::PlayableStartRequest request{};
    request.root = image.Root();
    request.emitter = emitter;
    request.callerSeed = 999;
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    EXPECT_TRUE(row->queueRandomSeedValid);
    EXPECT_EQ(seed.acceptedPostOrdinal,
              row->QueueRandomSeed().acceptedPostOrdinal);
    EXPECT_EQ(permutation[1], row->payload.target.occurrenceOrdinal);

    std::vector<std::uint32_t> heard;
    for (std::uint32_t block = 0; block < 64 && heard.size() < 2; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        const float* output = engine->nullBackend.LastBlock();
        for (std::uint32_t frame = 0; frame < engine->config.blockFrames;
             ++frame) {
            const float value = output[2u * frame];
            std::uint32_t ordinal = 0;
            if (value == 0.125f) ordinal = 7;
            if (value == -0.25f) ordinal = 8;
            if (value == 0.375f) ordinal = 9;
            if (ordinal != 0 &&
                (heard.empty() || heard.back() != ordinal)) {
                heard.push_back(ordinal);
            }
        }
    }
    const std::array<std::uint32_t, 2> expected = {
        permutation[1], permutation[2]};
    ASSERT_EQ(expected.size(), heard.size());
    EXPECT_TRUE(std::equal(expected.begin(), expected.end(), heard.begin()));
}

TEST(PlayableStart, RandomQueuePreparationFailureConsumesNoPermutationState) {
    VnConfig config = harkentest::MakeNullConfig(4, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    const std::array<VnObjectId, 3> soundIds = {
        kSound, kSecondSound, kThirdSound};
    std::array<std::vector<float>, 3> samples = {
        std::vector<float>(512, 0.125f),
        std::vector<float>(512, -0.25f),
        std::vector<float>(512, 0.375f)};
    std::array<std::uint64_t, 3> revisions{};
    for (std::uint32_t i = 0; i < samples.size(); ++i) {
        const VnPCMDesc pcm = harkentest::MonoDesc(samples[i], 48000);
        ASSERT_EQ(VN_OK, Vn_RegisterPCM(harkentest::ObjectId(soundIds[i]), &pcm));
        revisions[i] = engine->registry.Lookup(soundIds[i]).contentRevision;
    }
    RandomQueueWorldImage image(revisions);
    VnEmitterHandle emitter = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&emitter));
    harken::PlayableStartRequest request{};
    request.root = image.Root();
    request.emitter = emitter;
    request.callerSeed = 77;
    harken::RandomQueueSeedContext seed{};
    seed.worldSemanticFingerprint =
        image.world.identity.runtimeSemanticFingerprint;
    seed.rootStableId = request.root.stableId;
    seed.callerSeed = request.callerSeed;
    seed.acceptedPostOrdinal = engine->logicCommits.Current() + 1u;
    seed.emitterSlot = static_cast<std::uint32_t>(emitter);
    seed.emitterGeneration = 1; // First emitter incarnation in this engine.
    seed.resetEpoch = 1;
    harken::EffectiveQueueState initial{};
    initial.version = 1;
    initial.selectionOrdinal = 1;
    std::array<harken::SelectionChildV1, 3> childScratch{};
    std::array<std::uint32_t, 3> remaining{};
    std::array<std::uint32_t, 3> permutation{};
    ASSERT_EQ(harken::SelectionStatusV1::Ok,
              harken::BuildRandomQueuePermutationV1(
                  image.container, seed, initial, childScratch.data(),
                  remaining.data(), permutation.data(), permutation.size()));
    initial.currentChildOrdinal = permutation[0];
    const auto unavailable = std::find_if(
        image.children.begin(), image.children.end(),
        [&](const harken::ContainerChildProgramViewV2& child) {
            return child.stableChildOrdinal == permutation[1];
        });
    ASSERT_NE(image.children.end(), unavailable);
    ASSERT_EQ(VN_OK, Vn_UnregisterPCM(unavailable->playable.stableId));

    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    EXPECT_EQ(harken::PlayableControlLifecycle::FailingSourceActive,
              row->controlLifecycle);
    harken::QueueInstanceSnapshot queue{};
    ASSERT_TRUE(engine->queueInstances.Capture(row->queueInstance, &queue));
    EXPECT_EQ(harken::QueueFailurePhase::FailingSourceActive,
              queue.failurePhase);
    EXPECT_EQ(harken::QueueFailureReason::TargetPreparationFailed,
              queue.failureReason);
    EXPECT_EQ(initial.version, queue.logicMirror.version);
    EXPECT_EQ(initial.cursor, queue.logicMirror.cursor);
    EXPECT_EQ(initial.currentChildOrdinal,
              queue.logicMirror.currentChildOrdinal);
    EXPECT_EQ(initial.cycleOrdinal, queue.logicMirror.cycleOrdinal);
    EXPECT_EQ(initial.selectionOrdinal,
              queue.logicMirror.selectionOrdinal);
}

void ExpectDirectTrackAudioAdvance(bool duringPublication, bool stopBeforeBinding) {
    const auto config = harkentest::MakeNullConfig(2, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    auto& engine = *session.Engine();
    std::vector<float> samples(512, 0.25f);
    const auto pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &pcm));
    DirectTrackWorldImage image(engine.registry.Lookup(kSound).contentRevision);
    const auto owners = [&] {
        return std::tuple{engine.playableInstances.FreeCount(), engine.voices.AvailableSlotCount(),
            engine.ledger.AvailableEntryCount(), engine.timelineArms.LiveCount(),
            engine.timelinePool.LiveTransactionCount(), engine.timelineDeferred.Count(),
            engine.timelineDeferred.PreparedCount()};
    };
    const auto before = owners();
    const auto capture = harkentest::monitor::OpenIdentityEvents();
    ASSERT_NE(0u, capture);
    struct Advance {
        std::uint32_t calls = 0;
        std::uint32_t blocks = 0;
    } advance{0, engine.timelinePool.PublishLeadQuanta() + 2u};
    if (duringPublication) {
        engine.voiceCommandBatchPublishHookContextForTest = &advance;
        engine.voiceCommandBatchPublishHookForTest = [](harken::Engine& actual, void* context) {
            auto& observed = *static_cast<Advance*>(context);
            if (observed.calls++ == 0) actual.nullBackend.Pump(observed.blocks);
        };
    } else {
        engine.timelineVoicePreparedContextForTest = &advance;
        engine.timelineVoicePreparedHookForTest = [](harken::Engine& actual,
            const harken::EnginePreparedTimelineVoiceStart&, void* context) {
            auto& observed = *static_cast<Advance*>(context);
            if (observed.calls++ == 0) actual.nullBackend.Pump(observed.blocks);
        };
    }
    harken::PlayableStartRequest request{};
    request.root = image.Root();
    request.playbackRequest = engine.monitorRequests.Begin(
        harken::MonitorRequestOrigin::StudioPreview, VN_MONITOR_OPERATION_PLAY_PREVIEW);
    const auto started = harken::StartPlayable(engine, image.world, request);
    engine.timelineVoicePreparedHookForTest = nullptr;
    engine.timelineVoicePreparedContextForTest = nullptr;
    engine.voiceCommandBatchPublishHookForTest = nullptr;
    engine.voiceCommandBatchPublishHookContextForTest = nullptr;
    ASSERT_EQ(1u, advance.calls);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    ASSERT_NE(0u, started.instance);
    ASSERT_NE(0u, started.ticket);
    if (stopBeforeBinding) {
        ASSERT_EQ(harken::PlayableControlStatus::Ok, harken::StopPlayable(engine, started.instance, 0));
    }
    std::uint64_t audibleFrames = 0;
    std::uint64_t firstFrame = UINT64_MAX;
    std::vector<harkentest::monitor::IdentityRecord> records;
    for (unsigned block = 0; block < 64; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        const auto beforeBlock = engine.mixer.BlocksRendered();
        engine.nullBackend.Pump(1);
        ASSERT_EQ(beforeBlock + 1u, engine.mixer.BlocksRendered());
        const auto* output = engine.nullBackend.LastBlock();
        for (std::uint32_t frame = 0; frame < config.blockFrames; ++frame) {
            const bool audible = output[frame * 2u] != 0.0f || output[frame * 2u + 1u] != 0.0f;
            if (!audible) continue;
            if (firstFrame == UINT64_MAX) firstFrame = beforeBlock * config.blockFrames + frame;
            ++audibleFrames;
            EXPECT_NEAR(0.25f, output[frame * 2u], 0.00001f);
            EXPECT_NEAR(0.25f, output[frame * 2u + 1u], 0.00001f);
        }
        harkentest::monitor::CollectIdentityEvents(capture, records);
    }
    EXPECT_EQ(stopBeforeBinding ? 0u : samples.size(), audibleFrames);
    EXPECT_FALSE(engine.playableInstances.Classify(started.instance).live);
    EXPECT_EQ(before, owners());
    EXPECT_FALSE(engine.runtimeRecreateRequired);
    unsigned starts = 0, terminals = 0;
    for (const auto& record : records) {
        if (record.fact.root != started.instance || record.header.stableId != kSound ||
            record.fact.contentKind != VN_MONITOR_CONTENT_SOUND) continue;
        if (record.fact.factKind == VN_MONITOR_FACT_PLAYABLE_STARTED) {
            ++starts;
            EXPECT_EQ(firstFrame, record.header.executeFrame);
        }
        if (record.fact.factKind == VN_MONITOR_FACT_PLAYABLE_RETIRED) {
            ++terminals;
            EXPECT_EQ(stopBeforeBinding ? VN_MONITOR_TERMINAL_REQUESTED_STOP :
                VN_MONITOR_TERMINAL_NATURAL_COMPLETION, record.fact.terminalKind);
        }
    }
    EXPECT_EQ(stopBeforeBinding ? 0u : 1u, starts);
    EXPECT_EQ(1u, terminals);
    EXPECT_EQ(VN_OK, Vn_MonitorCloseSession(capture));
}

TEST(PlayableStart, DirectTrackKeepsWholeSourceWhenPreparationOutrunsInitialStart) {
    for (const bool stop : {false, true}) {
        SCOPED_TRACE(stop);
        ExpectDirectTrackAudioAdvance(false, stop);
    }
}

TEST(PlayableStart, DirectTrackKeepsWholeSourceWhenCommandPublicationOutrunsInitialStart) {
    for (const bool stop : {false, true}) {
        SCOPED_TRACE(stop);
        ExpectDirectTrackAudioAdvance(true, stop);
    }
}


