TEST(PlayableStart,
     VariableControlContinuousLogicalChildrenCompleteAtTheirOwnBoundaries) {
    VnConfig config = harkentest::MakeNullConfig(4, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    std::vector<float> first(512, 0.25f);
    std::vector<float> second(512, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSecondSound, &secondPcm));
    const harken::VariableDefinitionV1 variable = {
        harkentest::ObjectId(41), harken::VariableKindV1::Smooth,
        0.0f, 8.0f, 3.0f};
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harkentest::InstallDefinitionsWorld(
                  engine, &variable, 1,
                  UINT64_C(0x5234434F4E544C31)).status);
    VariableControlLogicalTracksWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision,
        engine->variables.CurrentWorldGeneration());

    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const auto started = harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    EXPECT_EQ(0u, row->variableControlContinuousMemberCount);
    ASSERT_EQ(2u, row->variableControlContinuousLogicalCount);
    EXPECT_EQ(7u, row->variableControlContinuousLogicalOrdinals[0]);
    EXPECT_EQ(9u, row->variableControlContinuousLogicalOrdinals[1]);
    const std::uint64_t firstBoundary = row->startFrame + 48000u;
    const std::uint64_t secondBoundary = row->startFrame + 96000u;
    EXPECT_EQ(firstBoundary,
              row->variableControlContinuousLogicalCompletionFrames[0]);
    EXPECT_EQ(secondBoundary,
              row->variableControlContinuousLogicalCompletionFrames[1]);
    EXPECT_EQ(secondBoundary, row->zeroWorkCompletionFrame);

    while (engine->mixer.BlocksRendered() * config.blockFrames <
           firstBoundary) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    ASSERT_TRUE(row->variableControlContinuousLogicalCompleted[0]);
    EXPECT_FALSE(row->variableControlContinuousLogicalCompleted[1]);
    EXPECT_TRUE(row->hasZeroWorkCompletion);
    EXPECT_EQ(secondBoundary, row->zeroWorkCompletionFrame);

    while (engine->mixer.BlocksRendered() * config.blockFrames <
           secondBoundary) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    EXPECT_TRUE(row->variableControlContinuousLogicalCompleted[0]);
    EXPECT_TRUE(row->variableControlContinuousLogicalCompleted[1]);
    EXPECT_FALSE(row->hasZeroWorkCompletion);
    ASSERT_NO_FATAL_FAILURE(ExpectVariableControlNaturallyCompleted(*engine, started.instance));
    ASSERT_EQ(VN_OK, Vn_SetValue(harkentest::ObjectId(41), 4.0f));
    for (std::uint32_t block = 0; block < 12; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    EXPECT_EQ(0u, engine->playableInstances.LiveCount());
    EXPECT_EQ(0u, engine->voices.ActiveCount());
    EXPECT_FALSE(engine->runtimeRecreateRequired);
}

TEST(PlayableStart,
     BlendVariableChangesPreserveEveryLogicalTrackDeadline) {
    VnConfig config = harkentest::MakeNullConfig(8, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    std::vector<float> first(512, 0.25f);
    std::vector<float> second(512, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSecondSound, &secondPcm));
    const harken::VariableDefinitionV1 variable = {
        harkentest::ObjectId(41), harken::VariableKindV1::Smooth,
        0.0f, 8.0f, 3.0f};
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harkentest::InstallDefinitionsWorld(
                  engine, &variable, 1,
                  UINT64_C(0x5234434F4E544C33)).status);
    VariableControlLogicalTracksWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision,
        engine->variables.CurrentWorldGeneration());
    image.cells[1].lower = 4.0f;
    image.cells[1].lowerInclusive = 0;

    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const auto started = harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    EXPECT_EQ(0u, row->variableControlContinuousMemberCount);
    ASSERT_EQ(2u, row->variableControlContinuousLogicalCount);
    ASSERT_EQ(2u, row->variableControlChildCount);
    const auto originalChildren = row->variableControlChildInstances.Snapshot();
    const auto originalBoundaries = row->variableControlContinuousLogicalCompletionFrames.Snapshot();
    const auto finalBoundary = row->zeroWorkCompletionFrame;
    ASSERT_EQ(row->startFrame + 96000u, finalBoundary);
    ASSERT_EQ(VN_OK, Vn_SetValue(harkentest::ObjectId(41), 7.0f));
    for (unsigned block = 0; block < 64; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        ASSERT_FALSE(engine->runtimeRecreateRequired);
    }
    EXPECT_EQ(originalChildren, row->variableControlChildInstances.Snapshot());
    EXPECT_EQ(originalBoundaries, row->variableControlContinuousLogicalCompletionFrames.Snapshot());
    EXPECT_FALSE(row->variableControlRetargetPrepared);
    for (unsigned block = 0; block < 2048; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        if (engine->mixer.BlocksRendered() * config.blockFrames < finalBoundary)
            EXPECT_TRUE(engine->playableInstances.Classify(started.instance).live);
        ASSERT_FALSE(engine->runtimeRecreateRequired);
    }
    EXPECT_EQ(0u, engine->voices.ActiveCount());
    EXPECT_EQ(0u, engine->playableInstances.LiveCount());
    EXPECT_EQ(0u, engine->variableControlInstances.LiveCount());
}


TEST(PlayableStart,
     BlendZeroWeightsKeepLogicalTracksUntilTheirAuthoredEnd) {
    VnConfig config = harkentest::MakeNullConfig(8, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    std::vector<float> first(512, 0.25f);
    std::vector<float> second(512, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSecondSound, &secondPcm));
    const harken::VariableDefinitionV1 variable = {
        harkentest::ObjectId(41), harken::VariableKindV1::Smooth,
        0.0f, 8.0f, 1.0f};
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harkentest::InstallDefinitionsWorld(
                  engine, &variable, 1,
                  UINT64_C(0x5234434F4E544C34)).status);
    VariableControlLogicalTracksWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision,
        engine->variables.CurrentWorldGeneration());
    image.cells[1].lower = 4.0f;
    image.cells[1].lowerInclusive = 0;
    image.cells[0].upper = 2.0f;

    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const auto started = harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    ASSERT_EQ(0u, row->variableControlContinuousMemberCount);
    ASSERT_EQ(2u, row->variableControlContinuousLogicalCount);
    ASSERT_EQ(2u, row->variableControlChildCount);
    const auto originalChildren = row->variableControlChildInstances.Snapshot();
    const auto originalBoundaries = row->variableControlContinuousLogicalCompletionFrames.Snapshot();
    const auto finalBoundary = row->zeroWorkCompletionFrame;
    ASSERT_EQ(row->startFrame + 96000u, finalBoundary);
    ASSERT_EQ(VN_OK, Vn_SetValue(harkentest::ObjectId(41), 3.0f));
    for (unsigned block = 0; block < 64; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        ASSERT_FALSE(engine->runtimeRecreateRequired);
    }
    EXPECT_EQ(originalChildren, row->variableControlChildInstances.Snapshot());
    EXPECT_EQ(originalBoundaries, row->variableControlContinuousLogicalCompletionFrames.Snapshot());
    EXPECT_FALSE(row->variableControlRetargetPrepared);
    for (unsigned block = 0; block < 2048; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        if (engine->mixer.BlocksRendered() * config.blockFrames < finalBoundary)
            EXPECT_TRUE(engine->playableInstances.Classify(started.instance).live);
        ASSERT_FALSE(engine->runtimeRecreateRequired);
    }
    EXPECT_EQ(0u, engine->voices.ActiveCount());
    EXPECT_EQ(0u, engine->playableInstances.LiveCount());
    EXPECT_EQ(0u, engine->variableControlInstances.LiveCount());
}


TEST(PlayableStart,
     VariableControlContinuousRetargetPreservesRetainedLogicalDeadline) {
    VnConfig config = harkentest::MakeNullConfig(4, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    std::vector<float> first(200000, 0.25f);
    std::vector<float> second(512, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSecondSound, &secondPcm));
    const harken::VariableDefinitionV1 variable = {
        harkentest::ObjectId(41), harken::VariableKindV1::Smooth,
        0.0f, 8.0f, 3.0f};
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harkentest::InstallDefinitionsWorld(
                  engine, &variable, 1,
                  UINT64_C(0x5234434F4E544C32)).status);
    VariableControlLogicalTracksWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision,
        engine->variables.CurrentWorldGeneration());
    image.MakeFirstTrackPhysical();
    image.placements[1].authoredStart = INT64_C(100000000);
    image.tracks[1].scheduleSemanticFingerprint =
        harken::ComputeTrackScheduleFingerprintV1(image.tracks[1]);
    image.children[1].timingHint = harken::MakeScheduleReferenceTimingHint(
        harken::PlayableKindV1::Track,
        image.tracks[1].rootDefinition.stableId,
        image.tracks[1].scheduleSemanticFingerprint);

    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const auto started = harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    ASSERT_TRUE(PumpUntilAudible(*engine));
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    ASSERT_EQ(1u, row->variableControlContinuousMemberCount);
    ASSERT_EQ(1u, row->variableControlContinuousLogicalCount);
    std::size_t physicalSlot = 0;
    ASSERT_TRUE(engine->ResolvePlayableMemberSlot(
        row->scheduleStorageBase +
            row->variableControlContinuousMemberOffset,
        &physicalSlot));
    ASSERT_FALSE(
        engine->ReadPlayableMember(physicalSlot).completion.resourcesRetired);
    ASSERT_NE(nullptr, engine->voices.Resolve(
                           engine->ReadPlayableMember(physicalSlot).render));
    ASSERT_EQ(7u, engine->ReadPlayableMemberReference(
                      row->scheduleStorageBase +
                      row->variableControlContinuousMemberOffset)
                      .authoredChildOrdinal);
    const std::uint64_t retainedBoundary =
        row->variableControlContinuousLogicalCompletionFrames[0];
    EXPECT_EQ(row->startFrame + 4800u, retainedBoundary);

    const float targetValue = 7.0f;
    std::array<harken::ContinuousGridWeight, 2> targetWeights{};
    std::uint32_t targetWeightCount = 0;
    ASSERT_EQ(harken::GridEvaluationStatus::Ok,
              harken::EvaluateContinuousGrid(
                  image.container, &targetValue, 1, targetWeights.data(),
                  targetWeights.size(), &targetWeightCount));
    ASSERT_EQ(2u, targetWeightCount);
    ASSERT_EQ(9u, targetWeights[1].childStableOrdinal);
    EXPECT_FLOAT_EQ(0.0f, targetWeights[0].weight);

    ASSERT_EQ(VN_OK, Vn_SetValue(harkentest::ObjectId(41), 7.0f));
    for (std::uint32_t block = 0;
         block < 256 && !row->variableControlRetargetPrepared; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    const VnVariableId axis = harkentest::ObjectId(41);
    float currentValue = 0.0f;
    harken::BankVersionToken currentBank{};
    ASSERT_TRUE(engine->variables.CaptureCurrentBank(
        0, &axis, 1, &currentValue, &currentBank));
    harken::VariableControlInstanceSnapshot control{};
    ASSERT_TRUE(engine->variableControlInstances.Capture(
        row->variableControlInstance, &control));
    ASSERT_TRUE(row->variableControlRetargetPrepared)
        << "nextEvaluation=" << row->VariablePayload().variableControlNextEvaluationFrame
        << " blocks=" << engine->mixer.BlocksRendered()
        << " value=" << currentValue
        << " currentBank=" << currentBank.slot << ":"
        << currentBank.generation
        << " appliedBank=" << control.continuous.lastApplied.slot << ":"
        << control.continuous.lastApplied.generation
        << " pending=" << engine->variables.HasPendingBankWrite(
               0, &axis, 1)
        << " recreate=" << engine->runtimeRecreateRequired;
    ASSERT_EQ(1u, row->VariablePayload().variableControlRetargetLogicalCount);
    EXPECT_EQ(9u, row->VariablePayload().variableControlRetargetLogicalOrdinals[0]);
    EXPECT_EQ(retainedBoundary,
              row->VariablePayload().variableControlRetargetLogicalCompletionFrames[0]);

    for (std::uint32_t block = 0;
         block < 64 && row->variableControlRetargetPrepared; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    ASSERT_FALSE(row->variableControlRetargetPrepared);
    EXPECT_EQ(1u, row->variableControlContinuousMemberCount);
    ASSERT_EQ(1u, row->variableControlContinuousLogicalCount);
    EXPECT_EQ(9u, row->variableControlContinuousLogicalOrdinals[0]);
    EXPECT_EQ(retainedBoundary,
              row->variableControlContinuousLogicalCompletionFrames[0]);
    EXPECT_FALSE(engine->runtimeRecreateRequired);
    EXPECT_EQ(harken::PlayableControlStatus::Ok,
              harken::StopPlayable(*engine, started.instance, 0));
}

