TEST(PlayableStart,
     QueueNaturalEndTransitionFadesEveryLiveCompositeSourceLeaf) {
    VnConfig config = harkentest::MakeNullConfig(8, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    std::vector<float> first(512, 0.25f);
    std::vector<float> second(512, -0.5f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSecondSound, &secondPcm));
    SequenceQueueCompositeTrackWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision);
    image.schedule.placements[1].authoredStart = 0;
    image.schedule.track.scheduleSemanticFingerprint =
        harken::ComputeTrackScheduleFingerprintV1(image.schedule.track);
    image.children[0].timingHint = harken::MakeScheduleReferenceTimingHint(
        harken::PlayableKindV1::Track, image.schedule.track.rootDefinition.stableId,
        image.schedule.track.scheduleSemanticFingerprint);
    image.EnableNaturalEndSourceTransition(128);

    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    const auto prepared = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), prepared);
    ASSERT_TRUE(prepared->queueContinuationPrepared);
    ASSERT_EQ(2u, prepared->QueuePayload().queueCurrentScheduleLeafCount);
    ASSERT_TRUE(prepared->QueueFiling().queueTransition.Valid());
    harken::ArmGroupSnapshot group{};
    ASSERT_TRUE(engine->armGroups.Capture(
        prepared->QueueFiling().queueArmGroup, &group));
    EXPECT_EQ(3u, group.memberCount);
    ASSERT_EQ(2u, prepared->QueueRuntimeViews().queueSourceRuntimeProgram.payloadCount);
    for (std::uint32_t index = 0; index < 2; ++index) {
        EXPECT_EQ(harken::TimelineEventKind::Envelope,
                  prepared->QueueRuntimeViews().queueSourceRuntimeProgram.payloads[index].kind);
        EXPECT_EQ(harken::TimelineEnvelopeDirection::FadeOut,
                  prepared->QueueRuntimeViews().queueSourceRuntimeProgram.
                      payloads[index].envelopeDirection);
    }
    const std::size_t currentBase = prepared->QueuePayload().queueCurrentScheduleBase;
    const std::array<VnVoiceHandle, 2> sources{
        engine->ReadPlayableMember(currentBase).render,
        engine->ReadPlayableMember(currentBase + 1u).render};
    ASSERT_NE(sources[0], sources[1]);
    for (std::uint32_t index = 0; index < sources.size(); ++index) {
        const harken::TimelineArmToken sourceControl =
            prepared->QueueFiling().queueTransitionGroupArms[index];
        EXPECT_EQ(static_cast<std::uint32_t>(sources[index]),
                  sourceControl.renderSlot);
        EXPECT_EQ(static_cast<std::uint32_t>(sources[index] >> 32),
                  sourceControl.renderGeneration);
    }
    const std::uint64_t audibleFrame =
        prepared->QueueRuntimeViews().queueSourceRuntimeProgram.payloads[0].envelopeStartFrame;
    const std::uint64_t completionFrame = prepared->QueuePayload().queueCompletionFrame;
    const VnVoiceHandle targetHandle =
        prepared->QueuePayload().queueSuccessorRenderHandle;
    const harken::TimelineArmToken targetArm =
        prepared->QueueFiling().queueTransitionGroupArms[
            prepared->QueueFiling().queueSourceControlArmCount];
    std::uint32_t audiblePage = 0;
    ASSERT_TRUE(engine->timelinePool.PageForFrame(
        audibleFrame, &audiblePage));
    const harken::HorizonPageHeader* audibleHeader =
        engine->timelinePool.Page(audiblePage);
    ASSERT_NE(nullptr, audibleHeader);
    const auto preludeIdentity = harkentest::QueueContinuationSlice(*engine, prepared->QueueFiling().queueDecision, 0);
    harken::Plan03PageGroupView prelude{};
    ASSERT_TRUE(engine->timelinePool.ResolvePlan03GroupSliceProducer(
        preludeIdentity, &prelude));
    EXPECT_EQ(2u, prelude.sourceControlCount);
    while (engine->mixer.BlocksRendered() *
               engine->config.blockFrames <= audibleFrame) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    harken::TransitionInstanceSnapshot transition{};
    ASSERT_TRUE(engine->transitionInstances.Capture(
        prepared->QueueFiling().queueTransition, &transition));
    EXPECT_EQ(harken::TransitionAudibleGateState::Locked,
              transition.state);
    harken::DecisionCommittedSnapshot decision{};
    ASSERT_TRUE(engine->decisions.CaptureCommitted(
        prepared->QueueFiling().queueDecision, &decision));
    EXPECT_EQ(harken::AudioGroupState::AudioClaimed,
              decision.audioState);
    ASSERT_TRUE(engine->timelinePool.ResolvePlan03GroupSliceProducer(
        preludeIdentity, &prelude));
    EXPECT_EQ(harken::AudioSliceState::SliceApplied,
              prelude.lease->Capture().state)
        << "audibleFrame=" << audibleFrame
        << " renderedFrame="
        << engine->mixer.BlocksRendered() * engine->config.blockFrames
        << " frontier=" << engine->timelinePool.ConsumerFrontier().load()
        << " audibleQuantum="
        << audibleFrame / engine->config.blockFrames;
    EXPECT_TRUE(audibleHeader->frozen);
    EXPECT_GT(engine->timelinePool.ConsumerFrontier().load(),
              audibleFrame / engine->config.blockFrames);
    harken::ArmGroupSnapshot observedGroup{};
    ASSERT_TRUE(engine->armGroups.Capture(
        prepared->QueueFiling().queueArmGroup, &observedGroup));
    EXPECT_EQ(harken::ArmGroupState::Ready,
              observedGroup.state);
    for (std::uint32_t index = 0; index < sources.size(); ++index) {
        const VnVoiceHandle sourceHandle = sources[index];
        const harken::VoiceRenderContext* source =
            engine->voices.Resolve(sourceHandle);
        ASSERT_NE(nullptr, source);
        harken::TimelineArmObservation sourceControl{};
        ASSERT_TRUE(engine->timelineArms.Observe(
            prepared->QueueFiling().queueTransitionGroupArms[index], &sourceControl));
        EXPECT_TRUE(source->timelineEnvelopes[1].active)
            << "source=" << index
            << " arm=" << static_cast<std::uint32_t>(sourceControl.state)
            << " events=" << source->timelineEvents.eventCount
            << " eventQuantum=" << source->timelineEvents.quantumIndex
            << " phase=" << static_cast<std::uint32_t>(source->phase)
            << " cursor=" << source->srcCursor
            << " produced=" << source->lastResult.framesProduced
            << " protocol="
            << engine->timelineExecutor.Stats().protocolViolation
            << " overflow="
            << engine->timelineExecutor.Stats().spanOverflowDropped;
        EXPECT_TRUE(source->timelineEnvelopes[1].fadeOut)
            << "source=" << index
            << " arm=" << static_cast<std::uint32_t>(sourceControl.state)
            << " protocol="
            << engine->timelineExecutor.Stats().protocolViolation;
    }
    harken::TimelineArmObservation targetBeforeCompletion{};
    ASSERT_TRUE(engine->timelineArms.Observe(
        targetArm, &targetBeforeCompletion));
    EXPECT_EQ(harken::ArmState::Published,
              targetBeforeCompletion.state);

    while (engine->mixer.BlocksRendered() *
               engine->config.blockFrames <= completionFrame) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    harken::TimelineArmObservation targetAfterCompletion{};
    ASSERT_TRUE(engine->timelineArms.Observe(
        targetArm, &targetAfterCompletion));
    EXPECT_NE(0u, targetAfterCompletion.startedBlockSequence);
    const harken::VoiceRenderContext* target =
        engine->voices.Resolve(targetHandle);
    ASSERT_NE(nullptr, target);
    EXPECT_FALSE(target->timelineGated);
    EXPECT_GT(target->srcCursor, 0.0);
}

TEST(PlayableStart,
     QueueCompositeSourceLaneAttemptShortfallHasZeroPartialPublication) {
    VnConfig config = harkentest::MakeNullConfig(6, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    std::vector<float> first(512, 0.25f);
    std::vector<float> second(512, -0.5f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSecondSound, &secondPcm));

    QueueLaneCapacityPressure pressure(*engine);
    ASSERT_TRUE(pressure.ExhaustAttempts());

    SequenceQueueCompositeTrackWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision);
    image.schedule.placements[1].authoredStart = 0;
    image.schedule.track.scheduleSemanticFingerprint =
        harken::ComputeTrackScheduleFingerprintV1(image.schedule.track);
    image.children[0].timingHint = harken::MakeScheduleReferenceTimingHint(
        harken::PlayableKindV1::Track, image.schedule.track.rootDefinition.stableId,
        image.schedule.track.scheduleSemanticFingerprint);
    image.EnableNaturalEndSourceTransition(128);
    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);

    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    EXPECT_FALSE(row->queueContinuationPrepared);
    EXPECT_FALSE(row->QueueFiling().queueSuccessorArm.Valid());
    EXPECT_FALSE(row->QueueFiling().queueTransition.Valid());
    EXPECT_FALSE(row->QueueFiling().queueArmGroup.Valid());
    EXPECT_EQ(2u, engine->timelinePool.LiveTransactionCount());
    EXPECT_EQ(2u, engine->timelinePool.TransactionHighWater());
}

TEST(PlayableStart,
     QueueNaturalEndTransitionFadesEveryLiveCompositeSegmentSourceLeaf) {
    VnConfig config = harkentest::MakeNullConfig(8, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    std::vector<float> first(512, 0.25f);
    std::vector<float> second(512, -0.5f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSecondSound, &secondPcm));
    SequenceQueueCompositeSegmentWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision);
    image.EnableNaturalEndSourceTransition(128);

    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    const auto prepared = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), prepared);
    ASSERT_TRUE(prepared->queueContinuationPrepared);
    ASSERT_EQ(2u, prepared->QueuePayload().queueCurrentScheduleLeafCount);
    ASSERT_TRUE(prepared->QueueFiling().queueTransition.Valid());
    harken::ArmGroupSnapshot group{};
    ASSERT_TRUE(engine->armGroups.Capture(
        prepared->QueueFiling().queueArmGroup, &group));
    EXPECT_EQ(3u, group.memberCount);
    ASSERT_EQ(2u, prepared->QueueRuntimeViews().queueSourceRuntimeProgram.payloadCount);
    for (std::uint32_t index = 0; index < 2; ++index) {
        EXPECT_EQ(harken::TimelineEventKind::Envelope,
                  prepared->QueueRuntimeViews().queueSourceRuntimeProgram.payloads[index].kind);
        EXPECT_EQ(harken::TimelineEnvelopeDirection::FadeOut,
                  prepared->QueueRuntimeViews().queueSourceRuntimeProgram.
                      payloads[index].envelopeDirection);
    }
    const std::size_t currentBase = prepared->QueuePayload().queueCurrentScheduleBase;
    const std::array<VnVoiceHandle, 2> sources{
        engine->ReadPlayableMember(currentBase).render,
        engine->ReadPlayableMember(currentBase + 1u).render};
    const std::uint64_t audibleFrame =
        prepared->QueueRuntimeViews().queueSourceRuntimeProgram.payloads[0].envelopeStartFrame;
    const std::uint64_t completionFrame = prepared->QueuePayload().queueCompletionFrame;
    const VnVoiceHandle targetHandle =
        prepared->QueuePayload().queueSuccessorRenderHandle;
    const harken::TimelineArmToken targetArm =
        prepared->QueueFiling().queueTransitionGroupArms[
            prepared->QueueFiling().queueSourceControlArmCount];

    while (engine->mixer.BlocksRendered() *
               engine->config.blockFrames <= audibleFrame) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    for (std::uint32_t index = 0; index < sources.size(); ++index) {
        const harken::VoiceRenderContext* source =
            engine->voices.Resolve(sources[index]);
        ASSERT_NE(nullptr, source);
        EXPECT_TRUE(source->timelineEnvelopes[1].active);
        EXPECT_TRUE(source->timelineEnvelopes[1].fadeOut);
    }
    harken::TimelineArmObservation targetBeforeCompletion{};
    ASSERT_TRUE(engine->timelineArms.Observe(
        targetArm, &targetBeforeCompletion));
    EXPECT_EQ(harken::ArmState::Published,
              targetBeforeCompletion.state);

    while (engine->mixer.BlocksRendered() *
               engine->config.blockFrames <= completionFrame) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    harken::TimelineArmObservation targetAfterCompletion{};
    ASSERT_TRUE(engine->timelineArms.Observe(
        targetArm, &targetAfterCompletion));
    EXPECT_NE(0u, targetAfterCompletion.startedBlockSequence);
    const harken::VoiceRenderContext* target =
        engine->voices.Resolve(targetHandle);
    ASSERT_NE(nullptr, target);
    EXPECT_FALSE(target->timelineGated);
    EXPECT_GT(target->srcCursor, 0.0);
}

TEST(PlayableStart, QueueCompositeSuccessorAdvancesOnlyAfterLatestLeaf) {
    VnConfig config = harkentest::MakeNullConfig(5, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    std::vector<float> first(512, 0.25f);
    std::vector<float> second(512, -0.5f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSecondSound, &secondPcm));
    SequenceQueueCompositeTrackWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision);
    std::array<harken::ContainerChildProgramViewV2, 3> children{
        image.children[1], image.children[0], image.children[1]};
    std::array<harken::PlayableOccurrencePropertyViewV1, 5> occurrences{};
    for (std::uint32_t index = 0; index < children.size(); ++index) {
        children[index].stableChildOrdinal = 7u + index;
        children[index].authoredStableOrder = index;
        occurrences[index].parentKind = harken::playableproperties::
            ContentPropertyKindV1::Container;
        occurrences[index].parentStableId = harkentest::ObjectId(kContainer);
        occurrences[index].parentProgramSemanticFingerprint =
            image.properties[3].programSemanticFingerprint;
        occurrences[index].stableOccurrenceOrdinal =
            children[index].stableChildOrdinal;
        occurrences[index].childPlayable = children[index].playable;
        occurrences[index].payload = CanonicalPayload();
        occurrences[index].occurrenceSemanticFingerprint =
            harken::ComputePlayableOccurrenceFingerprintV1(
                occurrences[index]);
    }
    occurrences[3] = image.schedule.occurrences[0];
    occurrences[4] = image.schedule.occurrences[1];
    harken::ContainerProgramViewV3 container = image.container;
    container.childCount = children.size();
    container.children = children.data();
    harken::PlayableWorldViewV1 world = image.world;
    world.occurrences = occurrences.data();
    world.occurrenceCount = occurrences.size();
    world.containers = &container;
    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    bool heardInitial = false;
    bool heardLatestCompositeLeaf = false;
    bool finalStartedAfterLatest = false;
    for (std::uint32_t block = 0; block < 96; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        const float* output = engine->nullBackend.LastBlock();
        for (std::uint32_t sample = 0;
             sample < 2u * engine->config.blockFrames; ++sample) {
            heardInitial = heardInitial || output[sample] > 0.0f;
            heardLatestCompositeLeaf =
                heardLatestCompositeLeaf ||
                (heardInitial && output[sample] < 0.0f);
        }
        const auto active = std::find_if(
            engine->playableServices.begin(), engine->playableServices.end(),
            [&](const harken::EnginePlayableServiceRow& candidate) {
                return candidate.rootInstance == started.instance;
            });
        const auto* activeInstall = active == engine->playableServices.end()
            ? nullptr : engine->ResolvePlayableServiceVoice(*active);
        if (activeInstall != nullptr &&
            active->queueInstance.Valid() && heardLatestCompositeLeaf &&
            activeInstall->Facts().soundId == kSound) {
            harken::QueueInstanceSnapshot queue{};
            harken::TimelineArmObservation arm{};
            finalStartedAfterLatest = finalStartedAfterLatest ||
                (engine->queueInstances.Capture(
                     active->queueInstance, &queue) &&
                 queue.logicMirror.version == 3u &&
                 queue.logicMirror.currentChildOrdinal == 9u &&
                 engine->timelineArms.Observe(active->arm, &arm) &&
                 arm.startedBlockSequence != 0);
        }
    }
    EXPECT_TRUE(heardInitial);
    EXPECT_TRUE(heardLatestCompositeLeaf);
    EXPECT_TRUE(finalStartedAfterLatest);
}

