TEST(PlayableStart, SequenceQueueSignalOnlyNoOverlapStartsAfterRealCompletion) {
    VnConfig config = harkentest::MakeNullConfig(2, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(session.InitResult(), VN_OK);
    harken::Engine* engine = session.Engine();
    ASSERT_NE(engine, nullptr);

    std::vector<float> first(96, 0.25f);
    std::vector<float> second(96, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(Vn_RegisterPCM(kSound, &firstPcm), VN_OK);
    ASSERT_EQ(Vn_RegisterPCM(kSecondSound, &secondPcm), VN_OK);
    SequenceQueueWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision,
        harken::QueueCycleV1::Once, false,
        harken::AuthoredCompletionClassV1::SignalOnly,
        harken::SignalOnlyPolicyV1::StartNextAtEarliestSafeNoOverlap);
    const std::uint32_t queueBaseline =
        engine->queueInstances.LiveCount();
    const std::uint32_t occurrenceBaseline =
        engine->timelineOccurrences.OccupiedCount();

    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);

    bool heardFirst = false;
    bool heardSecondAfterFirst = false;
    for (std::uint32_t block = 0; block < 32; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        const float* output = engine->nullBackend.LastBlock();
        for (std::uint32_t sample = 0;
             sample < 2u * engine->config.blockFrames; ++sample) {
            heardFirst = heardFirst || output[sample] > 0.0f;
            heardSecondAfterFirst =
                heardSecondAfterFirst ||
                (heardFirst && output[sample] < 0.0f);
        }
    }
    EXPECT_TRUE(heardFirst);
    EXPECT_TRUE(heardSecondAfterFirst);
    EXPECT_EQ(queueBaseline, engine->queueInstances.LiveCount());
    EXPECT_EQ(occurrenceBaseline,
              engine->timelineOccurrences.OccupiedCount());
}

static void CheckSignalQueueReceiptStop(bool applyBeforeStop, bool nestedSuccessor = false) {
    harkentest::EngineSession session(harkentest::MakeNullConfig(2, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    std::vector<float> first(96, 0.25f), second(2048, -0.25f);
    const auto firstPcm = harkentest::MonoDesc(first, 48000);
    const auto secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSecondSound, &secondPcm));
    SequenceQueueWorldImage image(engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision, harken::QueueCycleV1::Loop, true,
        harken::AuthoredCompletionClassV1::SignalOnly,
        harken::SignalOnlyPolicyV1::StartNextAtEarliestSafeNoOverlap);
    std::array<harken::PlayablePropertyProgramViewV1, 4> properties{};
    std::array<harken::PlayableOccurrencePropertyViewV1, 3> occurrences{};
    std::array<harken::ContainerProgramViewV3, 2> containers{};
    harken::ContainerChildProgramViewV2 nestedChild{};
    if (nestedSuccessor) {
        std::copy(image.properties.begin(), image.properties.end(), properties.begin());
        properties[3] = properties[2];
        properties[3].stableId = harkentest::ObjectId(2002);
        properties[3].authoredStableOrder = 3;
        properties[3].programSemanticFingerprint =
            harken::ComputePlayablePropertyFingerprintV1(properties[3]);
        nestedChild = image.children[1];
        nestedChild.stableChildOrdinal = 1;
        nestedChild.authoredStableOrder = 0;
        auto nested = image.Root();
        nested.stableId = properties[3].stableId;
        nested.expectedProgramSemanticFingerprint = properties[3].programSemanticFingerprint;
        image.children[1].playable = nested;
        image.children[1].timingHint = {};
        containers = {image.container, image.container};
        containers[1].containerStableId = nested.stableId;
        containers[1].programSemanticFingerprint = nested.expectedProgramSemanticFingerprint;
        containers[1].mode = harken::ContainerModeV1::Sequence;
        containers[1].childCount = 1;
        containers[1].children = &nestedChild;
        containers[1].queueCycle = harken::QueueCycleV1::Once;
        containers[1].resumePosition = 0;
        occurrences = {image.occurrences[0], image.occurrences[1], image.occurrences[1]};
        occurrences[1].childPlayable = nested;
        occurrences[1].occurrenceSemanticFingerprint =
            harken::ComputePlayableOccurrenceFingerprintV1(occurrences[1]);
        occurrences[2].parentStableId = nested.stableId;
        occurrences[2].parentProgramSemanticFingerprint = nested.expectedProgramSemanticFingerprint;
        occurrences[2].stableOccurrenceOrdinal = nestedChild.stableChildOrdinal;
        occurrences[2].occurrenceSemanticFingerprint =
            harken::ComputePlayableOccurrenceFingerprintV1(occurrences[2]);
        image.world.properties = properties.data();
        image.world.propertyCount = properties.size();
        image.world.occurrences = occurrences.data();
        image.world.occurrenceCount = occurrences.size();
        image.world.containers = containers.data();
        image.world.containerCount = containers.size();
        image.world.identity.capabilityMask |= harken::kWorldCapabilitySequence;
    }
    harken::PlayableStartRequest request{};
    request.root = image.Root();
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&request.emitter));
    const auto capture = harkentest::monitor::OpenIdentityEvents();
    std::vector<harkentest::monitor::IdentityRecord> records;
    const auto countSelections = [&] {
        return std::count_if(records.begin(), records.end(), [](const auto& record) {
            return record.fact.factKind == VN_MONITOR_FACT_SELECTION_COMMITTED;
        });
    };
    const auto started = harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    auto row = std::find_if(engine->playableServices.begin(), engine->playableServices.end(),
        [&](const auto& candidate) { return candidate.rootInstance == started.instance; });
    ASSERT_NE(engine->playableServices.end(), row);
    const auto queue = row->queueInstance;
    const auto checkpointKey = row->QueueCheckpointKey();
    for (std::uint32_t block = 0; block < 32 && !row->frontierAcceptedSignal.Valid(); ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        harkentest::monitor::CollectIdentityEvents(capture, records);
        if (!row->frontierAcceptedSignal.Valid()) engine->nullBackend.Pump(1);
    }
    ASSERT_TRUE(row->frontierAcceptedSignal.Valid());
    if (!nestedSuccessor) EXPECT_EQ(1, countSelections());
    const auto entry = row->frontierEntry;
    const auto* resource = nestedSuccessor
        ? engine->ResolvePlayableService(row->frontierChildService) : &*row;
    ASSERT_NE(nullptr, resource);
    const auto arm = resource->arm;
    const auto onset = row->startFrame;
    harken::EffectiveQueueState pending{};
    ASSERT_TRUE(engine->queueInstances.ResolveEffective(queue, &pending));
    EXPECT_EQ(1u, pending.version);
    EXPECT_EQ(image.children[0].stableChildOrdinal, pending.currentChildOrdinal);
    if (applyBeforeStop) {
        while (engine->mixer.BlocksRendered() <= onset / 64) {
            ASSERT_EQ(VN_OK, Vn_Update());
            harkentest::monitor::CollectIdentityEvents(capture, records);
            ASSERT_TRUE(engine->queueInstances.ResolveEffective(queue, &pending));
            EXPECT_EQ(1u, pending.version);
            engine->nullBackend.Pump(1);
        }
        harken::TimelineArmObservation observed{};
        ASSERT_TRUE(engine->timelineArms.Observe(arm, &observed));
        EXPECT_EQ(onset / 64 + 1u, observed.startedBlockSequence);
        const auto* activation = engine->decisions.ResolveFrontierActivation(entry.coordinator);
        ASSERT_NE(nullptr, activation);
        harken::FrontierActivationReceipt receipt{};
        ASSERT_EQ(harken::FrontierReceiptRead::Ready,
            activation->Read(entry, engine->mixer.BlocksRendered(), &receipt));
        EXPECT_EQ(harken::FrontierReceiptOutcome::Applied, receipt.outcome);
        ASSERT_TRUE(engine->queueInstances.ResolveEffective(queue, &pending));
        EXPECT_EQ(1u, pending.version);
    }
    ASSERT_EQ(harken::PlayableControlStatus::Ok, harken::StopPlayable(*engine, started.instance, 0));
    for (std::uint32_t block = 0; block < 48; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        harkentest::monitor::CollectIdentityEvents(capture, records);
        engine->nullBackend.Pump(1);
    }
    ASSERT_EQ(VN_OK, Vn_Update());
    harkentest::monitor::CollectIdentityEvents(capture, records);
    harken::QueueCheckpointImage checkpoint{};
    ASSERT_TRUE(engine->queueCheckpoints.Load(checkpointKey, &checkpoint));
    EXPECT_EQ(applyBeforeStop ? 2u : 1u, checkpoint.effective.version);
    EXPECT_EQ(image.children[applyBeforeStop ? 1u : 0u].stableChildOrdinal,
        checkpoint.effective.currentChildOrdinal);
    EXPECT_FALSE(engine->playableInstances.Classify(started.instance).live);
    EXPECT_EQ(0u, engine->queueInstances.LiveCount());
    EXPECT_EQ(0u, engine->timelineOccurrences.OccupiedCount());
    EXPECT_EQ(0u, engine->timelineArms.LiveCount());
    EXPECT_EQ(0u, engine->decisions.LiveCount());
    EXPECT_EQ(0u, engine->armGroups.LiveCount());
    EXPECT_FALSE(engine->runtimeRecreateRequired);
    harkentest::monitor::CollectIdentityEvents(capture, records);
    if (!nestedSuccessor) EXPECT_EQ(applyBeforeStop ? 2 : 1, countSelections());
    unsigned successors = 0;
    for (const auto& record : records) {
        if (record.fact.factKind != VN_MONITOR_FACT_SELECTION_COMMITTED ||
            record.header.stableId != kSecondSound) continue;
        ++successors;
        EXPECT_EQ(started.instance, record.fact.root);
        EXPECT_FALSE(harken::monitor::FactHas(record.fact, VN_MONITOR_FACT_FIELD_SELECTION_REQUEST));
    }
    EXPECT_EQ(applyBeforeStop ? 1u : 0u, successors);
    EXPECT_EQ(VN_OK, Vn_MonitorCloseSession(capture));

    const auto replayed = harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, replayed.status);
    float firstReplaySample = 0.0f;
    for (std::uint32_t block = 0; block < 64 && firstReplaySample == 0.0f; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        const auto* output = engine->nullBackend.LastBlock();
        for (std::uint32_t sample = 0; sample < 2u * engine->config.blockFrames; ++sample) {
            if (std::abs(output[sample]) <= 0.01f) continue;
            firstReplaySample = output[sample];
            break;
        }
    }
    EXPECT_NE(0.0f, firstReplaySample);
    if (applyBeforeStop) EXPECT_LT(firstReplaySample, 0.0f);
    else EXPECT_GT(firstReplaySample, 0.0f);
    ASSERT_EQ(harken::PlayableControlStatus::Ok, harken::StopPlayable(*engine, replayed.instance, 0));
    for (std::uint32_t block = 0; block < 48; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    ASSERT_EQ(VN_OK, Vn_Update());
    EXPECT_EQ(0u, engine->playableInstances.LiveCount());
    EXPECT_EQ(0u, engine->queueInstances.LiveCount());
    EXPECT_EQ(0u, engine->timelineOccurrences.OccupiedCount());
    EXPECT_EQ(0u, engine->timelineArms.LiveCount());
    EXPECT_EQ(0u, engine->decisions.LiveCount());
    EXPECT_EQ(0u, engine->armGroups.LiveCount());
    EXPECT_FALSE(engine->runtimeRecreateRequired);
}

TEST(PlayableStart, SignalQueueAcceptedChildDoesNotAdvanceBeforeAudioAndStopReturnsSelection) {
    CheckSignalQueueReceiptStop(false);
}

TEST(PlayableStart, SignalQueueAppliedChildSettlesBeforeStopWithoutInterveningUpdate) {
    CheckSignalQueueReceiptStop(true);
}

TEST(PlayableStart, SignalQueueAcceptedContainerStopResumesPreviousChild) {
    CheckSignalQueueReceiptStop(false, true);
}

TEST(PlayableStart, SignalQueueAppliedContainerStopResumesItsSound) {
    CheckSignalQueueReceiptStop(true, true);
}

TEST(PlayableStart, SequenceQueueMarkerAlignedRequiresKnownCompletion) {
    VnConfig config = harkentest::MakeNullConfig(2, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(session.InitResult(), VN_OK);
    harken::Engine* engine = session.Engine();
    ASSERT_NE(engine, nullptr);

    std::vector<float> first(512, 0.25f);
    std::vector<float> second(512, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(Vn_RegisterPCM(kSound, &firstPcm), VN_OK);
    ASSERT_EQ(Vn_RegisterPCM(kSecondSound, &secondPcm), VN_OK);
    SequenceQueueWorldImage known(
        engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision,
        harken::QueueCycleV1::Once, false,
        harken::AuthoredCompletionClassV1::FiniteMediaCandidate,
        harken::SignalOnlyPolicyV1::StopQueue,
        harken::QueueSpliceV1::MarkerAligned);
    harken::PlayableStartRequest request{};
    request.root = known.Root();
    const harken::PlayableStartResult accepted =
        harken::StartPlayable(*engine, known.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, accepted.status);

    bool heardFirst = false;
    bool heardSecond = false;
    for (std::uint32_t block = 0; block < 32; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        const float* output = engine->nullBackend.LastBlock();
        heardFirst = heardFirst || std::any_of(
            output, output + 2u * engine->config.blockFrames,
            [](float sample) { return sample > 0.0f; });
        heardSecond = heardSecond || std::any_of(
            output, output + 2u * engine->config.blockFrames,
            [](float sample) { return sample < 0.0f; });
    }
    EXPECT_TRUE(heardFirst);
    EXPECT_TRUE(heardSecond);

    SequenceQueueWorldImage signal(
        engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision,
        harken::QueueCycleV1::Once, false,
        harken::AuthoredCompletionClassV1::SignalOnly,
        harken::SignalOnlyPolicyV1::StartNextAtEarliestSafeNoOverlap,
        harken::QueueSpliceV1::MarkerAligned);
    request.root = signal.Root();
    const harken::PlayableStartResult refused =
        harken::StartPlayable(*engine, signal.world, request);
    EXPECT_EQ(harken::PlayableStartStatus::CapabilityUnavailable,
              refused.status);
}

TEST(PlayableStart, SequenceQueueTailNeverBecomesCurrentAfterAdvance) {
    VnConfig config = harkentest::MakeNullConfig(3, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(session.InitResult(), VN_OK);
    harken::Engine* engine = session.Engine();
    ASSERT_NE(engine, nullptr);

    std::vector<float> first(96, 0.25f);
    std::vector<float> second(512, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(Vn_RegisterPCM(kSound, &firstPcm), VN_OK);
    ASSERT_EQ(Vn_RegisterPCM(kSecondSound, &secondPcm), VN_OK);
    SequenceQueueWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision,
        harken::QueueCycleV1::Once, false,
        harken::AuthoredCompletionClassV1::FiniteMediaCandidate,
        harken::SignalOnlyPolicyV1::StopQueue,
        harken::QueueSpliceV1::Butt, true);
    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const auto capture = harkentest::monitor::OpenIdentityEvents();
    std::vector<harkentest::monitor::IdentityRecord> records;
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);

    const harken::EnginePlayableServiceRow* row = nullptr;
    bool successorCurrentWhileTailLive = false;
    for (std::uint32_t block = 0; block < 64; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        harkentest::monitor::CollectIdentityEvents(capture, records);
        engine->nullBackend.Pump(1);
        const auto found = std::find_if(
            engine->playableServices.begin(), engine->playableServices.end(),
            [&](const harken::EnginePlayableServiceRow& candidate) {
                return candidate.rootInstance == started.instance;
            });
        if (found == engine->playableServices.end()) break;
        row = &*found;
        std::uint32_t liveChildren = 0;
        engine->ledger.ForEachPlayableOwnedLive(
            [&](VnVoiceHandle render,
                const harken::VoiceLedger::PlayableParentRef& parent) {
                if (parent.internalToken == started.instance &&
                    engine->voices.Resolve(render) != nullptr) {
                    ++liveChildren;
                }
            });
        successorCurrentWhileTailLive =
            successorCurrentWhileTailLive ||
            (row->leaf.stableId == kSecondSound && liveChildren >= 2u);
    }
    EXPECT_TRUE(successorCurrentWhileTailLive);
    ASSERT_EQ(VN_OK, Vn_Update());
    harkentest::monitor::CollectIdentityEvents(capture, records);
    records.erase(std::remove_if(records.begin(), records.end(),
        [&](const auto& record) {
            return record.fact.root != started.instance ||
                record.fact.contentKind != VN_MONITOR_CONTENT_SOUND ||
                (record.fact.factKind != VN_MONITOR_FACT_PLAYABLE_STARTED &&
                 record.fact.factKind != VN_MONITOR_FACT_PLAYABLE_FINISHED);
        }), records.end());
    ASSERT_EQ(4u, records.size());
    const auto findEvent = [&](VnObjectId object, std::uint32_t kind) {
        return std::find_if(records.begin(), records.end(), [&](const auto& record) {
            return record.header.stableId == object && record.fact.factKind == kind;
        });
    };
    const auto firstStarted = findEvent(kSound, VN_MONITOR_FACT_PLAYABLE_STARTED);
    const auto secondStarted = findEvent(kSecondSound, VN_MONITOR_FACT_PLAYABLE_STARTED);
    const auto firstFinished = findEvent(kSound, VN_MONITOR_FACT_PLAYABLE_FINISHED);
    const auto secondFinished = findEvent(kSecondSound, VN_MONITOR_FACT_PLAYABLE_FINISHED);
    ASSERT_NE(records.end(), firstStarted);
    ASSERT_NE(records.end(), secondStarted);
    ASSERT_NE(records.end(), firstFinished);
    ASSERT_NE(records.end(), secondFinished);
    EXPECT_LT(firstStarted, secondStarted);
    EXPECT_LT(secondStarted, firstFinished);
    EXPECT_LT(secondStarted, secondFinished);
    EXPECT_EQ(firstStarted->header.executeFrame + first.size(), secondStarted->header.executeFrame);
    EXPECT_LT(secondStarted->header.executeFrame, firstFinished->header.executeFrame);
    EXPECT_EQ(secondStarted->header.executeFrame + second.size(), secondFinished->header.executeFrame);
    EXPECT_LE(secondStarted->fact.timestampNs, firstFinished->fact.timestampNs);
    EXPECT_EQ(firstStarted->header.instanceHandle, firstFinished->header.instanceHandle);
    EXPECT_EQ(secondStarted->header.instanceHandle, secondFinished->header.instanceHandle);
    EXPECT_EQ(VN_MONITOR_TERMINAL_NATURAL_COMPLETION, firstFinished->fact.terminalKind);
    EXPECT_EQ(VN_MONITOR_TERMINAL_NATURAL_COMPLETION, secondFinished->fact.terminalKind);
    EXPECT_EQ(VN_OK, Vn_MonitorCloseSession(capture));
}

TEST(PlayableStart, SequenceQueueLoopReturnsToFirstSoundWithoutPoolGrowth) {
    VnConfig config = harkentest::MakeNullConfig(3, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(session.InitResult(), VN_OK);
    harken::Engine* engine = session.Engine();
    ASSERT_NE(engine, nullptr);

    std::vector<float> first(512, 0.25f);
    std::vector<float> second(512, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(Vn_RegisterPCM(kSound, &firstPcm), VN_OK);
    ASSERT_EQ(Vn_RegisterPCM(kSecondSound, &secondPcm), VN_OK);
    SequenceQueueWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision,
        harken::QueueCycleV1::Loop);
    const std::uint32_t queueBaseline =
        engine->queueInstances.LiveCount();
    const std::uint32_t decisionBaseline = engine->decisions.LiveCount();
    const std::uint32_t groupBaseline = engine->armGroups.LiveCount();
    const std::uint32_t occurrenceBaseline =
        engine->timelineOccurrences.OccupiedCount();

    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);

    bool heardFirst = false;
    bool heardSecond = false;
    bool heardFirstAgain = false;
    std::array<std::uint32_t, 3> warmPeaks{};
    std::uint64_t audibleFrames = 0;
    for (std::uint32_t block = 0; block < 1024; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        const float* output = engine->nullBackend.LastBlock();
        for (std::uint32_t sample = 0;
             sample < 2u * engine->config.blockFrames; ++sample) {
            if (output[sample] > 0.0f) {
                heardFirstAgain = heardFirstAgain || heardSecond;
                heardFirst = true;
            } else if (heardFirst && output[sample] < 0.0f) {
                heardSecond = true;
            }
        }
        for (std::uint32_t frame = 0; frame < engine->config.blockFrames; ++frame) {
            const auto sample = output[2u * frame];
            if (audibleFrames == 0 && std::abs(sample) < 1e-7f) continue;
            const auto expected = ((audibleFrames / first.size()) % 2u) == 0 ? 1.0f : -1.0f;
            ASSERT_GT(sample * expected, 0.01f) << "audible frame " << audibleFrames;
            ++audibleFrames;
        }
        const std::array<std::uint32_t, 3> live{engine->decisions.LiveCount(),
            engine->armGroups.LiveCount(), engine->timelineOccurrences.OccupiedCount()};
        for (std::size_t resource = 0; resource < live.size(); ++resource) {
            if (block < 128) warmPeaks[resource] = std::max(warmPeaks[resource], live[resource]);
            else ASSERT_LE(live[resource], warmPeaks[resource]) << "resource " << resource << " block " << block;
        }
        ASSERT_FALSE(engine->runtimeRecreateRequired);
    }
    EXPECT_TRUE(heardFirst);
    EXPECT_TRUE(heardSecond);
    EXPECT_TRUE(heardFirstAgain);
    EXPECT_EQ(queueBaseline + 1u, engine->queueInstances.LiveCount());
    EXPECT_GT(audibleFrames / (first.size() + second.size()), 32u);
    ASSERT_EQ(harken::PlayableControlStatus::Ok, harken::StopPlayable(*engine, started.instance, 0));
    for (std::uint32_t block = 0; block < 128; ++block) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    EXPECT_EQ(queueBaseline, engine->queueInstances.LiveCount());
    EXPECT_EQ(decisionBaseline, engine->decisions.LiveCount());
    EXPECT_EQ(groupBaseline, engine->armGroups.LiveCount());
    EXPECT_EQ(occurrenceBaseline, engine->timelineOccurrences.OccupiedCount());
    EXPECT_EQ(0u, engine->voices.ActiveCount());
}

TEST(PlayableStart, SequenceQueueLogicalChildrenRetireDuringRepeatedPlayback) {
    for (const bool segmentChild : {false, true}) for (const auto cycles : {0u, 4u}) {
        SCOPED_TRACE(segmentChild);
        SCOPED_TRACE(cycles);
        harkentest::EngineSession session(harkentest::MakeNullConfig(8, 64, 48000));
        ASSERT_EQ(VN_OK, session.InitResult());
        auto* engine = session.Engine();
        std::vector<float> first(512, 0.25f), second(512, -0.25f);
        const auto firstPcm = harkentest::MonoDesc(first, 48000);
        const auto secondPcm = harkentest::MonoDesc(second, 48000);
        ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &firstPcm));
        ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSecondSound, &secondPcm));
        SequenceQueueCompositeSegmentWorldImage image(engine->registry.Lookup(kSound).contentRevision,
            engine->registry.Lookup(kSecondSound).contentRevision);
        image.schedule.placements[0].authoredStart = INT64_C(10000000);
        image.schedule.placements[1].authoredStart = INT64_C(20000000);
        for (auto& placement : image.schedule.placements) placement.authoredDuration = 1;
        image.schedule.track.scheduleSemanticFingerprint =
            harken::ComputeTrackScheduleFingerprintV1(image.schedule.track);
        image.trackRef.trackScheduleSemanticFingerprint = image.schedule.track.scheduleSemanticFingerprint;
        image.segment.scheduleSemanticFingerprint = harken::ComputeSegmentScheduleFingerprintV1(image.segment);
        image.children[0].playable = segmentChild ? image.segment.rootDefinition : image.schedule.track.rootDefinition;
        image.children[0].timingHint = harken::MakeScheduleReferenceTimingHint(
            image.children[0].playable.kind, image.children[0].playable.stableId,
            segmentChild ? image.segment.scheduleSemanticFingerprint : image.schedule.track.scheduleSemanticFingerprint);
        image.children[0].authoredStableOrder = 1;
        image.children[1].authoredStableOrder = 0;
        image.occurrences[0].childPlayable = image.children[0].playable;
        image.occurrences[0].occurrenceSemanticFingerprint =
            harken::ComputePlayableOccurrenceFingerprintV1(image.occurrences[0]);
        image.container.queueCycle = harken::QueueCycleV1::Loop;
        image.container.queueCycleCount = cycles;
        const auto baseline = engine->playableInstances.LiveCount();
        const auto capture = harkentest::monitor::OpenIdentityEvents();
        std::vector<harkentest::monitor::IdentityRecord> records;
        harken::PlayableStartRequest request{};
        request.root = image.Root();
        const auto started = harken::StartPlayable(*engine, image.world, request);
        ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
        unsigned audibleStarts = 0;
        bool audible = false;
        for (unsigned block = 0; block < (cycles == 0 ? 8000u : 256u); ++block) {
            ASSERT_EQ(VN_OK, Vn_Update());
            harkentest::monitor::CollectIdentityEvents(capture, records);
            engine->nullBackend.Pump(1);
            const bool nextAudible = harkentest::Peak(engine->nullBackend.LastBlock(), 128) > 0.01f;
            audibleStarts += nextAudible && !audible;
            audible = nextAudible;
            ASSERT_LE(engine->playableInstances.LiveCount(), baseline + 8u);
            ASSERT_FALSE(engine->runtimeRecreateRequired);
        }
        const auto retiredLogical = std::count_if(records.begin(), records.end(), [&](const auto& record) {
            if (record.fact.factKind != VN_MONITOR_FACT_PLAYABLE_RETIRED ||
                record.header.stableId != image.children[0].playable.stableId) return false;
            EXPECT_EQ(VN_MONITOR_TERMINAL_NATURAL_COMPLETION, record.fact.terminalKind);
            EXPECT_EQ(started.instance, record.fact.root);
            return true;
        });
        if (cycles == 0) {
            EXPECT_GT(audibleStarts, engine->playableInstances.Capacity());
            EXPECT_GE(retiredLogical, audibleStarts - 1u);
            ASSERT_TRUE(engine->playableInstances.Classify(started.instance).live);
            ASSERT_TRUE(StopUntilStale(*engine, started.instance));
        } else {
            EXPECT_EQ(cycles, audibleStarts);
            EXPECT_EQ(cycles, retiredLogical);
            EXPECT_FALSE(engine->playableInstances.Classify(started.instance).live);
        }
        EXPECT_EQ(baseline, engine->playableInstances.LiveCount());
        EXPECT_EQ(0u, engine->voices.ActiveCount());
        EXPECT_EQ(VN_OK, Vn_MonitorCloseSession(capture));
    }
}

static void CheckQueueSuccessorPreservesEffectCut(bool actionEntry, bool signalOnly, bool outsideWindow) {
    harkentest::EngineSession session(harkentest::MakeNullConfig(4, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    ASSERT_EQ(VN_OK, Vn_CreateBus(harkentest::ObjectId(2), VN_BUS_MASTER));
    std::vector<float> first(outsideWindow ? engine->timelinePool.WindowEndFrame() + 256u : 512u, 0.25f);
    std::vector<float> second(first.size(), -0.25f);
    const auto firstPcm = harkentest::MonoDesc(first, 48000);
    const auto secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSecondSound, &secondPcm));
    SequenceQueueWorldImage image(engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision, harken::QueueCycleV1::Loop, false,
        signalOnly ? harken::AuthoredCompletionClassV1::SignalOnly
                   : harken::AuthoredCompletionClassV1::FiniteMediaCandidate,
        harken::SignalOnlyPolicyV1::StartNextAtEarliestSafeNoOverlap,
        harken::QueueSpliceV1::Butt, false, true);
    image.delayParams[0].valueBits = std::bit_cast<std::uint32_t>(-6.0206f);
    harken::SendV1 send{1, 0, harkentest::ObjectId(2), -6.0206f, 0};
    image.properties[0].payload.presentMask |= UINT64_C(0x80);
    image.properties[0].payload.sendCount = 1;
    image.properties[0].payload.sends = &send;
    const auto loopIndex = static_cast<std::uint32_t>(
        harken::playableproperties::PlayablePropertyIdV1::LoopCount) - 1u;
    image.properties[0].payload.presentMask |= UINT64_C(1) << loopIndex;
    image.properties[0].payload.values[loopIndex].bits = 2;
    image.properties[0].programSemanticFingerprint =
        harken::ComputePlayablePropertyFingerprintV1(image.properties[0]);
    image.children[0].playable.expectedProgramSemanticFingerprint = image.properties[0].programSemanticFingerprint;
    image.completionLeaves[0].content = image.children[0].playable;
    image.occurrences[0].childPlayable = image.children[0].playable;
    image.occurrences[0].occurrenceSemanticFingerprint =
        harken::ComputePlayableOccurrenceFingerprintV1(image.occurrences[0]);
    harken::PlayableInstanceHandle root = 0;
    VnActionFiringHandle firing = 0;
    harken::ActionStepProgramViewV1 step{};
    harken::ActionProgramViewV1 action{};
    if (actionEntry) {
        step.target = {harken::ActionTargetKindV1::Container, 0, kContainer,
                       image.container.programSemanticFingerprint};
        step.delay = {harken::AuthoredTimeDomainV1::AbsoluteNanoseconds, 0, 1};
        step.fade = step.delay;
        step.cooldown = step.delay;
        action.actionStableId = harkentest::ObjectId(10001);
        action.steps = &step;
        action.stepCount = 1;
        action.expandedStepOccurrenceCount = 1;
        action.expandedFiringCount = 1;
        action.programSemanticFingerprint = harken::ComputeActionProgramFingerprintV1(action);
        auto install = image.InstallView();
        install.actions = &action;
        install.actionCount = 1;
        install.identity.capabilityMask |= harken::kWorldCapabilityActionDefinitions;
        install.identity.runtimeSemanticFingerprint = harken::ComputeCurrentWorldFingerprintV4(install);
        ASSERT_EQ(harken::WorldInstallStatus::Ok, harken::InstallContainerWorldV1(*engine, install).status);
        VnPostActionDesc desc{};
        desc.structSize = sizeof(desc);
        desc.actionId = action.actionStableId;
        ASSERT_EQ(VN_OK, Vn_CreateEmitter(&desc.emitter));
        ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
        VnActionStepResult result{};
        result.structSize = sizeof(result);
        ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &result));
        root = result.producedPlayableInstance;
    } else {
        harken::PlayableStartRequest request{};
        request.root = image.Root();
        const auto started = harken::StartPlayable(*engine, image.world, request);
        ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
        root = started.instance;
    }
    ASSERT_NE(0u, root);
    auto row = std::find_if(engine->playableServices.begin(), engine->playableServices.end(),
        [root](const auto& candidate) { return candidate.rootInstance == root; });
    ASSERT_NE(engine->playableServices.end(), row);
    const auto firstRender = row->renderHandle;
    const auto queueToken = row->queueInstance;
    const auto* initialInstall = engine->ResolvePlayableServiceVoice(*row);
    ASSERT_NE(nullptr, initialInstall);
    ASSERT_EQ(1u, initialInstall->Input().effects.size());
    ASSERT_EQ(1u, initialInstall->Input().sends.size());
    ASSERT_EQ(2u, initialInstall->Facts().loopCount);
    bool heardFirst = false;
    bool heardSecond = false;
    bool heardFirstAgain = false;
    bool verifiedLaterEffect = false;
    bool heardLaterSend = false;
    std::uint64_t initialPositiveSamples = 0;
    bool deferred = false;
    for (std::uint32_t block = 0; block < 1024 && (!heardFirstAgain || !verifiedLaterEffect); ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        deferred = deferred || row->QueuePayload().queueCompletionFrame >= engine->timelinePool.WindowEndFrame();
        engine->nullBackend.Pump(1);
        if (row->frontierEntry.Valid()) {
            harken::TimelineArmObservation arm{};
            ASSERT_TRUE(engine->timelineArms.Observe(row->arm, &arm));
            if (arm.startedBlockSequence != 0)
                EXPECT_EQ(row->startFrame / engine->config.blockFrames + 1u, arm.startedBlockSequence);
        }
        const float* samples = engine->nullBackend.LastBlock();
        for (std::uint32_t index = 0; index < engine->config.blockFrames * engine->nullBackend.Channels(); ++index) {
            if (samples[index] > 0.0f) {
                if (!heardSecond) ++initialPositiveSamples;
                heardFirst = true;
                heardFirstAgain = heardFirstAgain || heardSecond;
                heardLaterSend = heardLaterSend || (heardSecond && samples[index] > 0.18f);
                EXPECT_LE(samples[index], 0.189f);
            } else if (samples[index] < 0.0f && heardFirst) {
                heardSecond = true;
            }
        }
        const auto* currentInstall = engine->ResolvePlayableServiceVoice(*row);
        if (currentInstall != nullptr && currentInstall->Facts().soundId == kSound &&
            row->renderHandle != firstRender && row->renderHandle != 0) {
            const auto input = currentInstall->Input();
            EXPECT_EQ(1u, input.effects.size());
            ASSERT_EQ(1u, input.sends.size());
            EXPECT_EQ(2u, currentInstall->Facts().loopCount);
            EXPECT_EQ(harkentest::ObjectId(2u), input.sends[0].targetBusId);
            EXPECT_FLOAT_EQ(-6.0206f, input.sends[0].levelDb);
            const auto* voice = engine->voices.Resolve(row->renderHandle);
            if (voice != nullptr && voice->fxSlots[0].process != nullptr && voice->voiceSendActiveCount == 1u) {
                EXPECT_EQ(engine->buses.FindRef(harkentest::ObjectId(2)).index, voice->voiceSends[0].targetBusIndex);
                EXPECT_TRUE(voice->voiceSends[0].active);
                verifiedLaterEffect = true;
            }
        }
    }
    EXPECT_TRUE(heardFirst);
    EXPECT_TRUE(heardSecond);
    EXPECT_TRUE(heardFirstAgain);
    EXPECT_TRUE(verifiedLaterEffect);
    EXPECT_TRUE(heardLaterSend);
    EXPECT_GT(initialPositiveSamples, first.size() * engine->nullBackend.Channels());
    if (outsideWindow) EXPECT_TRUE(deferred);
    EXPECT_FALSE(engine->runtimeRecreateRequired);
    if (engine->playableInstances.Classify(root).live)
        ASSERT_EQ(harken::PlayableControlStatus::Ok, harken::StopPlayable(*engine, root, 0));
    for (std::uint32_t block = 0; block < 32; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    ASSERT_EQ(VN_OK, Vn_Update());
    harken::QueueInstanceSnapshot remainingQueue{};
    const bool remaining = engine->queueInstances.Capture(queueToken, &remainingQueue);
    EXPECT_FALSE(remaining);
    EXPECT_EQ(0u, engine->queueInstances.LiveCount());
    EXPECT_FALSE(engine->playableInstances.Classify(root).live);
    if (actionEntry) EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
}

TEST(PlayableStart, DirectKnownQueueSuccessorRetainsItsEffectCut) {
    CheckQueueSuccessorPreservesEffectCut(false, false, false);
}

TEST(PlayableStart, ActionKnownQueueSuccessorRetainsItsEffectCut) {
    CheckQueueSuccessorPreservesEffectCut(true, false, false);
}

TEST(PlayableStart, DirectSignalQueueSuccessorRetainsItsEffectCut) {
    CheckQueueSuccessorPreservesEffectCut(false, true, false);
}

TEST(PlayableStart, ActionSignalQueueSuccessorRetainsItsEffectCut) {
    CheckQueueSuccessorPreservesEffectCut(true, true, false);
}

TEST(PlayableStart, DirectDistantQueueSuccessorRetainsItsEffectCut) {
    CheckQueueSuccessorPreservesEffectCut(false, false, true);
}

TEST(PlayableStart, ActionDistantQueueSuccessorRetainsItsEffectCut) {
    CheckQueueSuccessorPreservesEffectCut(true, false, true);
}

TEST(PlayableStart, SequenceQueueResumeReplaysExactCheckpointCurrentAndClearsAtEnd) {
    VnConfig config = harkentest::MakeNullConfig(2, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(session.InitResult(), VN_OK);
    harken::Engine* engine = session.Engine();
    ASSERT_NE(engine, nullptr);

    std::vector<float> first(96, 0.25f);
    std::vector<float> second(96, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(Vn_RegisterPCM(kSound, &firstPcm), VN_OK);
    ASSERT_EQ(Vn_RegisterPCM(kSecondSound, &secondPcm), VN_OK);
    SequenceQueueWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision,
        harken::QueueCycleV1::Once, true);
    VnEmitterHandle emitter = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&emitter));

    harken::QueueCheckpointKey key{};
    key.world = image.world.generation;
    key.containerStableId = image.container.containerStableId;
    key.programSemanticFingerprint =
        image.container.programSemanticFingerprint;
    key.resetEpoch = 1;
    key.emitterSlot = static_cast<std::uint32_t>(emitter);
    key.emitterGeneration = static_cast<std::uint32_t>(emitter >> 32);
    harken::QueueCheckpointImage checkpoint{};
    checkpoint.effective.version = 7;
    checkpoint.effective.cursor = 1;
    checkpoint.effective.currentChildOrdinal =
        image.children[1].stableChildOrdinal;
    checkpoint.effective.selectionOrdinal = 3;
    checkpoint.replayCurrent = true;
    ASSERT_TRUE(engine->queueCheckpoints.Store(key, checkpoint));

    harken::PlayableStartRequest request{};
    request.root = image.Root();
    request.emitter = emitter;
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);

    bool heardNegative = false;
    bool heardPositive = false;
    for (std::uint32_t block = 0; block < 24; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        const float* output = engine->nullBackend.LastBlock();
        for (std::uint32_t sample = 0;
             sample < 2u * engine->config.blockFrames; ++sample) {
            heardNegative = heardNegative || output[sample] < 0.0f;
            heardPositive = heardPositive || output[sample] > 0.0f;
        }
    }
    EXPECT_TRUE(heardNegative);
    EXPECT_FALSE(heardPositive);
    EXPECT_EQ(0u, engine->queueCheckpoints.LiveCount());
    EXPECT_EQ(VN_OK, Vn_DestroyEmitter(emitter));
}

