TEST(PlayableStart, SequenceQueueStopThenSequenceStartAcceptsWhenQueryStale) {
    VnConfig config = harkentest::MakeNullConfig(2, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(session.InitResult(), VN_OK);
    harken::Engine* engine = session.Engine();
    ASSERT_NE(engine, nullptr);

    std::vector<float> first(4096, 0.25f);
    std::vector<float> second(32768, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(Vn_RegisterPCM(kSound, &firstPcm), VN_OK);
    ASSERT_EQ(Vn_RegisterPCM(kSecondSound, &secondPcm), VN_OK);
    SequenceQueueWorldImage queueImage(
        engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision);

    harken::PlayableStartRequest queueRequest{};
    queueRequest.root = queueImage.Root();
    ASSERT_EQ(harken::InstallContainerWorldV1(*engine, queueImage.InstallView())
                  .status,
              harken::WorldInstallStatus::Ok);
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, queueRequest);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    ASSERT_NE(started.instance, 0u);
    ASSERT_TRUE(PumpUntilAudible(*engine));
    bool mixAheadPrepared = false;
    for (std::uint32_t block = 0; block < 64; ++block) {
        mixAheadPrepared = std::any_of(
            engine->playableServices.begin(), engine->playableServices.end(),
            [&](const harken::EnginePlayableServiceRow& row) {
                return row.rootInstance == started.instance &&
                       (row.queueContinuationPrepared ||
                        row.pendingFutureCount != 0 ||
                        row.QueuePayload().queuePreparedPages.generation != 0);
            });
        if (mixAheadPrepared) {
            break;
        }
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    EXPECT_TRUE(mixAheadPrepared);

    std::uint64_t queueStartFrame = 0;
    for (const harken::EnginePlayableServiceRow& row : engine->playableServices) {
        if (row.rootInstance == started.instance &&
            row.phase != harken::EnginePlayableStartPhase::Free) {
            queueStartFrame = row.startFrame;
            break;
        }
    }
    const std::uint32_t blockFrames = engine->config.blockFrames;
    const std::uint64_t firstDoneFrame =
        queueStartFrame + static_cast<std::uint64_t>(first.size()) +
        static_cast<std::uint64_t>(blockFrames) * 8u;
    harken::PlayableControlState state{};
    harken::PlayableControlStatus query =
        harken::QueryPlayable(*engine, started.instance, &state);
    for (std::uint32_t block = 0; block < 512; ++block) {
        query = harken::QueryPlayable(*engine, started.instance, &state);
        ASSERT_EQ(harken::PlayableControlStatus::Ok, query)
            << "query=" << static_cast<int>(query)
            << " lifecycle=" << static_cast<int>(state.lifecycle)
            << " reason=" << static_cast<int>(state.reason)
            << " live=" << state.childLiveCount
            << " retiring=" << state.childAudibleRetiringCount
            << " pending=" << state.pendingFutureCount
            << " blocks=" << engine->mixer.BlocksRendered();
        if (engine->mixer.BlocksRendered() * blockFrames >= firstDoneFrame) {
            break;
        }
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    query = harken::QueryPlayable(*engine, started.instance, &state);
    ASSERT_EQ(harken::PlayableControlStatus::Ok, query)
        << "lifecycle=" << static_cast<int>(state.lifecycle)
        << " reason=" << static_cast<int>(state.reason);
    harken::PlayableControlStatus stop =
        harken::StopPlayable(*engine, started.instance, 0);
    for (std::uint32_t block = 0; block < 256; ++block) {
        if (stop == harken::PlayableControlStatus::Backpressure) {
            stop = harken::StopPlayable(*engine, started.instance, 0);
        }
        query = harken::QueryPlayable(*engine, started.instance, &state);
        if (query == harken::PlayableControlStatus::StaleHandle ||
            query == harken::PlayableControlStatus::InvalidHandle) {
            break;
        }
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    const harken::EnginePlayableServiceRow* queueRow = nullptr;
    for (const harken::EnginePlayableServiceRow& row : engine->playableServices) {
        if (row.rootInstance == started.instance &&
            row.phase != harken::EnginePlayableStartPhase::Free) {
            queueRow = &row;
            break;
        }
    }
    ASSERT_TRUE(query == harken::PlayableControlStatus::StaleHandle ||
                query == harken::PlayableControlStatus::InvalidHandle)
        << "query=" << static_cast<int>(query)
        << " lifecycle=" << static_cast<int>(state.lifecycle)
        << " reason=" << static_cast<int>(state.reason)
        << " stop=" << static_cast<int>(stop)
        << " arrival=" << (queueRow && queueRow->queueArrivalDecision.Valid())
        << " continuation=" << (queueRow && queueRow->queueContinuationPrepared)
        << " phase=" << (queueRow ? static_cast<int>(queueRow->phase) : -1);

    ASSERT_TRUE(WaitUntilReclaimed(*engine, started.instance));
    const bool queueRowHeld = std::any_of(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& row) {
            return row.phase != harken::EnginePlayableStartPhase::Free &&
                   row.rootInstance == started.instance;
        });
    EXPECT_FALSE(queueRowHeld);
    EXPECT_EQ(
        engine->timelinePool.PreflightSingleEvent(
            engine->timelinePool.PublishCutoffFrame(),
            engine->timelinePool.PublishCutoffFrame()),
        harken::ReserveRefusal::None)
        << "ingress=" << engine->timelinePool.IngressThisQuantum()
        << " live=" << engine->timelinePool.LiveTransactionCount();

    PlayableWorldImage sequenceImage(
        engine->registry.Lookup(kSound).contentRevision,
        harken::ContainerModeV1::Sequence);
    harken::PlayableWorldViewV1 sequenceWorld{};
    sequenceWorld.generation = 1;
    sequenceWorld.identity = sequenceImage.world.identity;
    sequenceWorld.properties = sequenceImage.world.playableProperties;
    sequenceWorld.propertyCount = sequenceImage.world.playablePropertyCount;
    sequenceWorld.occurrences = sequenceImage.world.playableOccurrences;
    sequenceWorld.occurrenceCount =
        sequenceImage.world.playableOccurrenceCount;
    sequenceWorld.containers = sequenceImage.world.containers;
    sequenceWorld.containerCount = sequenceImage.world.containerCount;
    harken::PlayableStartRequest sequenceRequest{};
    sequenceRequest.root = sequenceImage.Root();
    const harken::PlayableStartResult next =
        harken::StartPlayable(*engine, sequenceWorld, sequenceRequest);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, next.status)
        << "recreate=" << engine->runtimeRecreateRequired
        << " ingress=" << engine->timelinePool.IngressThisQuantum()
        << " live=" << engine->timelinePool.LiveTransactionCount();
    EXPECT_NE(next.instance, 0u);
    EXPECT_NE(next.instance, started.instance);
}

TEST(PlayableStart, RandomQueueListenThenSequenceStartAccepts) {
    VnConfig config = harkentest::MakeNullConfig(4, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(session.InitResult(), VN_OK);
    harken::Engine* engine = session.Engine();
    ASSERT_NE(engine, nullptr);

    std::vector<float> first(4096, 0.25f);
    std::vector<float> second(32768, -0.25f);
    std::vector<float> third(32768, 0.125f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    const VnPCMDesc thirdPcm = harkentest::MonoDesc(third, 48000);
    ASSERT_EQ(Vn_RegisterPCM(kSound, &firstPcm), VN_OK);
    ASSERT_EQ(Vn_RegisterPCM(kSecondSound, &secondPcm), VN_OK);
    ASSERT_EQ(Vn_RegisterPCM(kThirdSound, &thirdPcm), VN_OK);
    const std::array<std::uint64_t, 3> revisions = {
        engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision,
        engine->registry.Lookup(kThirdSound).contentRevision};
    RandomQueueWorldImage queueImage(revisions);
    VnEmitterHandle emitter = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&emitter));
    harken::PlayableStartRequest queueRequest{};
    queueRequest.root = queueImage.Root();
    queueRequest.emitter = emitter;
    queueRequest.callerSeed = 77;
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, queueImage.world, queueRequest);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    ASSERT_NE(started.instance, 0u);
    ASSERT_TRUE(PumpUntilAudible(*engine));

    std::uint64_t queueStartFrame = 0;
    for (const harken::EnginePlayableServiceRow& row : engine->playableServices) {
        if (row.rootInstance == started.instance &&
            row.phase != harken::EnginePlayableStartPhase::Free) {
            queueStartFrame = row.startFrame;
            break;
        }
    }
    const std::uint32_t blockFrames = engine->config.blockFrames;
    const std::uint64_t firstDoneFrame =
        queueStartFrame + static_cast<std::uint64_t>(first.size()) +
        static_cast<std::uint64_t>(blockFrames) * 8u;
    harken::PlayableControlState state{};
    harken::PlayableControlStatus query =
        harken::QueryPlayable(*engine, started.instance, &state);
    for (std::uint32_t block = 0; block < 1024; ++block) {
        query = harken::QueryPlayable(*engine, started.instance, &state);
        if (query == harken::PlayableControlStatus::StaleHandle ||
            query == harken::PlayableControlStatus::InvalidHandle) {
            break;
        }
        if (engine->mixer.BlocksRendered() * blockFrames >= firstDoneFrame) {
            break;
        }
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    harken::PlayableControlStatus stop = harken::PlayableControlStatus::Ok;
    if (query == harken::PlayableControlStatus::Ok) {
        stop = harken::StopPlayable(*engine, started.instance, 0);
    }
    for (std::uint32_t block = 0; block < 256; ++block) {
        if (stop == harken::PlayableControlStatus::Backpressure) {
            stop = harken::StopPlayable(*engine, started.instance, 0);
        }
        query = harken::QueryPlayable(*engine, started.instance, &state);
        if (query == harken::PlayableControlStatus::StaleHandle ||
            query == harken::PlayableControlStatus::InvalidHandle) {
            break;
        }
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    ASSERT_TRUE(query == harken::PlayableControlStatus::StaleHandle ||
                query == harken::PlayableControlStatus::InvalidHandle)
        << "query=" << static_cast<int>(query)
        << " lifecycle=" << static_cast<int>(state.lifecycle)
        << " reason=" << static_cast<int>(state.reason)
        << " stop=" << static_cast<int>(stop);
    const std::uint64_t horizonFrames =
        engine->timelinePool.WindowEndFrame() -
        engine->timelinePool.WindowStartFrame();
    const std::uint32_t extraBlocks =
        blockFrames == 0
            ? 8u
            : static_cast<std::uint32_t>(horizonFrames / blockFrames) + 8u;
    for (std::uint32_t block = 0; block < extraBlocks; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    const std::uint64_t cutoff = engine->timelinePool.PublishCutoffFrame();
    const std::uint64_t leadFrames =
        static_cast<std::uint64_t>(engine->timelinePool.PublishLeadQuanta()) *
        blockFrames;
    const std::uint64_t observedFrame =
        engine->mixer.BlocksRendered() * blockFrames;
    const std::uint64_t startFrame =
        observedFrame > UINT64_MAX - leadFrames
            ? UINT64_MAX
            : std::max(cutoff, observedFrame + leadFrames);
    EXPECT_EQ(
        engine->timelinePool.PreflightSingleEvent(startFrame, cutoff),
        harken::ReserveRefusal::None)
        << "start=" << startFrame << " cutoff=" << cutoff
        << " base=" << engine->timelinePool.WindowStartFrame()
        << " end=" << engine->timelinePool.WindowEndFrame()
        << " blocked=" << engine->timelinePool.AdvanceBlockedByConsumer()
        << " ingress=" << engine->timelinePool.IngressThisQuantum()
        << " live=" << engine->timelinePool.LiveTransactionCount();

    PlayableWorldImage sequenceImage(
        engine->registry.Lookup(kSound).contentRevision,
        harken::ContainerModeV1::Sequence);
    harken::PlayableWorldViewV1 sequenceWorld{};
    sequenceWorld.generation = 1;
    sequenceWorld.identity = sequenceImage.world.identity;
    sequenceWorld.properties = sequenceImage.world.playableProperties;
    sequenceWorld.propertyCount = sequenceImage.world.playablePropertyCount;
    sequenceWorld.occurrences = sequenceImage.world.playableOccurrences;
    sequenceWorld.occurrenceCount =
        sequenceImage.world.playableOccurrenceCount;
    sequenceWorld.containers = sequenceImage.world.containers;
    sequenceWorld.containerCount = sequenceImage.world.containerCount;
    harken::PlayableStartRequest sequenceRequest{};
    sequenceRequest.root = sequenceImage.Root();
    const harken::PlayableStartResult next =
        harken::StartPlayable(*engine, sequenceWorld, sequenceRequest);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, next.status)
        << "recreate=" << engine->runtimeRecreateRequired
        << " ingress=" << engine->timelinePool.IngressThisQuantum()
        << " live=" << engine->timelinePool.LiveTransactionCount();
    EXPECT_NE(next.instance, 0u);
}

