TEST(PlayableStart, SequenceLoopSuccessorContentRevisionInvalidates) {
    VnConfig config = harkentest::MakeNullConfig(4, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    const std::uint32_t instanceBaseline =
        engine->playableInstances.LiveCount();
    const std::uint32_t containerBaseline =
        engine->containerPlayback.LiveCount();
    const std::uint32_t armBaseline = engine->timelineArms.LiveCount();
    const std::uint32_t voiceBaseline = engine->voices.ActiveCount();
    const std::uint32_t selectionFreeBaseline =
        engine->selectionMemory.FreeDeltaCount();
    std::vector<float> first(64, 0.25f);
    std::vector<float> second(64, -0.5f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSecondSound, &secondPcm));
    TwoChildPlayableWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision,
        harken::ContainerModeV1::Sequence);
    image.SetContainerLoopCount(2);
    harken::PlayableWorldViewV1 frozenWorld{};
    frozenWorld.generation = 1;
    frozenWorld.identity = image.world.identity;
    frozenWorld.properties = image.world.playableProperties;
    frozenWorld.propertyCount = image.world.playablePropertyCount;
    frozenWorld.occurrences = image.world.playableOccurrences;
    frozenWorld.occurrenceCount = image.world.playableOccurrenceCount;
    frozenWorld.containers = image.world.containers;
    frozenWorld.containerCount = image.world.containerCount;
    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, frozenWorld, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    const harken::EnginePlayableServiceRow* row =
        FindPlayableRow(*engine, started.instance);
    ASSERT_NE(nullptr, row);
    harken::ContainerPlaybackRow initialPlayback{};
    ASSERT_TRUE(engine->containerPlayback.Capture(started.instance, &initialPlayback));
    const harken::TimelineArmToken firstArm = row->arm;
    const harken::PlayableInstanceHandle firstLeaf = row->activeLeafInstance;
    const std::uint64_t firstFrame = row->startFrame;
    const std::uint32_t completedBefore = initialPlayback.completedSelections;
    const std::uint32_t iterationBefore = row->containerLoopIteration;
    ASSERT_TRUE(firstArm.Valid());
    ASSERT_NE(0u, firstLeaf);

    image.properties[2].programSemanticFingerprint ^= UINT64_C(1);
    bool invalidated = false;
    harken::PlayableControlState state{};
    for (std::uint32_t block = 0; block < 64 && !invalidated; ++block) {
        ASSERT_TRUE(PumpBlocks(*engine, 1));
        invalidated =
            harken::QueryPlayable(*engine, started.instance, &state) ==
                harken::PlayableControlStatus::Ok &&
            state.lifecycle ==
                harken::PlayableControlLifecycle::FailingSourceActive &&
            state.reason == harken::PlayableControlReason::ContentRevision;
    }
    ASSERT_TRUE(invalidated);
    EXPECT_NE(harken::PlayableControlLifecycle::LogicalComplete,
              state.lifecycle);
    EXPECT_NE(harken::PlayableControlReason::Natural, state.reason);
    row = FindPlayableRow(*engine, started.instance);
    ASSERT_NE(nullptr, row);
    EXPECT_EQ(firstArm.slot, row->arm.slot);
    EXPECT_EQ(firstArm.generation, row->arm.generation);
    EXPECT_EQ(firstArm.renderSlot, row->arm.renderSlot);
    EXPECT_EQ(firstArm.renderGeneration, row->arm.renderGeneration);
    EXPECT_EQ(firstLeaf, row->activeLeafInstance);
    EXPECT_EQ(firstFrame, row->startFrame);
    harken::ContainerPlaybackRow invalidatedParent{};
    ASSERT_TRUE(engine->containerPlayback.Capture(started.instance, &invalidatedParent));
    EXPECT_EQ(completedBefore + 1u, invalidatedParent.completedSelections);
    EXPECT_EQ(iterationBefore, row->containerLoopIteration);
    EXPECT_EQ(0u, engine->playableInstances.NextSibling(firstLeaf));

    bool stale = false;
    bool unexpectedSuccessor = false;
    for (std::uint32_t block = 0; block < 96 && !stale; ++block) {
        if (engine->playableInstances.Classify(firstLeaf).live) {
            unexpectedSuccessor = unexpectedSuccessor ||
                engine->playableInstances.NextSibling(firstLeaf) != 0u;
        }
        ASSERT_TRUE(PumpBlocks(*engine, 1));
        const harken::PlayableControlStatus query =
            harken::QueryPlayable(*engine, started.instance, &state);
        stale = query == harken::PlayableControlStatus::StaleHandle ||
            query == harken::PlayableControlStatus::InvalidHandle;
    }
    EXPECT_FALSE(unexpectedSuccessor);
    EXPECT_TRUE(stale);
    ASSERT_TRUE(PumpBlocks(*engine, 8));
    EXPECT_EQ(instanceBaseline, engine->playableInstances.LiveCount());
    EXPECT_EQ(containerBaseline, engine->containerPlayback.LiveCount());
    EXPECT_EQ(armBaseline, engine->timelineArms.LiveCount());
    EXPECT_EQ(voiceBaseline, engine->voices.ActiveCount());
    EXPECT_EQ(selectionFreeBaseline, engine->selectionMemory.FreeDeltaCount());
    EXPECT_FALSE(engine->runtimeRecreateRequired);
}

TEST(PlayableStart, SequenceEmitterLoopCountTwoPlaysTwoChildren) {
    VnConfig config = harkentest::MakeNullConfig(4, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    std::vector<float> first(64, 0.25f);
    std::vector<float> second(64, -0.5f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSecondSound, &secondPcm));
    TwoChildPlayableWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision,
        harken::ContainerModeV1::Sequence);
    image.container.memoryScope = harken::MemoryScopeV1::Emitter;
    image.SetContainerLoopCount(2);
    ASSERT_EQ(harken::InstallContainerWorldV1(*engine, image.world).status,
              harken::WorldInstallStatus::Ok);
    VnEmitterHandle emitter = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&emitter));
    harken::PlayableStartRequest request{};
    request.root = image.Root();
    request.emitter = emitter;
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    const auto root = engine->playableInstances.Classify(started.instance);
    ASSERT_TRUE(root.live);
    const auto firstSound = root.firstChild;
    ASSERT_NE(firstSound, 0u);
    bool observedSecondLeaf = false;
    bool heardPositive = false;
    bool heardNegative = false;
    for (std::uint32_t block = 0; block < 32; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        const auto secondSound =
            engine->playableInstances.NextSibling(firstSound);
        if (secondSound != 0u) {
            const auto secondSoundView =
                engine->playableInstances.Classify(secondSound);
            observedSecondLeaf = observedSecondLeaf ||
                (secondSound != firstSound && secondSoundView.live &&
                 secondSoundView.kind == harken::PlayableKind::Sound &&
                 secondSoundView.parent == started.instance);
        }
        const float* output = engine->nullBackend.LastBlock();
        heardPositive = heardPositive || std::any_of(
            output, output + 2u * engine->config.blockFrames,
            [](float sample) { return sample > 0.1f; });
        heardNegative = heardNegative || std::any_of(
            output, output + 2u * engine->config.blockFrames,
            [](float sample) { return sample < -0.1f; });
    }
    EXPECT_TRUE(observedSecondLeaf);
    EXPECT_TRUE(heardPositive);
    EXPECT_TRUE(heardNegative);
    EXPECT_FALSE(engine->runtimeRecreateRequired);
    ASSERT_TRUE(StopUntilStale(*engine, started.instance));
    EXPECT_EQ(0u, engine->playableInstances.LiveCount());
    EXPECT_EQ(0u, engine->containerPlayback.LiveCount());
    EXPECT_EQ(VN_OK, Vn_DestroyEmitter(emitter));
}

