TEST(PlayableStart, BlendResponseRetainsEveryInitialMemberIncludingSilentRows) {
    for (const bool live : {false, true}) {
        SCOPED_TRACE(live);
        harkentest::EngineSession session(harkentest::MakeNullConfig(8, 256, 48000));
        ASSERT_EQ(VN_OK, session.InitResult());
        auto* engine = session.Engine();
        std::vector<float> samples(48000, 0.1f);
        const auto pcm = harkentest::MonoDesc(samples, 48000);
        ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &pcm));
        const harken::VariableDefinitionV1 variable = {
            harkentest::ObjectId(41), harken::VariableKindV1::Smooth, 0.0f, 8.0f, 3.0f};
        ASSERT_EQ(harken::WorldInstallStatus::Ok,
            harkentest::InstallDefinitionsWorld(engine, &variable, 1).status);
        VariableControlMembershipWorldImage image(engine->registry.Lookup(kSound).contentRevision,
            engine->variables.CurrentWorldGeneration());
        image.container.maxActiveRows = 2;
        image.container.continuousTiming = live ? 1u : 0u;
        image.container.evaluationPeriodFrames = live ? 64u : 0u;
        harken::PlayableStartRequest request{};
        request.root = image.Root();
        const auto started = harken::StartPlayable(*engine, image.world, request);
        ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
        ASSERT_TRUE(PumpUntilAudible(*engine));
        const auto row = std::find_if(engine->playableServices.begin(), engine->playableServices.end(),
            [&](const auto& candidate) { return candidate.rootInstance == started.instance; });
        ASSERT_NE(engine->playableServices.end(), row);
        ASSERT_EQ(2u, row->variableControlContinuousMemberCount);
        std::array<VnVoiceHandle, 2> renders{};
        for (unsigned index = 0; index < renders.size(); ++index) {
            std::size_t slot = 0;
            ASSERT_TRUE(engine->ResolvePlayableMemberSlot(row->scheduleStorageBase +
                row->variableControlContinuousMemberOffset + index, &slot));
            renders[index] = engine->ReadPlayableMember(slot).render;
            const auto* voice = engine->voices.Resolve(renders[index]);
            ASSERT_NE(nullptr, voice);
            const auto* weight = FrontierOwnedVariableWeight(*voice, *row);
            ASSERT_NE(nullptr, weight);
            EXPECT_FLOAT_EQ(index == 0 ? 1.0f : 0.0f, weight->segment.endWeight);
        }
        for (const float value : {7.0f, 4.5f, 3.0f}) {
            ASSERT_EQ(VN_OK, Vn_SetValue(variable.variableId, value));
            for (unsigned block = 0; block < 32; ++block) {
                ASSERT_EQ(VN_OK, Vn_Update());
                engine->nullBackend.Pump(1);
                ASSERT_FALSE(engine->runtimeRecreateRequired);
            }
            ASSERT_EQ(2u, engine->voices.ActiveCount());
            ASSERT_TRUE(engine->playableInstances.Classify(started.instance).live);
            for (unsigned index = 0; index < renders.size(); ++index) {
                const auto* voice = engine->voices.Resolve(renders[index]);
                ASSERT_NE(nullptr, voice);
                const auto* weight = FrontierOwnedVariableWeight(*voice, *row);
                ASSERT_NE(nullptr, weight);
                const float expected = live ? (index == 0 ? value < 4.0f : value > 5.0f)
                    : index == 0;
                EXPECT_FLOAT_EQ(expected, weight->segment.endWeight);
            }
        }
        for (unsigned block = 0; block < 240; ++block) {
            ASSERT_EQ(VN_OK, Vn_Update());
            engine->nullBackend.Pump(1);
        }
        EXPECT_EQ(0u, engine->voices.ActiveCount());
        EXPECT_EQ(0u, engine->playableInstances.LiveCount());
        EXPECT_FALSE(engine->runtimeRecreateRequired);
    }
}

