            containers[0] = image.container;
            auto& blend = containers[1];
            blend.containerStableId = properties[4].stableId;
            blend.authoredStableOrder = 4;
            blend.programSemanticFingerprint = properties[4].programSemanticFingerprint;
            blend.mode = harken::ContainerModeV1::VariableControl;
            blend.memoryScope = harken::MemoryScopeV1::Emitter;
            blend.childCount = 1;
            blend.children = &child;
            blend.continuousAxisCount = 1;
            blend.continuousAxes = &axis;
            blend.continuousRowCount = 1;
            blend.continuousRows = &grid;
            blend.curveCount = 1;
            blend.curves = &weightCurve;
            blend.continuousTiming = live ? 1u : 0u;
            blend.evaluationPeriodFrames = live ? 64u : 0u;
