            properties[5].stableId = harkentest::ObjectId(2103);
            properties[5].authoredStableOrder = 5;
            properties[5].contentRevision = 3003;
            properties[5].compatibilityFingerprint = 6;
            properties[5].programSemanticFingerprint =
                harken::ComputePlayablePropertyFingerprintV1(properties[5]);
            const std::array<harken::VariableDefinitionV1, 2> variables{
                variable, harken::VariableDefinitionV1{
                    harkentest::ObjectId(42), harken::VariableKindV1::Step, 0.0f, 1.0f, 0.0f}};
            std::array<harken::ContainerChildProgramViewV2, 2> matchChildren{};
            matchChildren[0].stableChildOrdinal = 31;
